import scala.annotation.tailrec
import scala.collection.mutable.HashMap

object Main extends App {
  val mod = 1000000007
  val n = in.readInt
  val map = HashMap.empty[Long,Long]

  (2 to n).map(i => primeFact(i)).foreach(m => {
    m.foreach(e => addOrUpdate(map, e._1, e._2))
  })

  val ans = if(n == 1) 1 else {
    map.values./:(1L)((acc,v) => {
      val m = acc * (v + 1)
      if(m > mod) m % mod else m
    })
  }

  println(ans)

  @inline
  def addOrUpdate
    (map:HashMap[Long,Long], key:Long, value:Long):HashMap[Long,Long] =
  {
    if(map.contains(key)) map(key) += value
    else map += (key -> value)
    map
  }

  def primeFact(n:Long):Map[Long,Long] = {

    @tailrec
    def rec(acc:HashMap[Long,Long], num:Long, root:Long):Map[Long,Long] = {

      if(root * root > num) addOrUpdate(acc, num, 1).toMap
      else {
        if(num % root == 0L) rec(addOrUpdate(acc, root, 1), num/root, root)
        else rec(acc, num, root+1L)
      }
    }

    val ret = HashMap.empty[Long,Long]
    rec(ret, n, 2L)
  }
}

