typedef long long ll;
ll M = 1000000007;

map<ll, ll> prime_factor(ll n) {
	map<ll, ll> res;
	for (ll i = 2; i <= n; i++) {
		ll N = i;
		for (ll i = 2; i*i <= N; i++) {
			while (N%i == 0) {
				res[i]++;
				N /= i;
			}
		}
		if (N != 1)res[N]++;
	}

	return res;
}

int main() {
	ll N;
