	map<ll, ll> res;

	res = prime_factor(N);

	ll sum = 1;
	for (int i = 1; i <= N; i++) {
		if (res[i] > 0) {
			sum *= (res[i] + 1);
			sum %= M;
		}
	}

	cout << sum << endl;
}

