// 計算量 前処理:O(n) クエリ:O(1)
template <long long MOD = 1000000007, long long COMB_MAX = 1000000>
class mod_comb {
	std::array<ModInt<MOD>, COMB_MAX> fact;
	std::array<ModInt<MOD>, COMB_MAX> fact_inv;
	std::array<ModInt<MOD>, COMB_MAX> inv;

	public:
	constexpr mod_comb() : fact{}, fact_inv{}, inv{} {}

	constexpr int init() {
		this->fact[0] = this->fact[1] = 1;
		this->fact_inv[0] = this->fact_inv[1] = 1;
		this->inv[1] = 1;

		for(int i = 2; i < COMB_MAX; i++) {
			this->fact[i] = this->fact[i - 1] * i;
			this->inv[i] = MOD - (this->inv[MOD % i] * (MOD / i));
			this->fact_inv[i] = this->fact_inv[i - 1] * this->inv[i];
		}
		return 0;
	}

	constexpr ModInt<MOD> operator()(long long n, long long r) {
		if(n < r || n < 0 || r < 0) {
			return ModInt<MOD>(0);
		}

		if(this->fact[0] == 0) {
			this->init();
		}
		return fact[n] * fact_inv[r] * fact_inv[n - r];
	}
};

// 高速素因数分解
class Factor {
	std::vector<int> divisors;

	public:
	Factor(int n) : divisors(n, 0) {
		std::iota(this->divisors.begin(), this->divisors.end(), 0);
		for(int i = 2; i * i < n; i++) {
			if(this->divisors[i] != i) {
				continue;
			}
			this->divisors[i] = i;
			for(int j = i * i; j < n; j += i) {
				if(this->divisors[j] == j) {
					this->divisors[j] = i;
				}
			}
		}
	}

	std::unordered_map<int, size_t> operator()(int n) {
		std::unordered_map<int, size_t> factors;
		while(n != 1) {
			int divisor = this->divisors[n];
			while(n % divisor == 0) {
				factors[divisor]++;
				n /= divisor;
			}
		}
		return factors;
	}
};

// 約数列挙
template <typename T>
std::vector<T> divisor(T n) {
	std::vector<T> divisors;
	for(T i = 1; i * i <= n; i++) {
		if(n % i != 0) {
			continue;
		}
		divisors.push_back(i);
		if(i * i != n) {
			divisors.push_back(n / i);
		}
	}
	return divisors;
}

