// 素因数を数列で返す。ソートされている。
// first が素因数で second が個数
template <class T> map<T, long long> factring(T N) {
    map<T, long long> ans;
    int now = N;
    while (now != 1) {
        N           = now;
        long long i = 2;
        while (i * i <= N) {
            if (N % i == 0) {
                ans[i]++;
                N /= i;
            } else {
                i++;
            }
        }
        if (N != 1)
            ans[N]++;
        now--;
    }

    return ans;
};

