using namespace std;

typedef long long int ll;

const int div_num = 1000000007;
int N;
ll ans;
vector<bool> pt;

void make_pt(int n) {
	pt.resize(n + 1, (bool)true);
	pt[0] = pt[1] = false;
	for (int i = 4; i <= n; i += 2) pt[i] = false;
	int sqrt_max = (int)sqrt((double)n);
	for (int i = 2; i <= sqrt_max; ++i) {
		if (pt[i]) {
			for (int j = i * i; j <= n; j += i)
				pt[j] = false;
		}
	}
}

int calcu(int num, int div) {
	int p = 0;
	int x = num;
	while (true) {
		if (x % div != 0)
			break;
		x /= div;
		++p;
	}
	return p;
}

void solve(int n) {
	ans = 1;
	for (int i = 2; i <= n; ++i) {
		if (pt[i] != true)
			continue;
		int cnt = 0;
		for (int j = i; j <= n; ++j) {
			cnt += calcu(j, i);
		}
		if (cnt != 0) {
			ans = ans * (ll)(cnt + 1);
			ans = ans % div_num;
		}
	}
}

int main(void) {
	cin >> N;
	make_pt(N);

	solve(N);

	cout << ans << '\n';
	return 0;
}

