int prime_len = 4010101;
void setprime() {
    isprime = MALLOC(bool, prime_len);
    minfactor = MALLOC(int, prime_len);
    fill_n(isprime, prime_len, true);
    fill_n(minfactor, prime_len, 0);
    isprime[0] = isprime[1] = false;
    minfactor[0] = 0;
    minfactor[1] = 1;
    for (int i = 2; i <= sqrt(prime_len); ++i) {
        if (!isprime[i])continue;
        //iは素数
        for (int j = 2 * i; j < prime_len; j += i) {
            isprime[j] = false;
            if (minfactor[j] == 0)minfactor[j] = i;
        }
    }
    rep(i, prime_len) {
        if (isprime[i]) {
            minfactor[i] = i;
            primes.pb(i);
        }
    }
}
