vi divisors(int v) {
    vi res;
    double lim = std::sqrt(v);
    for (int i = 1; i <= lim; ++i) {
        if (v % i == 0) {
            res.pb(i);
            if (i != v / i)res.pb(v / i);
        }
    }
    return res;
}
vi factorization(int v) {
    int tv = v;
    vi res;
    if (!isprime)setprime();
    for (auto &&p :primes) {
        //osak法が使える
        if (v < prime_len) {
            //pはresに含まれていないので追加できる
            //backにすでにpが入っているか確認しなくていいため
            while (v > 1) {
                int p = minfactor[v];
                res.pb(p);
                while (v % p == 0) {
                    v /= p;
                }
            }
            break;
        }
        if (v % p == 0)res.push_back(p);
        while (v % p == 0) {
            v /= p;
        }
        if (v == 1 || p * p > tv)break;
    }
    if (v > 1)res.pb(v);
    return res;
}

vp factorization_count(int v) {
    int tv = v;
    vp res;
    if (!isprime)setprime();
    for (auto &&p :primes) {
        //osak法が使える
        if (v < prime_len) {
            //pはresに含まれていないので追加できる
            //backにすでにpが入っているか確認しなくていいため
            while (v > 1) {
                int p = minfactor[v];
                res.eb(p, 0);
                while (v % p == 0) {
                    v /= p;
                    res.back().second++;
                }
            }
            break;
        }
        if (v % p == 0)res.eb(p, 0);
        while (v % p == 0) {
            v /= p;
            res.back().second++;
        }
