void BreakDown(int n, int cnt[])
{
    while (n > 1)
    {
        bool devide = false;
        for (int i = 2; i <= n; ++i)
        {
            if (n % i == 0)
            {
                n /= i;
                ++cnt[i];
                devide = true;
                break;
            }
        }

        if (!devide)
        {
            ++cnt[n];
            break;
        }
    }
}

