template<typename T>
map<T, int> primeMap(T n) {
  map<T, int> mp;

  for(T i = 2; i <= n; i++){
    T x = i;
    for(T j = 2; x != 1; j++){
      int cnt = 0;
      while(x % j == 0){
        x /= j;
        cnt++;
      }
      if(cnt > 0) mp[j] += cnt;
    }
  }

  return mp;
}

