  constexpr int mod = 1e9 + 7;
  int n; cin >> n;

  map<int, int> mp = primeMap(n);

  ll ans = 1;
  for(const auto& x: mp){
    (ans *= x.second + 1) %= mod;
  }

  cout << ans << endl;

  return 0;
}

