using namespace std;

typedef long long ll;

vector<pair<ll, ll> > prime_factorize(ll n) {
  vector<pair<ll, ll> > res;

  for (ll p = 2; p * p <= n; p++) {
    if (n % p != 0) { continue; }
    int num = 0;
    while (n % p == 0) { ++num; n /= p; }
    res.push_back(make_pair(p, num));
  }

  if (n != 1) { res.push_back(make_pair(n, 1)); }
  return res;
}

// n! の約数の数を mod で割った余りを返す
ll mod_div_fact(ll n, ll mod) {
  map<ll, ll> mp;
  for (ll i = 2; i <= n; i++) {
    vector<pair<ll, ll> > v = prime_factorize(i);
    for (int i = 0; i < v.size(); i++) {
      ll prime = v[i].first;
      ll exp = v[i].second;

      mp[prime] += exp;
    }
  }
  ll res = 1;
  for (std::map<ll, ll>::iterator it = mp.begin(); it != mp.end(); it++) {
    res *= ((it->second) + 1);
    res %= mod;
  }
  return res;
}

const ll mod = int(1e9)+7;

