        Modint& operator+=(const Modint& p){
            if((x += p.x) >= MOD) x -= MOD;
            return *this;
        }

        Modint& operator-=(const Modint& p){
            if((x += MOD - p.x) >= MOD) x -= MOD;
            return *this;
        }

        Modint& operator*=(const Modint& p){
            x = x * p.x % MOD;
            return *this;
        }

        Modint& operator/=(const Modint& p){
            *this *= p.inverse();
            return *this;
        }

        Modint operator-() const {
            return Modint(-x);
        }

        Modint operator+(const Modint& p) const {
            return Modint(*this) += p;
        }

        Modint operator-(const Modint& p) const {
            return Modint(*this) -= p;
        }

        Modint operator*(const Modint& p) const {
            return Modint(*this) *= p;
        }

        Modint operator/(const Modint& p) const {
            return Modint(*this) /= p;
        }

        bool operator==(const Modint& p) const {
            return x == p.x;
        }

        bool operator!=(const Modint& p) const {
            return !(*this == p);
        }

        bool operator<(const Modint& p) const {
            return x < p.x;
        }

        bool operator>(const Modint& p) const {
            return x > p.x;
        }

        bool operator<=(const Modint& p) const {
            return !(*this > p);
        }

        bool operator>=(const Modint& p) const {
            return !(*this < p);
        }

        Modint inverse() const {
            long long a = x, b = MOD, u = 1, v = 0;
            while(b > 0){
                long long t = a / b;
                a -= t * b;
                swap(a, b);
                u -= t * v;
                swap(u, v);
            }
            return Modint(u);
        }

        Modint pow(long long n) const {
            Modint ret(1), mul(x);
            while(n > 0){
                if(n & 1) ret *= mul;
                mul *= mul;
                n >>= 1;
            }
            return ret;
        }

        friend ostream &operator<<(ostream& os, const Modint& p){
            return os << p.x;
        }

        friend istream &operator>>(istream& is, Modint& a){
            long long t;
            cin >> t;
            a = Modint<MOD>(t);
            return is;
        }

        explicit operator long long() const {
            return x;
        }

        static long long get_mod(){
            return MOD;
        }

    private:
        long long x;
};

auto smallestPrimeFactors(long long N){
    vector<long long> spf(N + 1);
    for(long long i = 0; i <= N; i++) spf[i] = i;
    for(long long i = 2; i * i <= N; i++){
        if(spf[i] != i) continue;
        for(long long j = i * i; j <= N; j += i){
            if(spf[j] == j) spf[j] = i;
        }
    }
    return spf;
}

auto factorization_spf(long long N, vector<long long>& spf){
    map<long long, long long> prime;
    while(N != 1){
        prime[spf[N]]++;
        N /= spf[N];
    }
    return prime;
}

signed main(){
    using mint = Modint<MOD>;
    ll N;
    cin >> N;
    mint ans = 1;
    map<ll, ll> prime;
    auto spf = smallestPrimeFactors(N);
    for(ll i = 2; i <= N; i++){
        auto mp = factorization_spf(i, spf);
        for(auto p : mp) prime[p.first] += p.second;
    }
    for(auto p : prime){
        ans *= mint(p.second + 1);
    }
    PRINT(ans);
    return 0;
}

