void Sieve()
{
	for(int i=3;i<=sqrt(S);i+=2)
	{
		if(!mark[i])
		{
			for(int j=i*i;j<=S;j+=(i*2))mark[j]=true;
		}
	}
	prime.push_back(2);
	for(int i=3;i<=S;i+=2)if(!mark[i])prime.push_back(i);
}

ll Fact_factorize ( int n ) 
{
	ll ans=1;
    for( int i = 0; i < prime.size() && prime[i] <= n; i++ ) 
    {
        int x = n;
        int freq = 0;

        while ( x / prime[i] ) {
            freq += x / prime[i];
            x = x / prime[i];
        }

 		freq++;
        ans=(ans*freq)%mod;
    }
    return ans;
}


