// Legendre's formula
// x! 을 나누는 p의 최대 exp를 반환한다.
int Legendre(int x, int p)
{
	int ret = 0;
	while(x > 0)
	{
		x /= p;
		ret += x;
	}
	return ret;
}

VI sieve()
{
	VB prime(n + 1, true);
	prime[0] = prime[1] = false;

	int m = sqrtl(n);
	for(int i = 2; i <= m; ++i)
		if(prime[i] == true)
			for(int j = i * i; j <= n; j += i)
				prime[j] = false;

	VI ret;
	for(int i = 2; i <= n; ++i)
		if(prime[i])
			ret.emplace_back(i);
	return ret;
}

int factDiv()
{
	VI prime = sieve();

	int ret = 1;
	for(auto p : prime)
	{
		int exp = Legendre(n, p);
		ret = mul(ret, exp + 1);
	}
	return ret;
}

