vector<pair<ll, ll>> prime_factor(ll n) {
	vector<pair<ll, ll>> vp; // {素数、個数}

	// iがsqrt(n)となるまで繰り返す
	for (ll i = 2; i*i <= n; i++) {
		if (n%i == 0) {  // iが素因数
			vp.emplace_back(i, 0);

			// 素因数の数を求める
			do {
				vp[vp.size() - 1].second++;
				n /= i;
			} while (n%i == 0);
		}
