const int mod = 1e9 + 7;

map < int, int > primes (int x) {
  map < int, int > res;
  for (int i = 2; i * i <= x; ++i) {
    while (x % i == 0) {
      x /= i;
      ++res[i];
    }
  }
  if (x != 1)
    ++res[x];
  return res;
}

