    map < int, int > here = primes(i);
    for (auto pr: here) 
      pows[pr.first] += pr.second;
  }
  int64_t ans = 1;
  for (auto pr: pows) 
    (ans *= (pr.second + 1)) %= mod;
  cout << ans << '\n';
}

