void Eratosthenes(int n) {  // n未満の素数を求める

    Prime[0] = Prime[1] = 0;
    for(int i = 2; i*i < n; i++) {
        if(Prime[i]) {
            for(int j = 2; i*j < n; j++) {
                Prime[i*j] = 0;
            }
        }
    }
}

int main() {
    int n;
    cin >> n;

    Eratosthenes(1000);

    vector<ll> e(1000, 1);  // e[i] : n!の素因数iの指数 + 1 (iが素数でないときは1)
    for(int i = 2; i <= n; i++) {
        int k = i;
        for(int j = 2; j*j <= n; j++) {
            if(Prime[j]) {
                while(k%j == 0) {
                    k /= j;
                    e[j]++;
                }
            }
        }
        if(k != 1) {
            e[k]++;
        }
    }

    ll ans = 1LL;
    rep(i, 1000) {
        ans *= e[i];
        ans %= mod;
    }

    cout << ans << endl;
    return 0;
}

