typedef long long ll;

pair<vector<ll>, vector<ll>> prime_factor_decomp(ll n) {
    vector<ll> p, e;
    ll m = n;
    for (ll i = 2; i * i <= n; i++) {
        if (m % i != 0){
            continue;
        }
        int c = 0;
        while (m % i == 0){
            c++;
            m /= i;
        }
        p.push_back(i);
        e.push_back(c);
    }
    if (m > 1) {
        p.push_back(m);
        e.push_back(1);
    }
    return make_pair(p, e);
}

int main(){
    ll n;
    cin >> n;
    set<ll> prime_factor;
    map<ll, ll> count_prime_factor;
    for (ll i=1; i<=n; ++i){
        pair<vector<ll>, vector<ll>> p = prime_factor_decomp(i);
        for (int j=0; j<(int)p.first.size(); ++j){
            if(prime_factor.find(p.first[j]) == prime_factor.end()){
                prime_factor.insert(p.first[j]);
                count_prime_factor.insert(make_pair(p.first[j], p.second[j]));
            }
            else {
                ll tmp = count_prime_factor.at(p.first[j]);
                count_prime_factor.erase(p.first[j]);
                count_prime_factor.insert(make_pair(p.first[j], tmp + p.second[j]));
            }
        }
    }
    ll ans = 1;
    const ll div = 1000000000 + 7;
    for (auto itr = prime_factor.begin(); itr != prime_factor.end(); ++itr){
        ll num = count_prime_factor.at(*itr);
        ans *= (num + 1);
        ans = ans % div;
    }
    cout << ans << endl;
    return 0;
}

