          crr = crr/i;
          isDivided = true;
          break;
        }
      }
      if ( !isDivided ){
        break;
      }
    }
  }

  long long ans = 1;
  for ( map<int,int>::iterator it = mp.begin(); it!=mp.end(); ++it){
    long long x = (it->second + 1) % mod;
    ans = ans * x % mod;
  }
  cout << ans << endl;

  return 0;
}

