ll count(ll n, ll m){
    ll ans = 0;
    while(n%m == 0){
        n = n/m;
        ans++;
    }
    return ans;
}

bool IsPrime(ll num){
    if(num < 2) return false;
    else if (num == 2) return true;
    else if (num % 2 == 0) return false;

    double sqrtNum = sqrt(num);
    for(ll i=3;i<=sqrtNum;i+=2){
        if(num % i == 0)
            return false;
    }
    return true;
}

int main(){
    ll N;
    cin >> N;

    ll ans = 1, c[N+1] = {};
    for(ll i=2;i<=N;i++){   // N! = 1*2*...*N
        for(ll j=2;j<=i;j++){   // 素因数
            if( IsPrime(j) )
                c[j] += count(i, j);
        }
    }

    for(int i=2;i<=N;i++){
        ans *= (c[i]+1);
        ans %= MOD;
    }

    cout << ans << endl;

}

