void prime_factor(long long num){
	long long bak = num;
	for(int i = 2; i*i <= num; i++){
		while(bak % i == 0){
			//i is prime
			prime[i]++;
			bak /= i;
		}
	}
	if(bak > 1){
		prime[bak]++;
		//bak is prime
	}
}


