	for(int i = 1; i <= N; i++){
		prime_factor(i);
	}
	long long ans = 1;
	for(map<long long,long long>::iterator it = prime.begin(); it != prime.end(); it++){
		ans *= (1 + it->second);
		ans %= DIV;
	}
	cout << ans << endl;
}

