void calc_prime(int x) {
	for (int i = 2; i <= x; i++) {
		for (int pi = 0; pi < index; pi++)
			if (i % Primes[pi] == 0)
				goto LoopEndPoint;
		Primes[index] = i;
		index++;
	LoopEndPoint:;
	}
}

std::vector<int> fact(int x) {
	std::vector<int> res;
	for (int i = 0; i <= 1010; i++) {
		if (x % Primes[i] == 0) {
			res.push_back(i);
			x /= Primes[i];
			i--;
		}
		if (x == 1) break;
	}
	return res;
}

