typedef __int128_t int128_t;
std::istream &operator>>(std::istream& input, int128_t& value) { // int128_tの入力。入力が64bitに収まる前提。
    long long tmp; input >> tmp; value = tmp;
    return input;
}
std::ostream &operator<<(std::ostream& output, const int128_t value) { // int128_tの出力。出力が64bitに収まる前提。
    output << (long long)value;
    return output;
}

int128_t cal_mod(const int128_t n, const int128_t mod) {
    // n % modを計算する。ただしmod <= 0 ならば何もしない。nが負の場合、正にして補正する。
    if (mod <= 0) {
        return n;
    } else if (0 <= n) {
        return n % mod;
    } else {
        int128_t tmp = (-n) / mod + 1;
        return (n + tmp * mod) % mod;
    }
}

int128_t pow_mod(int128_t x, int128_t n, const int128_t mod) {
    // 累乗の計算。mod <= 0ならば余りの計算は行わない。
    int128_t ret = 1;
    while (n > 0) {
        if (n & 1) { ret = cal_mod(ret * x, mod); }
        x = cal_mod(x * x, mod);
        n = (n >> 1);
    }
    return ret;
}

std::vector<std::pair<long long, int>> prime_factor(long long n) {
    // nの素因数分解。計算量はO(sqrt(n))なので、long longも入り得る。
    // intにおさまらない素数を入れた場合を考えて、keyはlong longにしておく。戻り値はintで十分と思われる。
    std::vector<std::pair<long long, int>> res;
    for (long long i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            int num = 0;
            while(n % i == 0) {
                num++;
                n = n / i;
            }
            res.push_back(std::pair<long long, int>({i, num}));
        }
    }
    if (n != 1) {
        res.push_back(std::pair<long long, int>({n, 1}));
    }
    return res;
}

const int MOD = 1e9 + 7;
int N;

int main(int argc, char **argv) {
    std::cin >> N;

    std::map<long long, int> mp;

    for (int i = 2; i <= N; i++) {
        std::vector<std::pair<long long, int>> fac = prime_factor(i);
        for (auto p : fac) {
            if (mp.find(p.first) == mp.end()) {
                mp[p.first] = p.second;
            } else {
                mp[p.first] += p.second;
            }
        }
    }

    int128_t ret = 1;
    for (auto itr = mp.begin(); itr != mp.end(); ++itr) {
        ret = (ret * (itr->second + 1)) % MOD;
    }

    std::cout << ret << std::endl;

    return 0;
}

