bool isprime(ll num) {
    if (num<2) return false;
    else if (num == 2) return true;
    else if (!(num%2)) return false;

    for (int i = 3; i*i <= num; i+=2) {
        if (!(num%i)) return false;
    }
    return true;
}

ll getexp(ll num, ll p) {
    ll ans = 0;
    while(!(num%p)) {
        ans++;
        num/=p;
    }
    return ans;
}

int main() {
    cin >> N;
    for (int i = 0; i < 1000; i++) if (isprime(i)) prime.push_back(i);
    ll pn = prime.size();
    primeex.resize(pn);
    for (int i = 1; i <= N; i++) {
        for (int j = 0; j < pn; j++) {
            primeex[j] += getexp(i,prime[j]);
        }
    }
    ll ans = 1;
    for (int i = 0; i < pn; i++) {
        ans *= primeex[i]+1;
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

