// エラトステネスの篩（素数は配列primeがfalseになる添え字）
void eratosthenes(int N) {
  prime[0] = prime[1] = true;
  for (int i = 2; i < sqrt(N); i++) {
    for (int j = i; i * j < N; j++) {
      prime[i*j] = true;
    }
  }
}

int main() {
