      if (prime[j]) continue;

      int c = 0;
      while (x % j == 0) {
        x /= j;
        c++;
      }
      cnt[j] += c;
    }
  }

  ll ans = 1;
  for (int i = 1; i <= N; i++) {
    ans *= cnt[i] + 1;
    ans %= MOD;
  }

  // 解答
  cout << ans << endl;

  return 0;
}

