vector<pair<ll, ll>> factorization_vector(ll n)
{
    vector<pair<ll, ll>> rtn;

    ll m = n;
    ll idx = 0;
    for (ll i = 2; i * i <= m; i++) {
        if (n % i != 0)
            continue;

        rtn.push_back({i,0});
        while (m % i == 0) {
            rtn[idx].second++;
            m /= i;
        }
        idx++;
    }
    if (m != 1) {
        rtn.push_back({m,1});
    }

    return rtn;
}

