// 約数の列挙
long long divisor(long long n){
  long long ans=0;
  for(long long i=1; i*i<=n; i++){
    if(n%i == 0){
      ans++;
      if(i != n/i){
        ans++;
      }
    }
  }
  return ans%MOD;
}
long long mul(long long n){
  if(n==1) return 1;
  return n*mul(n-1);
}

