int main()
{
    int N;
    scanf("%d", &N);

    long long ans = 1;
    std::unordered_map<int, int> dict;

    for (int i = 2; i < N + 1; i++) {
        int tmp = i;
        for (int j = 2; j < i + 1; j++) {
            while (true) {
                if (tmp % j == 0) {
                    if (dict.find(j) == dict.end()) {
                        dict[j] = 1;
                    } else {
                        dict.at(j) += 1;
                    }
                    tmp /= j;
                } else {
                    break;
                }
            }
            if (tmp == 1) {
                break;
            }
        }
    }

    for (auto itr = dict.begin(); itr != dict.end(); ++itr) {
        //        std::cout << "key = " << itr->first              // キーを表示
        //                 << ", val = " << itr->second << "\n";  // 値を表示
        ans *= (itr->second + 1);
        if (ans > 1000000007) {
            ans %= 1000000007;
        }
    }
    std::cout << (ans) << std::endl;
    return 0;
}

