int IsPrime(int n){
    for(int i=2;i*i<=n;i++){
        if(n%i == 0)
            return 0;
    }
    return 1;
}

int main(void){
    int n,primes[1000]={0},factors[1000]={0},nPrime=0;
    unsigned long long cnt=1;

    scanf("%d",&n);
    if(n==1){
        puts("1");
        return 0;
    }

    for(int i=2; i<=n; i++){
        if(IsPrime(i)){
            primes[nPrime++]=i;
        }
    }

    for(int i=2; i<=n; i++){
        int tmp=i;
        for(int j=0; primes[j]<=tmp && j<nPrime; j++){
            while(tmp%primes[j] == 0){
                //printf("tmp:%d p:%d\n",tmp,primes[j]);
                factors[j]++;
                tmp/=primes[j];
            }
        }
        //printf("%d\n",i);
    }
    for(int i=0;i<nPrime;i++){
        cnt *= factors[i]+1;
        cnt %= 1000000007ull;
    }
    printf("%llu\n",cnt);
    return 0;
}

