using namespace std;


class PrimeFactorization{
 private:
  vector<int> primes;

 public:
  PrimeFactorization(int N){
    bool ckecked[N+1];
    fill(ckecked, ckecked+N+1, false);

    for (int i = 2, len=sqrt(N)+1; i < len; ++i) {
      if(ckecked[i]) continue;

      for (int j = i*2; j <= N; j += i) {
        ckecked[j] = true;
      }
    }

    for (int i = 2; i <= N; ++i) {
      if(!ckecked[i]) {
        primes.push_back(i);
      }
    }
  }

  map<int, int> get_pairs(int n){
    map<int, int> prime_frq_map;

    int index_primes = 0;
    while(n > 1){
      int prime = primes[index_primes];

      if(n % prime != 0) {
        index_primes++;
        continue;
      }

      //
      n /= prime;

      //
      if(prime_frq_map.find(prime) == prime_frq_map.end()) {
        prime_frq_map[prime] = 1;
      }else{
        prime_frq_map[prime] += 1;
      }
    }

    return prime_frq_map;
  }


};



//
int main(){
  int n;
  cin >> n;
//  int n = 1000;
  long threshold = pow(10, 9) + 7;


  PrimeFactorization pe(n);
  map<int, int> all_prime_frq_map;

  for (int i = 2; i <= n; ++i) {
    map<int, int> prime_frq_map = pe.get_pairs(i);
    for (auto pair: prime_frq_map) {
      int prime = pair.first;
      int frq = pair.second;

      if(all_prime_frq_map.find(prime) == all_prime_frq_map.end()) {
        all_prime_frq_map[prime] = frq;
      }else{
        all_prime_frq_map[prime] += frq;
      }
    }
  }


  long long num_divisor = 1;
  for (auto pair: all_prime_frq_map) {
//    cout << pair.first << "  " << pair.second << endl;
    num_divisor *= (pair.second+1);
    if(threshold < num_divisor) num_divisor %= threshold;
  }

  cout << num_divisor << endl;

  return 0;
}

