// 高速素因数分解
class Factor {
	std::vector<int> divisors;

	public:
	Factor(int n) : divisors(n, 0) {
		std::iota(this->divisors.begin(), this->divisors.end(), 0);
		for(int i = 2; i * i < n; i++) {
			if(this->divisors[i] != i) {
				continue;
			}
			this->divisors[i] = i;
			for(int j = i * i; j < n; j += i) {
				if(this->divisors[j] == j) {
					this->divisors[j] = i;
				}
			}
		}
	}

	std::unordered_map<int, size_t> operator()(int n) {
		std::unordered_map<int, size_t> factors;
		while(n != 1) {
			int divisor = this->divisors[n];
			while(n % divisor == 0) {
				factors[divisor]++;
				n /= divisor;
			}
		}
		return factors;
	}
};

void merge_unordered_map(unordered_map<int, size_t>& m1,
						 const unordered_map<int, size_t>& m2) {
	EACH(e, m2) { m1[e.first] += e.second; }
}

ModInt<> divisors_num(const unordered_map<int, size_t>& m) {
	ModInt ret = 1;
	EACH(e, m) { ret *= e.second + 1; }
	return ret;
}

int main() {
	int n;
	cin >> n;

	auto factor = Factor(n + 1);
	unordered_map<int, size_t> result;
	RANGE(i, 2, n + 1) {
		auto factors = factor(i);
		merge_unordered_map(result, factors);
	}

	cout << divisors_num(result) << endl;
	return 0;
}

