void smallestPrimeFactors()
{
    for (int i = 0; i <= N; i++) {
        spf[i] = i;
    }

    for (int i = 2; i <= N; i++) {
        if (spf[i] == i) {
            for (int j = i * i; j <= N; j += i) {
                spf[j] = i;
            }
        }
    }
}

void factorization(int n)
{
    if (n == spf[n]) {
        prime[n]++;
        return;
    }
    prime[spf[n]]++;
    factorization(n / spf[n]);
    return;
}

