	is_prime[0]=is_prime[1]=false;
	for(ll i=2;i<=n;i++){
		if(is_prime[i]){
			prime[p++]=i;
			for(ll j=2*i;j<=n;j+=j) is_prime[j]=false;
		}
	}
	return p;
}
