#include<bits/stdc++.h>
using namespace std;
map<int,int> mp;
bool isp(int x)
{
	if(x<2) return 0;
	for(int i=2;i*i<=x;i++)
		if(x%i==0)
			return 0;
	return 1;
}
int main()
{
	int n;
	cin>>n;
	for(int i=1;i<=n;i++)
	{
		int t=i;
		for(int j=2;j<=t;j++)
		{
			if(isp(j))
			{
				int a=0;
				while(t%j==0)
				{
					t/=j;
					a++;
				}
				if(mp.find(j)!=mp.end())
				{
					mp[j]+=a;
				}
				else
				{
					mp[j]=a;
				}
			}
		}
	}
	long long ans=1;
	for(map<int,int>::iterator it=mp.begin();it!=mp.end();it++)
	{
		ans*=(it->second+1);
		ans%=1000000007;
	}
	cout<<ans<<endl;
	return 0;
}

