#define MOD 1000000007

typedef long long ll;

using namespace std;

// n 以下の素数のリストを計算
vector<int> getPrime(int n) {
	vector<int> primeVec;
	for (int i = 2; i <= n; i++) {
		int divCount = 0;
		for (int j = 1; j * j <= i; j++) {
			if (i % j == 0) {
				divCount++;
			}
		}
		if (divCount == 1) {
			primeVec.push_back(i);
		}
	}

	return primeVec;
}

int main(){
    int N;
    cin >> N;
    ll ans = 1;

    if (N != 1) {
	    vector<int> primeVec = getPrime(N);
	    map<int, int> factoringMp;

	    for (int i = 2; i <= N; i++) {
	    	int res = i;
	    	for (auto itr = primeVec.begin(); itr != primeVec.end(); itr++) {
	    		int count = 0;
	    		int div = *itr;
				if (res < div) {
					break;
				}
				while (res % div == 0) {
					res /= div;
					count++;
				}

				auto mpItr = factoringMp.find(div);
				if (mpItr != factoringMp.end()) {
					factoringMp[div] += count;
				}
				else {
					factoringMp[div] = count;
				}
