using ll = long long;

vector<bool> IsPrime;
vector<int> Primes;
vector<int> Counter;

void sieve(size_t max) {
    if(max + 1 > IsPrime.size()) { // resizeで要素数が減らないように
        IsPrime.resize(max + 1, true); // IsPrimeに必要な要素数を確保
    }
    IsPrime[0] = false; // 0は素数ではない
    IsPrime[1] = false; // 1は素数ではない

    for(size_t i = 2; i * i <= max; ++i) // 0からsqrt(max)まで調べる
        if(IsPrime[i])                   // iが素数ならば
            for(size_t j = 2; i * j <= max; ++j) // (max以下の)iの倍数は
                IsPrime[i * j] = false;          // 素数ではない
}

void getPrimes(size_t max) {
    sieve(max);
    for(int i = 2; i <= max; i++) {
        if(IsPrime[i]) {
            Primes.push_back(i);
        }
    }
}

void factCount(int n) {
    for(int i = 0; i < Primes.size() && Primes[i] <= n; i++) {
        // cout << n << "%" << Primes[i] << ": " << n % Primes[i] << endl;
        while(true) {
            if(n % Primes[i] == 0) {
                Counter[Primes[i]]++;
                n /= Primes[i];
            } else
                break;
        }
    }
}

int main() {
    int n;
    ll mod = 1e9 + 7, ans = 1;
    cin >> n;
    getPrimes(n);

    // rep(i, Primes.size()) { cout << "prime" << i << ": " << Primes[i] <<
    // endl; }

    Counter.resize(n + 1);

    for(int i = 2; i <= n; i++) {
        factCount(i);
    }

    // rep(i, Counter.size()) { cout << "num" << i << ": " << Counter[i] <<
    // endl; }

    for(int i = 0; i <= n; i++) {
        ans = (ans * (Counter[i] + 1)) % mod;
    }

    cout << ans << endl;
    return 0;
}

