map<int, int> prime_factors(int n) {
    map<int, int> res;
    if(n == 1) { // n=1 の素因数分解は n^1
        res[n] = 1;
        return res;
    }
    for(int i = 2, _n = n; i*i <= _n; ++i) {
        while(n % i == 0) {
            ++res[i]; // 素数i^{res[i]}
            n /= i;
        }
    }
    if(n != 1) res[n] = 1;
    return res;
}

int main() {
   int N;
   cin >> N;
   map<int, int> log;
   for (int i = 1; i <= N; i++) {
      map<int, int> res = prime_factors(i);
      for(map<int, int>::iterator it = res.begin(), end = res.end(); it != end; ++it) {
         // cout << it->first << "^" << it->second << endl;
         if (it->first == 1) continue;
         log[it->first] += it->second;
      }
   }
   ll ans = 1;
   for (auto alog : log) {
      ans *= 1 + alog.second;
      ans %= MOD;
   }
   cout << ans << endl;
   return 0;
}

