typedef unsigned long long int ull;
const int mod = 1e9 + 7;
vector<ull> allPrimes;

void sieve(int n) {
    vector<bool> prime(n+1, true);

    for (int p=2; p*p<=n; p++) {
        if (prime[p] == true) {
            for (int i=p*2; i<=n; i += p)
                prime[i] = false;
        }
    }

    for (int p=2; p<=n; p++)
        if (prime[p])
            allPrimes.push_back(p);
}

ull factorialDivisors(ull n) {
    sieve(n);  // create sieve

    ull result = 1;

    for (int i=0; i < allPrimes.size(); i++) {
        ull p = allPrimes[i];
        ull exp = 0;
        while (p <= n) {
            exp = exp + (n/p);
            p = p*allPrimes[i];
        }
            result = ((result%mod)*((exp+1)%mod))%mod;
    }
    return result;
}

int main() {
    int n;
    cin >> n;
    cout << factorialDivisors(n);
    return 0;
}

