const ll MOD = (ll)1e9 + 7LL;

int cnt[1000]; // 1000 is not prime.

void prime_factorize(int a){
	for (int p = 2; p * p <= a; ++p){
		if (a % p == 0){
			int c = 0;
			do{
				a /= p;
				++c;
			}while(a % p == 0);
			cnt[p] += c;
		} // end for
	} // end for

	if (a > 1) ++cnt[a];
}

int main()
{
	memset(cnt, 0, sizeof(cnt));
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	int N; cin >> N;

	for (int i = 1; i <= N; ++i){
		prime_factorize(i);
	} // end for

	ll res = 1LL;
	for (int i = 1; i <= N; ++i){
//		cerr << "i: " << setw(3) << i << " cnt: " << cnt[i] << endl;
		if (cnt[i] != 0){
			res = (res *((ll)cnt[i] + 1LL)) % MOD;
		} // end if
	} // end for

	cout << res << endl;

	return 0;
}

