bool isPrime(ll a){
  if(a == 1) return false;
  if(a == 2) return true;
  if(a%2 == 0) return false;
  for(ll i=3;i*i<=a;i += 2){
    if(a%i == 0) return false;
  }
  return true;
}

int howdiv(int n,int d){
  if(n%d) return 0;
  else return 1+howdiv(n/d,d);
}

int main(){
