  rep1(i,1000){
    rep(j,m){
      dp[i][j] = dp[i-1][j] + howdiv(i,primes[j]);
    }
  }
  ll ans = 1;
  rep(j,m){
    ans *= (dp[n][j]+1);
    ans %= 1000000007;
  }
  cout << ans << endl;
}

