const int MAX = 1e6;

bool is_prime(int x) { // 素数判定
    if (x < 2) return false;
    for (int i = 2; i * i <= x; i++) {
        if (x % i == 0) return false;
    }
    return true;
}

int seive[MAX+1]; // 整数の素因数で最小のもの

void erat() { // エラトステネスのふるい
    rep(i, MAX+1) seive[i] = i; // 初期化
    for (int i = 2; i <= MAX; i++) {
        if (seive[i] == i) { // seive[i]=iならばiは素数
            for (int j = i + i; j <= MAX; j += i) {
                seive[j] = i;
            }
        }
    }
}

void prime_fact(int x, set<int> &fact) { // 高速素因数分解
    while (x > 1 && x % seive[x] == 0) {
        fact.insert(seive[x]); // 素因数
        x /= seive[x];
    }
}


void prime_fact(int x, vector<int> &fact) { // 素因数分解
    for (int i = 2; i * i <= x; i++) {
        while (x % i == 0) {
            fact.push_back(i); // 素因数
            x /= i;
        }
    }
    if (x != 1) {
        fact.push_back(x);
    }
}

