void factorize(int n){
    for(int i = 2;i * i <= n;i++){
        if(n % i == 0){
            while(n % i == 0){
                primes[i]++;
                n /= i;
            }
        }
    }

    if(n != 1)  primes[n]++;
}

int main(){
    init();

