    ll N = 0; cin >> N;

    prime.assign(N + 500, true);
    isPrime(N);

    vector<pi > t_ans = factorialPrimeFactor(N);

    ll ans = 1;

    for(ll i = 0; i < t_ans.size(); i++){
        //cout << t_ans[i].second << endl;
        ans *= t_ans[i].second + 1;
        ans %= MOD;
    }

    cout << ans << endl;

}

