void sieve_of_eratosthenes(int n) {
	//primes : [0, n] の配列で，primes[i] != 0 iff i は素数
	//O(n log n)
	primes.assign(n + 1, true);
	for (int i = 0; i <= 1; ++i)
		primes[i] = false;
	for (int i = 2; i*i <= n; ++i)
		if (primes[i])
			for (int j = i * i; j <= n; j += i)
				primes[j] = false;
	return;
}

bool is_prime(const int n, const bool is_using_primes) {
	if (n <= 1)
		return false;
	for (int i = 2; i*i <= n; i++) {
		if (is_using_primes && !primes[i])
			continue;
		if (n % i == 0)
			return false;
	}
	return true;
}

vector<int> make_divisors(const int n) {
	vector<int> ans;
	for (int i = 1; i*i <= n; i++)
	{
		if (n%i == 0) {
			ans.emplace_back(i);
			if (n / i != i)
				ans.emplace_back(n / i);
		}
	}
	return ans;
}

unordered_map<unsigned int, int> make_prime_factor(unsigned int n, const bool is_using_primes) {
	unordered_map<unsigned int, int> ans;
	for (unsigned int i = 2; i*i <= n; i++) {
		if (is_using_primes && !primes[i])
			continue;
		while (n % i == 0) {
			++ans[i];
			n /= i;
		}
	}
	if (n != 1)
		++ans[n];
	return ans;
}
