typedef long long ll;

//素因巣分解のpairを返す関数(1次元目が素因数，2次元目がその素因数をいくつ持っているか)
vector<pair<ll, ll>> factorize(ll n)
{
  vector<pair<ll, ll>> res;

  for(ll i=2; i*i < n; i++)
  {
    if(n % i != 0) continue;//素因数にないならスキップ
    res.emplace_back(i, 0);//素因数を追加
    while(n % i == 0){
      n = n / i;
      res.back().second++;//1後ろの2次元目をインクリメント
    }
  }
  if(n != 1 ) res.emplace_back(n, 1);

  return res;
}

