S Eratosthenes(int n){
  S set_;
  FOR(i,2,n+1)set_.insert(i);
  FOREACH(s,set_){
    if(s>sqrt(n))break;
    FOREACH(ss,set_){
      if(ss>s&&ss%s==0)set_.erase(ss);
    }
  }
  return set_;
}

