vector<int> primeNumbers(int x) {
	vector<int> v;
	int sn = sqrt(x);

	for (int number = 2; number <= x; number++) {
		int i = 0;
		bool pn = false;
		while (true) {
			if (i >= v.size() || v[i] > sn) { //平方根までの全素数で割れればOK
				v.push_back(number);
				break;
			}
			if (number % v[i] == 0) break;
			i++;
		}
	}
	return v;
}

//素因数分解
map<int, int> primeFactorMap(int x, vector<int> vpn) {
	map<int, int> mpn;

	int k = 0;
	while (true) {
		bool can_div = false;
		for (int i = k; i < vpn.size(); i++) {
			int n = vpn[i];
			if (x % n == 0) {
				if (mpn.count(n) == 0) mpn.insert(pair<int, int>(n, 1));
				else mpn[n]++;
				x /= vpn[i];
				k = i;
				can_div = true;
				break;
			}
		}
		if (!can_div) break;
	}
	return mpn;
}


//Valueを＋演算子でマージ
template<typename Tkey,typename Tval>
void mergeMap(map<Tkey, Tval>& mapBase, map<Tkey, Tval> mapAdded) {

	for (pair<Tkey,Tval> p : mapAdded) {
		if (mapBase.count(p.first) > 0) {
			mapBase[p.first] += p.second;
		}
		else {
			mapBase[p.first] = p.second;
		}
	}
}

