	map<int, int> mp;
	vector<int> primes= primeNumbers(N);

	for (int i = 2; i <= N; i++) {
		auto m = primeFactorMap(i, primes);
		mergeMap(mp, m);
	}

	long long counter = 1;
	for (auto p : mp) {
		counter *= (p.second + 1);
		counter %= MOD;
	}
	cout << counter << endl;

	return 0;
}

