int func(int n,int i){
  int ans = 0;
  if(prime(i)){
    if(n%i == 0 && i <= n){
      int k = n;
      while(k >0){
        ans++;
        k /= i;
        if(k%i != 0){
          break;
        }
      }
    }
  }
  return ans;
}

