    vector<int> fn(N+1);
    for (int i = 2; i <=N; i++){
        auto pf = prime_factorize(i);
        for (auto p : pf){
            fn[p.first] += p.second;
        }
    }

    for (int i = 2; i<=N; i++){
        ans *= fn[i]+1;
    }

    cout << ans << endl;
}

