#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll mod = 1e9+7;

map<ll,ll> mp; 

void factorsFactorial(ll n){
    vector<bool> nPrime(n+1);
    for(int i = 2;i < n+1;i ++){
        if(nPrime[i]) continue;
        ll si = i*2;
        while(si<n+1) {nPrime[si]=1;si+=i;}
    }
    for(int i = 2;i < n+1;i ++){
        if(nPrime[i]) continue;
        ll si = i;
        while(n/si){
            mp[i] += n/si;
            si *= i;
        }
    }
}

int main(){
    ll n,ans=1;
    cin >> n;
    factorsFactorial(n);
    for(auto ite = mp.begin();ite != mp.end();++ite){
        ans = ans*(ite->second+1)%mod;
    }
    cout << ans << endl;
    return 0;
}

