    for(ll i=2;i<=n;i++){//n以下の連続整数の素因数個数を数える
        ll number=i;
        for(ll j=2;j<=i;j++){
            if(prime[j]==true){
                while(number%j==0){
                    num[j]++;
                    number/=j;
                }
            }
        }
