const auto P = (ll) 1e9 + 7;

ll factorial_count(ll N) {
    vector<int> count(MAX_N, 0);

    for (int i = 2; i <= N; i++) {
        int t = i;
        for (int p = 2; p <= t; ++p) {
            while (t % p == 0) {
                count[p]++;
                t /= p;
            }
        }
    }

    ll ans = 1;
    for (auto x : count) {
        ans = ans * (x + 1) % P;
    }
    return ans;
}

int main() {
