template <typename T> // ll or int
T lcm(T x, T y) {
	T res = 0;
	T mod = x % y;
	if (mod == 0)
		res = y;
	else
		res = lcm(y, mod);

	return res;
}

/* greatest common divisor */
template <typename T> // ll or int
T gcd(T x, T y) {
	T res = 0;
	T lcm_v = lcm(x, y);

	res = x / lcm_v * y;

	return res;
}

