const ll MOD = 1000000007;
const int nmax = 8;
bool graph[nmax][nmax];

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}
int dfs(int v, ll N, bool visited[nmax])
{
    bool all_visited = true;

    for (int i = 0; i < N; i++)
    {
        if (!visited[i])
        {
            all_visited = false;
        }
    }

    if (all_visited)
    {
        return 1;
    }
    int ret = 0;
    for (size_t i = 0; i < N; i++)
    {
        if (!graph[v][i])
        {
            continue;
        }
        if (visited[i])
        {
            continue;
        }

        visited[i] = true;
        ret += dfs(i, N, visited);
        visited[i] = false;
    }

    return ret;
}

void solve(long long N)
{
    //帰ったらすぐとく
    map<int, ll> prime;
    ll ans = 1;
    for (int i = 2; i <= N; i++)
    {
        ll temp = i;
        for (int j = 2; j <= i; j++)
        {
            ll cnt = 0;
            while (temp % j == 0)
            {
                cnt++;
                temp /= j;
            }
            if (cnt != 0)
            {
                if (prime.find(j) == prime.end())
                {
                    prime[j] = cnt;
                }
                else
                {
                    prime[j] += cnt;
                }
            }
        }
    }

    for (auto i = prime.begin(); i != prime.end(); i++)
    {
        ans = mulMod(ans, i->second+1);
    }

    cout << ans << endl;
}

int main()
{
    long long N;
    scanf("%lld", &N);
    solve(N);
    return 0;
}

