vector< bool > prime_table(number n) {
    vector< bool > prime(n + 1, true);
    if (n >= 0) prime[0] = false;
    if (n >= 1) prime[1] = false;
    for (number i = 2; i * i <= n; i++) {
        if (!prime[i]) continue;
        for (number j = i + i; j <= n; j += i) {
            prime[j] = false;
        }
    }
    return prime;
}

