    auto pr = prime_table(n);
    mint ans = 1;
    rep(p, n + 1) {
        if (!pr[p]) continue;
        mint tmp = 1;
        int beki = p;
        while (n >= beki) {
            tmp += (n / beki);
            beki *= p;
        }
        ans *= tmp;
    }

    cout << ans << endl;
}

