void prime_factorize(long long N) {
    for (ll a = 2; a * a <= N; ++a) {
        if (N % a != 0) continue;
        ll ex = 0; // 指数

        // 割れる限り割り続ける
        while (N % a == 0) {
            ++ex;
            N /= a;
        }

        // その結果を push
        g[a]+=ex;
        h.insert(a);
    }

    // 最後に残った数について
    if (N != 1){g[N]++;h.insert(N);};
    return;
}

