const int MOD = (int)1e9 + 7;
int n;

VI sieve()
{
	VB prime(n + 1, true);
	prime[0] = prime[1] = false;

	int m = sqrtl(n);
	for(int i = 2; i <= m; ++i)
		if(prime[i])
			for(int j = i * i; j <= n; j += i)
				if(prime[j]) prime[j] = false;

	VI ret;
	for(int i = 2; i <= n; ++i)
		if(prime[i])
			ret.emplace_back(i);
	return ret;
}

ULL solve()
{
	VI primes = sieve();
	ULL ret = 1;
	for(int i = 0; i < sz(primes); ++i)
	{
		ULL p = primes[i];

		ULL exp = 0;
		while(p <= n)
		{
			exp += (n / p);
			p *= primes[i];
		}

		ret = (ret * (exp + 1ll)) % MOD;
	}
	return ret;
}

