map< ll, int > prime_factor(ll n) {
  map< ll, int > ret;
  for(ll i = 2; i * i <= n; i++) {
    while(n % i == 0) {
      ret[i]++;
      n /= i;
    }
  }
  if(n != 1) ret[n] = 1;
  return ret;
}

int main() {
  int N; cin >> N;
  map<ll, int> m;
  for(int i = 1; i <= N; ++i) {
    auto a = prime_factor(i);
    for(auto x : a) {
      m[x.first] += x.second;
    }
  }
  ll ans = 1;
  for(auto x : m) {
    ans = ans * (x.second + 1) % 1000000007;
  }
  cout << ans << endl;
}

