const int INF = 1000000007;

// 何回割り切れるか
int num_division(int x, int y)
{
    int n = 0;
    while (x / y != 0 && x % y == 0)
    {
        x /= y;
        n++;
    }
    return n;
}

// 素数判定
bool isPrime(int n)
{
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++)
    {
        if (n % i == 0) return false;
    }
    return true;
}

// aとbを掛けた値をmodする(a * b mod p)
int modmulti(int a, int b)
{
    int res = 0;
    int mod = a % INF;
    while (b > 0)
    {
        if ((b & 1) == 1)
        {
            res += mod;
            if (res > INF)
            {
                res -= INF;
            }
        }
        mod <<= 1;
        if (mod > INF)
        {
            mod -= INF;
        }
        b >>= 1;
    }
    return res;
}

int main()
{
    int N;
    if (scanf("%d", &N) < 1) return 0;

    int sum = 1;
    for (int i = 2; i <= N; i++)
    {
        if (!isPrime(i)) continue;
        int cnt = 0;
        for (int j = 2; j <= N; j++)
        {
            if (j < i) continue;
            cnt += num_division(j, i);
        }
        sum = modmulti(sum, cnt + 1);
    }

    printf("%d\n", sum);
    return 0;
}

