#include <bits/stdc++.h>

using namespace std;

constexpr int modulo = 1000000007;

std::vector<int> primeFactorization(int n) {
  std::vector<int> ret{};
  int const maxPrimteCandidate = static_cast<int>(sqrt(n));
  for (int i = 2; n > 1 && i <= maxPrimteCandidate; i++) {
    while (n % i == 0) {
      ret.push_back(i);
      n /= i;
    }
  }
  if (n > 1) {
    ret.push_back(n);
  }
  return ret;
}

int solve(int n) {
  if (n == 1) {
    return 1;
  }
  std::vector<int> allPrimes{};
  for (int i = 2; i <= n; i++) {
    auto primes = primeFactorization(i);
    allPrimes.insert(allPrimes.end(), primes.begin(), primes.end());
  }
  std::sort(allPrimes.begin(), allPrimes.end());
  int64_t ret = 1;
  for (auto itr = allPrimes.begin(); itr != allPrimes.end();) {
    auto const nextItr = std::upper_bound(itr, allPrimes.end(), *itr);
    ret *= ((nextItr - itr) + 1);
    ret %= modulo;
    itr = nextItr;
  }
  return static_cast<int>(ret);
}

int main() {
  int n;
  std::cin >> n;
  std::cout << solve(n) << std::endl;
  return 0;
}

