vector<int> sieve(int n) {
	vector<int> prime;
	vector<bool> is_prime(n + 1, true);
	is_prime[0] = is_prime[1] = false;
	for (int i = 2; i <= n; ++i) {
		if (is_prime[i]) {
			prime.push_back(i);
			for (int j = 2 * i; j <= n; j += i) {
				is_prime[j] = false;
			}
		}
	}
	return prime;
}
map<ll, int> prime_factrorize(ll n, vector<int> const & primes) {
	map<ll, int> result;
	for (int p : primes) {
		if (n < p) break;
		while (n % p == 0) {
			result[p] += 1;
			n /= p;
		}
	}
	if (n != 1) result[n] += 1;
	return result;
}
