const int mod = 1000000007;
struct mint {
  ll x;
  mint(ll x=0):x(x%mod){}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

// エラトステネスの篩でN 以下の素数判定を行う
// 素数: 1, 素数じゃない: 0
// [0, 0, 1, 1, 0, 1, ...]
vector<int> createEratos(int n)
{
  vector<int> isprime(n+1, 1);
  isprime[0] = 0;
  isprime[1] = 0;

  for (int i = 2; i * i <= n; i++) {
    if (isprime[i]) {
      int j = i + i;
      while (j <= n) {
        isprime[j] = 0;
        j = j + i;
      }
    }
  }
  return isprime;
}

// 階乗の素因数分解
// n = 10: 2^1 * 5^1 [0, 0, 1, 0, 1, 0, ...]
// n = 12: 2^2 * 3^1 [0, 0, 2, 1, 0, 0, ...]
vector<int> factfact(int n)
{
  vector<int> prime = createEratos(n);

  for (int i = 2; i <= n; i++) {
    if (prime[i]) {
      prime[i] = 0;
      for (int j = i; j <= n; j *= i) {
        prime[i] += n/j;
      }
    }
  }
  return prime;
}

int main()
{
  int n;
  cin >> n;

  // 1 ~ n を素因数分解
  // 各素数の 数をカウント (2^x)(3^y)(5^z)...
  vector<int> fact = factfact(n);

  // ans = (x+1)(y+1)(z+1)...
  struct mint ans;
  ans.x = 1;
  for (auto v : fact) {
    mint val;
    val.x = v + 1;
    ans *= val;
  }

  cout << ans.x << endl;

  return 0;
}

