int cnt[1001];

void decompositPrime(int n)
{
	// 割る数の初期値
	int a = 2;
	// √n ≧ a ( n ≧ a * a ) の間ループ処理
	while (n >= a * a) {
		// a で割り切れたら、a は素因数
		// そして、割られる数を a で割る
		// a で割り切れなかったら、 a を 1 増加させる
		if (n % a == 0) {
			cnt[a]++;
			n /= a;
		}
		else {
			a++;
		}
	}
	// 最後に残った n は素因数
	cnt[n]++;
}

