  osa_k_init(n);
  map<int, int> mp;
  FOR(i, 2, n + 1) {
    auto tmp = osa_k(i);
    for (auto a : tmp) mp[a.first] += a.second;
  }
  long long ans = 1;
  FOR(i, 2, n + 1) if (mp[i] > 0) (ans *= (mp[i] + 1)) %= MOD;
  cout << ans << '\n';
  return 0;
