        for(auto p : pf) ex[p.first] += p.second;
    }
    ll MOD = 1e9 + 7;
    ll ans = 1;
    for(int i = 2; i <= N; i++){
        ans *= ex[i] + 1;
        ans %= MOD;
    }
    cout << ans << endl;
}

