const int MOD = 1000000007;

vector<ll> pf(ll n) {
    vector<ll> p;
    double x = sqrt(n);
    for (ll i = 2; i <= x; i++) {
        while (n % i == 0 && n) {
            p.push_back(i);
            n /= i;
        }
    }
    if (n != 1) p.push_back(n);
    return p;
}

vector<ll> divisors(ll n) {
    vector<ll> div;
    double x = sqrt(n);
    for (ll i = 1; i <= x; i++) {
        if (n % i == 0) {
            div.push_back(i);
            if (i != n / i) div.push_back(n / i);
        }
    }
    sort(div.begin(), div.end());
    return div;
}

int main() {
    int n;
    cin >> n;
    ll d[n + 1] = {};
    for (int i = n; i >= 1; i--) {
        vector<ll> vec = divisors(i);
        for (auto x : vec) d[x]++;
    }
    ll prime[n + 1] = {};
    for (int i = 2; i <= n; i++) {
        if (d[i]) {
            vector<ll> vec = pf(i);
            for (auto x : vec) {
                prime[x]++;
            }
        }
    }
    ll ans = 1;
    for (int i = 2; i <= n; i++) {
        if (prime[i]) ans *= (prime[i] + 1);
        ans %= MOD;
    }
    cout << ans << endl;
}

