vector<bool> sieve(int n) {
  vector<bool> vec(n+1, true);
  vec[0] = false;
  vec[1] = false;
  for(int i = 2; i*i <= n; i++) {
    if (is_prime(i)) {
      int x = i*2;
      while(x <= n) {
        vec[x] = false;
        x += i;
      }
    }
  }
  return vec;
}

