  std::vector<long long> arr(N+1);
  for(long long i = 0; i <= N; i++) arr[i] = 1;
	for(long long i = 2; i <= std::sqrt(N); i++) {
    if(arr[i]) for(long long j = 0; i * (j + 2) <= N; j++) arr[i *(j + 2)] = 0;
