#include <bits/stdc++.h>

using namespace std;

constexpr int modulo = 1000000007;

template <size_t N, size_t MaxPrimeSize>
struct primes_t {
  constexpr static size_t maxPrimeSize = MaxPrimeSize;
  constexpr primes_t() : primes(), count(), notSieves() {
    primes[count++] = 2;
    notSieves[0] = notSieves[1] = true;
    for (int i = 2; i < N; i++) {
      if (notSieves[i]) {
        continue;
      }
      primes[count++] = i;
      for (int64_t j = 2; i * j < N; j++) {
        notSieves[i * j] = true;
      }
    }
  }
  int64_t primes[MaxPrimeSize];
  int count;

 private:
  bool notSieves[N];
};

static constexpr auto primes = primes_t<1001, 169>{};

std::vector<int> primeFactorization(int n) {
  std::vector<int> ret{};
  int const maxPrimteCandidate = static_cast<int>(sqrt(n));
  for (int i = 0;; i++) {
    if (n <= 1) {
      return ret;
    }
    auto const prime = primes.primes[i];
    if (prime > maxPrimteCandidate) {
      break;
    }
    while (n % prime == 0) {
      ret.push_back(prime);
      n /= prime;
    }
  }
  if (n > 1) {
    ret.push_back(n);
  }
  return ret;
}

int solve(int n) {
  if (n == 1) {
    return 1;
  }
  std::vector<int> allFactors{};
  for (int i = 2; i <= n; i++) {
    auto factors = primeFactorization(i);
    allFactors.insert(allFactors.end(), factors.begin(), factors.end());
  }
  std::sort(allFactors.begin(), allFactors.end());
  int64_t ret = 1;
  for (auto itr = allFactors.begin(); itr != allFactors.end();) {
    auto const nextItr = std::upper_bound(itr, allFactors.end(), *itr);
    ret *= ((nextItr - itr) + 1);
    ret %= modulo;
    itr = nextItr;
  }
  return static_cast<int>(ret);
}

int main() {
  int n;
  std::cin >> n;
  std::cout << solve(n) << std::endl;
  return 0;
}

