/* Eratosthenes Lib */
class Eratosthenes {
 public:
  Eratosthenes(int n) : isprime_(n + 1, true) {
    isprime_[0] = false;  isprime_[1] = false;
    for (int i = 2; i <= n; ++i) if (isprime_[i]) {
      primes_.push_back(i);
      for (int j = 2; i * j <= n; ++j) isprime_[i * j] = false;
    }
  }

  bool isprime(int x) const { return isprime_[x]; }
  auto primes(int x) const {
    vi prime_list;
    auto last = upper_bound(primes_.begin(), primes_.end(), x);
    for (auto it = primes_.begin(); it != last; ++it)
      prime_list.push_back(*it);
    return prime_list;
  }
  auto factor(int x) const {
    map<int, int> factor_map;
    int search_max = (int)sqrt(x);
    for ( auto p : primes(search_max) ) {
      while (x % p == 0) {
        x /= p;
        factor_map[p]++;
      }
    }
    if (x != 1) factor_map[x]++;
    return factor_map;
  }

