bool is_prime(int n){
	if(n == 1){
		return false;
	}
	if(n == 2){
		return true;
	}
	int divisor = 2;
	while(divisor < n){
		if(n % divisor == 0){
			return false;
		}
		divisor++;
	}
	return true;
}

void prime_factor(int n, vector<int> &cnt){
	while(!is_prime(n)){
		int divisor = 2;
		// cout << "divisor : " << divisor << endl;
		// cout << "n : " << n << endl;
		while(divisor <= n){
			if(is_prime(divisor) && n % divisor == 0){
				cnt.at(divisor)++;
				n /= divisor;
				break;
			}
			divisor++;
		}
	}
	cnt.at(n)++;
	return;
}

