void prime_factorize(ll n) {
    for (ll p = 2; p * p <= n; ++p) {
        if (n % p != 0) continue;
        int num = 0;
        while (n % p == 0) { ++num; n /= p; }
        primes[p] += num;
    }
    if (n != 1) primes[n] += 1;
}

