struct Sieve {
        int n;
        vector<int> f,primes;

        Sieve(int n=1):n(n),f(n+1){
                f[0] = f[1] = -1;
                for(long long i=2;i<=n;++i){
                        if(f[i]) continue;
                        primes.push_back(i);
                        f[i] = i;
                        for(long long j = i*i;j <= n;j += i) {
                                if(!f[j]) f[j] = i;
                        }
                }
        }

        bool isPrime(int x){return f[x] == x;}

        vector<int> factorList(int x){
                vector<int> res;
                while(x != 1){
                        res.push_back(f[x]);
                        x /= f[x];
                }
                return res;
        }

        vector<pair<int,int>> factor(int x){
                vector<int> fl = factorList(x);
                if(fl.size() == 0) return {};
                vector<pair<int,int>> res(1,pair<int,int>(fl[0],0));
                for(int p:fl){
                        if(res.back().first == p){
                                res.back().second ++;
                        }else{
                                res.emplace_back(p,1);
                        }
                }
                return res;
        }

};


int main() {
  int n;
  cin >> n;
  Sieve sieve(1005);
  map<int,int> mp;
  for(int i=1;i<=n;i++){
    auto f = sieve.factor(i);
    for(auto p:f){
      mp[p.first] = (mp[p.first]+p.second)%MOD ;
    }
  }
  ll ans = 1;
  for(auto num:mp){
    ans *= num.second+1;
    ans %= MOD;
  }
  cout << ans << endl;

  return 0;
}

