inline vector<int> primes(int n) {
  vector<bool> is_prime(n+1, true);
  is_prime[0] = is_prime[1] = false;
  for (int i = 2; i*i <= n; i++) {
    if (is_prime[i]) {
      for (int k = i * 2; k <= n; k += i) {
        is_prime[k] = false;
      }
    }
  }

  vector<int> x;
  for (int i = 2; i <= n; i++) {
    if (is_prime[i]) {
      x.push_back(i);
    }
  }

  return x;
}

inline map<ll, int> prime_factorize(ll n, vector<int> const & primes) {
  map<ll, int> result;
  for (int p: primes) {
    if (n < p * (ll)p) break;
    while (n % p == 0) {
      result[p] += 1;
      n /= p;
    }
  }

  if (n != 1) result[n] += 1;
  return result;
}

inline int ans(int N) {
  vector<int> _primes = primes(sqrt(N) + 3);
  map<ll, int> factors;

  for (int i = 1; i < N + 1; i++) {
    for (auto kv: prime_factorize(i, _primes)) {
      int p, cnt;
      tie(p, cnt) = kv;
      factors[p] += cnt;
    }
  }

  ll ret = 1;
  for (auto kv: factors) {
    int cnt = kv.second;
    ret = (ret * (1 + cnt) ) % MOD;
  }

  return ret;
}

int main (void) {
  int N;
  cin >> N;
  int _ans = ans(N);
  cout << _ans << endl;
  return 0;
}

