const ll MOD = 1e9 + 7;
//加算代入演算子は+=！！！！！
//int 2^31 10^9まで
// 5! = 120。約数の数は、16。
// 5! = 5 * 3 * (2^3)
int main() {
    int n, count = 0;
    cin >> n;
    map<int, int> count_prime; // mapを用いると「特定の値に、ある値が紐付いている」ようなデータを扱うことができる。

    // N,N-1,N-2,..について各素数の個数を求める。
    for (int i = 2; i <= n; i++) { // 階乗の整数(i)分繰り返す。1は除外してるので2からスタート。
        int temp = i; // iが変化しないように
        for (int j = 2; j <= temp; j++) { // 階乗の各整数(temp)をさらに素数に分解
            while (temp % j == 0) {
                temp /= j;
                count_prime[j]++; //分解できたらその素数をキーに値+1する。
            }
        }
    }

    // (素数aの数+1) * (素数bの数+1) * (素数cの数+1)...
    // +1はその素数を選ぶか選ばないか
    ll ans = 1;
    for (auto p : count_prime) { //pair<int, int> p : count_primeと同義。count_primeのキーの値が小さい順にループ
        ans = ((ans % MOD) * (p.second + 1) % MOD) % MOD; //p.secondは素数の個数
    }
    cout << ans << endl;
    return 0;
}

