map<int, long long> primes;

void calcPrimes(int n)
{
	int max_it = (int)sqrt(n);
	// cout << "primes of " << n << " is ";
	for(int i = 2; i <= max_it; i++){
		if(!(n % i)){
			// cout << i << " ";
			primes[i]++;
			n /= i;
			i--;
		}
	}
	// cout << n << endl;
	if(n != 1) primes[n]++;
}


int main()
{
	int N;
	cin >> N;
	long long prod = 1;
	for(int i = 2; i <= N; i++){
		calcPrimes(i);
	}
	for(map<int, long long>::iterator it = primes.begin(); it != primes.end(); it++){
		// cout << it->first << " " << it->second << endl;
		prod = (prod * (it->second + 1)) % 1000000007;
	}
	cout << prod << endl;

	return 0;
}

