void FactrizePrime(int x, std::unordered_map<int, int> &count)
{
    while (x % 2 == 0)
    {
        ++count[2];
        x /= 2;
    }
    for (int i = 3; i <= x; i += 2)
    {
        while (x % i == 0)
        {
            ++count[i];
            x /= i;
        }
    }
}

