vector<pair<T, ll>> rle(vector<T> v)
{
    vector<pair<T, ll>> ret;
    ret.reserve(v.size() / 2);
    for (const auto x : v)
    {
        if (ret.empty() || ret.back().first != x)
        {
            ret.emplace_back(x, 1);
        }
        else
        {
            ++ret.back().second;
        }
    }
    return ret;
}
