            ret.emplace_back(c, 1);
        }
        else
        {
            ++ret.back().second;
        }
    }
    return ret;
}

struct primeSieve
{
    ll n;
    vll prime_factor;
    vll primes;

    primeSieve(ll n = 1)
        : n(n), prime_factor(n + 1, 0)
    {
        prime_factor[0] = prime_factor[1] = -1;
        for (ll i = 2; i <= n; ++i)
        {
            if (prime_factor[i])
                continue;
            primes.pb(i);
            prime_factor[i] = i;
            for (ll j = i * i; j <= n; j += i)
            {
                if (!prime_factor[j])
                    prime_factor[j] = i;
            }
        }
    }
    bool isPrime(ll x) { return prime_factor[x] == x; }
    vll factorList(ll x)
    {
        vll res;
        if (x == 0)
            return res;
        while (x != 1)
        {
            res.pb(prime_factor[x]);
            x /= prime_factor[x];
        }
        return res;
    }
    vpll factor(ll x)
    {
        return rle(factorList(x));
    }
};

