vector<int> solve(int n) {
    vector<int> ret;
    vector<int> table(n + 1);
    rep3(i, 2, n + 1) {
        if (table[i] == 1) continue;
        rep3(j, 2, n + 1) {
            if (i * j > n) break;
            table[i * j] = 1;
        }
    }
    rep3(i, 2, n + 1) if (table[i] == 0) ret.eb(i);
    return ret;
}

