vector<bool> Sieve(int N) {
	vector<bool> isPrime(N + 1, true);
	isPrime[0] = false;
	isPrime[1] = false;

	for (int i = 2; i <= N; i++)
		if (isPrime[i])
			for (int j = 2; i * j <= N; j++)
				isPrime[i * j] = false;

	return isPrime;
}

int main()
{
	int N;
	cin >> N;

	auto prime = Sieve(N);

	vll count(N + 1, 0);
	for (int i = 1; i <= N; i++) {
		for (int j = 1; j <= i; j++) {
			if (!prime[j]) continue;
			if (i % j == 0) {
				int tmp = i;
				while (tmp % j == 0) {
					count[j]++;
					tmp /= j;
				}
			}
		}
	}

	int ans = 1;
	for (int i = 2; i <= N; i++) {
		if (count[i] == 0) continue;
		ans = ans * ((count[i] % MOD + 1) % MOD) % MOD;
	}

	cout << ans << endl;


	return 0;
}

