const int MOD = 1e9 +7 ;

vector<pair<long long, long long> > prime_fac( long long N ){
    vector<pair<long long, long long> > res;

    for(int i=2; i*i <=N; ++i){
        if( N % i ==0 ){
            long long ex = 0;
            while( N % i == 0 ){
                ex++;
                N /= i;
            }
            res.push_back({i, ex});
        }
    }

    if(N != 1){
        res.push_back({N, 1});
    }
    return res;
}

