void solve(void){
    //prime_table
    rep(MAX, i) prime[i] = true;
    prime[0] = prime[1] = false;
    Rep(2, MAX, i) {
        if (prime[i]) {
            for (int k = 2; i * k <= MAX; k++){
                prime[i*k] = false;
            }
        }
    }
    int N;
    scanf("%d\n", &N);
    Rep(2, N, n){
