ll prime_factorial_cnt(ll n, ll p){
    ll res = 0, pd = p;
    while(n >= p){
        res = res + n / p;
        p *= pd;
    }

    return res;
}

vector<ll> prime_vec(int n){
    vector<ll> res;
    for(int i = 2;i <= n;i++){
        if(prime[i] == 0){
            res.push_back(i);
            for(int j = i;j <= n;j += i){
                prime[j] = 1;
            }
        }
    }

    return res;
}

