void searchPrime(vector<int> &prime, int N) {
    vector<int> search;
    for(int i = 2; i <= N; i++) {
        search.push_back(i);
    }

    while(search.size() != 0) {
        int first = search[0];
        prime.push_back(first);
        search.erase(search.begin());
        for(auto itr = search.begin(); itr != search.end();) {
            if(*itr % first == 0){
                search.erase(itr);
            }
            else    itr++;
        }
    }
}

