vector<pi> factorialPrimeFactor(ll num){

    //素因数と指数部の並び
    ll j = 0;
    vector<pi > PF;

    for(ll i = 2; i < prime.size(); i++){
        if(prime[i] == false) continue;
        if(i > num) break;

        PF.push_back(make_pair(i, 0));
        //cout << PF.size() << endl;
        ll cn = 1;
        while(pow(i, cn) < num ){
            //cout << "cn "<< PF[j].second << endl;
            PF[j].second += num / pow(i, cn);
            cn++;
        }
        j++;
    }

    return PF;
}

