    }
    ll cnt = 0;
    ll ans = 1;
    for(int i = 0; i < primes.size(); i++){
        int cur = primes[i];
        int total = 0;
        while(cur <= N){
            total += (N/cur);
            cur = cur*primes[i];
        }
        if(total!=0) ans *= (total+1);
        ans %= MOD;
    }
    P(ans%MOD);
    return 0;
}

