void bunkai(int n)
{
    //割る数の初期値
    int a = 2;
    while (n >= a * a)
    {
        if (n % a == 0)
        {
            SO[a]++;
            n /= a;
        }
        else
        {
            a++;
        }
    }
    if (n != 1)
        SO[n]++;
}

