vector<pair<ll, int>> factorize(ll n) {
  vector<pair<ll, int>> res;
  for (ll i = 2; i*i <= n; i++) {
    if (n%i != 0) continue;
    res.eb(i,0);
    while (n%i == 0) {
      n /= i;
      res.back().se++;
    }
  }
  if (n != 1) res.eb(n,1);
  return res;
}

