void createSieve(ll n)
{
	smp = vector<ll>(n+1);

	for(ll i = 2; i <= n; i++)
	{
		if(smp[i] == 0)
		{
			smp[i] = i;
			p.pb(i);
		}

		for(ll j = 0; j < p.size() and p[j] <= smp[i] and i*p[j] <= n; j++)
			smp[i*p[j]] = p[j];
	}
}

map<ll, ll> getFactors(ll n)
{
	map<ll, ll> ans;
	while(n > 1)
	{
		int aux = smp[n];
		ans[aux]++;
		n /= aux;
	}

	return ans;
}

void update(map<ll, ll> &c, map<ll, ll> &o)
{
	for(pair<ll, ll> x: o)
		c[x.fi] += x.se;

	return;
}

