#define ll long long

// Sieve of Erastosthenes の実装
vector<long long> erast(long long n) {
    vector<long long> primes, sieve;
    // 篩の初期化
    for(long long i=2; i<n+1; i++) {
        sieve.push_back(i);
    }
    while(!sieve.empty()) {
        long long ptr = sieve.front();
        primes.push_back(ptr);
        for(auto it = sieve.begin(); it != sieve.end();) {
            if(*it%ptr==0) {
                it = sieve.erase(it);
            } else {
                ++it;
            }
        }
    }
    return primes;
}

int main() {
    ll n; cin >> n;
    vector<ll> prime = erast(n);
    ll ans = 1;
    map<ll, ll> factors;
    for(ll i=1; i<n+1; i++) {
        for(auto p:prime) {
            ll c_n = i;
            while(true) {
                if(c_n%p==0) {
                    c_n = c_n/p;
                    if(c_n>0) {
                        if(factors.count(p)==0) {
                            factors[p] = 1;
                        } else {
                            factors[p] += 1;
                        }
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
        }
    }
    for(auto f:factors) {
        ans *= (f.second+(ll)1);
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

