vector<pair<ll, ll>> getFactor(ll x) {
    vector<pair<ll, ll>> result;
    for (ll i = 2; i * i <= x; i++) {
        ll num = 0;
        while (x % i == 0) {
            x /= i;
            num++;
        }
        if (num) {
            result.push_back({i, num});
        }
        if (x <= 1) {
            break;
        }
    }
    if (x > 1) {
        result.push_back({x, 1});
    }
    return result;
}

