// Sieve of Eratosthenes
void eratosthenes ()
{
    // init
    for (int i=0; i<array_size; ++i){
        if(i < 2 || (i % 2 == 0 && i != 2) || (i % 3 == 0 && i != 3)){
            is_prime[i] = 0;
        }
        else  {
            is_prime[i] = 1;
        }
    }
    int itr = 0;
    while(itr <= check_p){
        if(is_prime[itr]){
            prime_number.push_back(itr);
            for (int i=2; itr*i<=array_size; ++i){
                is_prime[itr*i] = 0;
            }
        }
        itr++;
    }
    for(int i=itr; i<array_size; ++i){
        if(is_prime[i]){
            prime_number.push_back(i);
        }
    }
    /*
    int j=0;
    for(auto itr=prime_number.begin(); itr!=prime_number.end(); ++itr){
        cout << ++j << ":" << *itr << endl;
    }
    */
}

void factorize(int n){
    int num;
    num = n;
    for(auto itr = prime_number.begin(); itr != prime_number.end(); ++itr){
        while(num % *itr == 0){
            num = num / *itr;
            fact[*itr]++;
        }
    }
    if(num != 1){
        fact[num]++;
    }
}

