int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin >> n;
  sieve_of_eratosthenes(1e7);
  long long res = 1;
  for (auto &pc : prime_factorize_factorial(n)) {
    res *= pc.second + 1; res %= MOD;
  }
  cout << res << '\n';
  return 0;
}

