}

vector<pair<ll,ll>> prime_factorize(ll N){
    vector<pair<ll,ll>> res;
    for (ll a = 2; a * a <= N; ++a){
        if (N%a != 0) continue;
        ll ex = 0; //指数
        while ( N%a == 0) {
            ++ex;
            N /= a;
        }
        // {}でpairの形としてpush出来る
        res.push_back({a,ex});
    }
    //余りがあれば素数
    if (N!=1) res.push_back({N,1});
    return res;
}
