vector<int> prime;

bool isprime(int N) {
    if (N == 2) return true;
    else if (N % 2 == 0) return false;
    else if (N == 1) return false;
    for (int i = 3; i <= sqrt(N); i++) {
        if (N % i == 0)return false;
    }
    return true;
}

void factorial(int N, vector<int>& cnt) {
    int i = 0;
    while (!isprime(N)) {
        int p = prime[i];
        if (N % p == 0) {
            cnt[p]++;
            N /= p;
        }
        else i++;
    }
    if (isprime(N)) cnt[N]++;
}

int main() {
    int N;
