    vector<int> cnt(N + 1);
    Rep(i, N + 1) {
        if (isprime(i)) prime.push_back(i);
    }
    for (int i = 2; i <= N; i++) factorial(i, cnt);
    ll ans = 1;
    for (int i = 0; i < prime.size(); i++) {
        if (cnt[prime[i]] >= 1) {
            ans *= cnt[prime[i]] + 1;
            ans %= 1000000007;
        }
    }
    cout << ans << endl;
    return 0;
}

