//n未満の自然数のでのエラトステネスの篩
//O(nlog(logn)) , 実質O(n)
bool* eratosthenes(int n) {
	bool* array = new bool[n];
	for (int i = 0; i < n; i++)array[i] = true;
	for (int i = 2; i < n; i++) {
		if (!array[i])continue;
		int t = 2*i;
		while (t < n) {
			array[t] = false;
			t += i;
		}
	}
	return array;
}

int M = 1000000007;

void solve() {
	int N;
	cin >> N;
	bool* arr = eratosthenes(N+1);
	int ans = 1;
	for (int p = 2; p <= N; p++) {   //各素数p
		if (!arr[p])continue;
		int c = 0;   //pで何回割れる?
		for (int n = 2; n <= N; n++) {
			int old = n;
			while (old%p == 0) {
				c++;
				old /= p;
			}
		}
		ans = (ans*(c+1)) % M;
	}
	cout << ans << endl;
	delete arr;
	return;
}

