        for(auto p: prime){
            while(num%p==0){
                div[p]++;
                num/=p;
            }
        }
    }

    ll res = 1;
    for(auto d: div){
        res *= (d.second+1)%mod;
        res = res%mod; 
    }

    cout << res << endl;

}

