std::map<int, int> prime_factorize(int d) {
  std::map<int, int> primes;

  if (d % 2 == 0) {
    primes.insert(std::make_pair(2, 0));
    while(d % 2 == 0) {
      d /= 2;
      primes[2]++;
    }
  }

  int factor = 3;
  while(d > 1) {
    if (d % factor == 0) {
      primes.insert(std::make_pair(factor, 0));
      while(d % factor == 0) {
        d /= factor;
        primes[factor]++;
      }
    }
    factor += 2;
  }
  return primes;
}

int main() {
  int N; std::cin >> N;
  std::map<int, int> m;
  for (int i = 2; i <= N; ++i) {
    for (auto pair : prime_factorize(i)) {
      m[pair.first]+=pair.second;
    }
  }

  LL ans = 1;
  for (auto pair : m) {
    ans *= pair.second + 1;
    ans %= kMod;
  }
  std::cout << ans << std::endl;
}

