vector <int> allPrimes; 

void sieve(int n) 
{ 
    vector<bool> prime(n+1, true); 
    for (int p=2; p*p<=n; p++) { 
        if (prime[p] == true) { 
            for (int i=p*2; i<=n; i += p) 
                prime[i] = false; 
        } 
    } 
    for (int p=2; p<=n; p++) {
        if (prime[p]) {
           allPrimes.push_back(p); 
        }
    }
} 

int solve() 
{ 
    int  n; cin>>n; 
    sieve(n) ; 
    int result = 1;
    for (int  i=0; i < allPrimes.size(); i++) 
    { 
        int p = allPrimes[i]; 
        int exp = 0; 
        while (p <= n) { 
            exp = exp + (n/p); 
            p = p*allPrimes[i]; 
        } 
        result = (result*(exp+1))%1000000007; 
    } 
    cout << result << endl; 
}


signed main()
{
    int n=1; // cin>>n;
    while (n--) solve();
    return 0;
}

