map<int,int> primediv(int n)
{
    assert(n > 1);

    int d = 2;
    int ulimit = sqrt(n);
    map<int,int> res;

    while (d <= ulimit) {
        if (n % d == 0) {
            res[d]++;
            n /= d;
            ulimit = sqrt(n);
        } else
            d += 1;
    }
    if (n != 1)
        res[n]++;
    return res;
}

