void prime_factorial(ll n, map<ll, ll> &fact) {

    for(ll i = 2; i * i <= n; i++) {
        if(n % i == 0) {
            while (n % i == 0) {
                fact[i]++;
                n /= i;
            }
        }
    }

    if(n > 1) { fact[n]++; }
}
int main() 
{
    ll n;
    cin >> n; 

    ll ans = 1;
    map<ll, ll> fact;

    for(int i = 1; i <= n; i++) {
        prime_factorial(i, fact);
    }

    for(auto prime : fact) {
        //cout << "pow(" << prime.first << "," << prime.second << ")" << endl;
        ans *= (prime.second + 1);
        ans %= IMOD; 
    }

    cout << ans << endl;

    return 0;
}

