const int mod = 1e9+7;
int n, a[1005], p[1005], c[1005], m;
long long ans = 1;
void siftp(int maxn) {
    a[0] = a[1] = 1;
    for (int i = 2; i < maxn; i++) {
        if (!a[i]) p[m++] = i;
        for (int j = 0; j < m; j++) {
            if (i * p[j] >= maxn) break;
            a[i*p[j]] = 1;
            if (i % p[j] == 0) break;
        }
    }
}
void handle(int x) {
    for (int i = 0; i < m && x > 1; i++) {
        while (x % p[i] == 0) {
            c[i] += 1;
            x /= p[i];
        }
    }
}
int main() {
    siftp(1005);
    scanf("%d", &n);
    for (int i = 2; i <= n; i++)
        handle(i);
    for (int i = 0; i < m; i++)
        ans = ans * (c[i] + 1) % mod;
    cout << ans << endl;
    return 0;
}

