const ll mod = 1e9+7;

struct Sieve { // 篩
  int n;
  vector<int> f, primes;
  Sieve(int n=1):n(n), f(n+1) {
    f[0] = f[1] = -1;
    for (ll i = 2; i <= n; ++i) {
      if (f[i]) continue;
      primes.push_back(i);
      f[i] = i;
      for (ll j = i*i; j <= n; j += i) {
        if (!f[j]) f[j] = i;
      }
    }
  }
  bool isPrime(int x) { return f[x] == x;} // 素数判定
  vector<int> factorList(int x) { // 素因数列挙
    vector<int> res;
    while (x != 1) {
      res.push_back(f[x]);
      x /= f[x];
    }
    return res;
  }
  vector<P> factor(int x) { // 素因数分解(ランレングス圧縮的なもの)
    vector<int> fl = factorList(x);
    if (fl.size() == 0) return {};
    vector<P> res(1, P(fl[0], 0));
    for (int p : fl) {
      if (res.back().first == p) {
        res.back().second++;
      }
      else {
        res.emplace_back(p, 1);
      }
    }
    return res;
  }
};


int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int n;
  cin >> n;
  map<int, ll> mp;
  Sieve s(n);
  REP(i,n+1) {
    vi fl = s.factorList(i);
    for(int x : fl) mp[x]++;
  }
  ll ans = 1;
  for(P p : mp) {
    ans *= p.se+1;
    ans %= mod;
  }
  cout << ans << endl;
}

