void Prime_table(bool *is_prime, int n){
	fill(is_prime + 2, is_prime + n + 1, 1);
	repU(i,2,n/2) is_prime[i * 2] = 0;
	is_prime[0] = is_prime[1] = 0;
	int p = 3;
	while(p * p <= n){
		for(int t = p * 3; t <= n; t += p * 2) is_prime[t] = 0;
		p += 2;
		while(!is_prime[p]) p += 2;
	}
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);

	int n; cin>>n;
	bool is[1001];
	ll ans = 1;
	Prime_table(is,n);
	rep1(i,n){
		if(is[i]){
			ll t = i,u = 0;
			while(t <= n){
				u += n / t;
				t *= i;
			}
			ans *= (1 + u);
			ans %= MOD;
		}
	}
	cout<<ans<<endl;

	return 0;
}

