    for(int i=2;i*i<=n;i++){
        if(n%i==0) return false;
    }
    return true;
}

ll kosuu(ll n,ll m){
    ll D[1000]={};
    for(int i=2;i<=n;i++){
        if(prime(i)){
            D[i]++;
            continue;
        }
        ll z=i;
        for(int j=2;j<=i&&z!=1;){
            if(z%j!=0||!prime(j)){
                j++;
                continue;
            }
            z/=j;
            D[j]++;
        }
    }
    ll ans=1;
    for(int i=2;i<1000;i++){
        ans=ans*(D[i]+1)%m;
    }
    return ans;
}

