constexpr const u64 MODNUM = 1000000007;

vector<int> prime_list() {
    bitset<1001> nps;
    nps[0] = nps[1] = true;
    for (int i = 2; i <= 1000; i++) {
        if (nps[i]) continue;
        for (int n = i*2; n <= 1000; n += i) {
            nps[n] = true;
        }
    }
    vector<int> primes;
    for (int i = 2; i <= 1000; i++) {
        if (!nps[i]) primes.push_back(i);
    }
    return primes;
}

void add_facts(int n, vector<int> const &primes, vector<u64> &facts) {
    for (int i = 0; n != 1; i++) {
        while (n % primes[i] == 0) {
            n /= primes[i];
            facts[i]++;
        }
    }
}

int main() {
    auto primes = prime_list();

    int N; cin >> N;
    vector<u64> facts(primes.size());
    for (int n = 1; n <= N; n++) {
        add_facts(n, primes, facts);
    }

    u64 num = 1;
    for (int i = 0; i < primes.size(); i++) {
        num *= (facts[i] + 1) % MODNUM;
        num %= MODNUM;
    }
    cout << num << endl;

    return 0;
}

