vector<pair<int,int>> prime_factorize(int N){

    vector<pair<int,int>> num;

    for(int i=2; i<=N; i++){
        if(N%i != 0) continue;
        int e = 0;
        while(N%i==0){
            e++;
            N /= i;
        }
        num.push_back({i,e});
    }

    if(N != 1) num.push_back({N,1});

    return num;
}

