std::map<int, int> decomposition_prime(int n){
  std::map<int, int> ret;
  for(int i=2; i<=n; i++){
    while(n%i == 0){
      if(ret.find(i) == ret.end()) ret[i] = 0;
      ret[i]++;
      n /= i;
    }
  }
  return ret;
}

std::map<int, int> elem_add(const std::map<int, int>& a, const std::map<int, int>& b){
  std::map<int, int> ret = a;
  for(auto elem: b){
    if(ret.find(elem.first) == ret.end()) ret[elem.first] = 0;
    ret[elem.first] += elem.second;
  }
  return ret;
}

int main(void){
  int n;
