  std::map<int, int> final;
  for(int i=1; i<=n; i++){
    final = elem_add(final, decomposition_prime(i));
  }

  llint result = 1;
  for(auto elem: final){
    result = MULT(elem.second+1, result);
  }
  std::cout << result << std::endl;


  return 0;
}

