bool visit[maxn];
int a[maxn], na = 0;
int C[maxn];
LL dp[maxn];

void init() {
	memset(visit, true, sizeof(visit));
	visit[0] = visit[1] = false;
	a[na++] = 1;
	for (int i=2; i<maxn; ++i) {
		if (visit[i]) {
			a[na++] = i;
			for (int j=i+i; j<maxn; j+=i)
				visit[j] = true;
		}
	}
}

inline int getId(int x) {
	return lower_bound(a, a+na, x) - a;
}

void solve(int n) {
	if (n == 1) {
		puts("1");
		return ;
	}

	for (int i=2; i<=n; ++i) {
		int x = i;
		for (int j=2; j*j<=x; ++j) {
			if (x%j == 0) {
				int id = getId(j);
				while (x%j == 0) {
					x /= j;
					++C[id];
				}
			}
		}
		if (x > 1) {
			int id = getId(x);
			++C[id];
		}
	}

	dp[0] = 1;
	for (int i=1; i<na; ++i) {
		// if (C[i] == 0) {
			// dp[i] = dp[i-1];
			// continue;
		// }

		dp[i] = dp[i-1] * (1 + C[i]) % mod;
	}

	LL ans = dp[na-1];
	cout << ans << endl;
}

