int legendre(int n){

    ll res = 1;
    for (int i=1; i<=n; i++){
        if(is_prime[i]){

            ll sum_expo = 0;
            ll pot = 1;
            while((n/pot)>0){
                pot = pot * i;
                sum_expo += n/pot;
            }

            if(sum_expo == 0) break;
            res = (res * (sum_expo + 1))%MAX;
        }
    }
    return res;
}

