        }
    }
    return 1;
}
int calculeazaPutere(int nr, int prime)
{
    int P = prime;
    int sum = 0;
    while (nr >= P)
    {
        sum += nr / P;
        P = P * prime;
    }
    return sum;
}
int main()
{
    int n;
    cin >> n;
    long long nrDivs = 1;
    for (int i = 2; i <= n; i++)
    {
        if (isPrime(i) == 1)
        {
            nrDivs = ((nrDivs % MOD) * ((calculeazaPutere(n, i) + 1) % MOD)) % MOD;
        }
    }
    cout << nrDivs;
    return 0;
}

