// primeFactorize {{{
map<i64, int> primeFactorize(i64 n) {
    map<i64, int> ret;
    for (i64 i = 2; i * i <= n; ++i) {
        while (n % i == 0) {
            ++ret[i];
            n /= i;
        }
    }
    if (n != 1) ret[n] = 1;
    return ret;
}
