    int i = 2;

    FORq(j,2,N){
        int n = j;

        while(i<=n){
            if (!IsPrime(i)){
                i++;
                continue;
            }

            if ((n%i) == 0){
                a[i] = (a[i] + 1) % p;
                n = n/i;
                continue;
            }else{
                i++;
                continue;
            }
        }
        i = 2;
    }

    long long ans = 1;

    REP(i,MAX){
        ans = (ans * ((1 + a[i]) % p)) % p;
    }

