const int MOD = 1000000007; // 998244353;
/*-------------------------------------------------*/
struct osa_k {
  osa_k(int val = 10000000) {
    least_prime_factor.assign(val + 1, -1);
    least_prime_factor[0] = 0;
    least_prime_factor[1] = 1;
    FOR(i, 2, val + 1) if (least_prime_factor[i] == -1) {
      least_prime_factor[i] = i;
      for (int j = i * i; j <= val; j += i) {
        if (least_prime_factor[j] == -1) least_prime_factor[j] = i;
      }
    }
  }

  vector<pair<int, int> > query(int val) {
    vector<pair<int, int> > res;
    while (val > 1) {
      int prime = least_prime_factor[val], exponent = 0;
      while (least_prime_factor[val] == prime) {
        ++exponent;
        val /= prime;
      }
      res.emplace_back(prime, exponent);
    }
    return res;
  }

private:
  vector<int> least_prime_factor;
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  // freopen("input.txt", "r", stdin);

  int n; cin >> n;
  osa_k osa(n);
  map<int, int> mp;
  FOR(i, 2, n + 1) {
    vector<pair<int, int> > tmp = osa.query(i);
    for (pair<int, int> pr : tmp) mp[pr.first] += pr.second;
  }
  long long ans = 1;
  for (pair<int, int> pr : mp) (ans *= pr.second + 1) %= MOD;
  cout << ans << '\n';
  return 0;
}

