vector<int> prime;

void calcPrime(int n){

    bool isPrime[n+1];
    fill(isPrime, isPrime+n+1, true);
    isPrime[0] = false;
    isPrime[1] = false;

    int i1 = 2; 
    while(i1 <= n){
        if(isPrime[i1] == false){
            i1++;
            continue;
        }

        int temp = i1;
        int i2 = i1*2;
        while(i2 <= n){
            isPrime[i2] = false;
            i2 += temp;
        }
        i1++;
    }

    prime.clear();
    for(int i=2; i<=n; i++){
        if(isPrime[i]){
            prime.push_back(i);
        }
    }
}

int main(){

    int n; cin >> n;

    calcPrime(n);

    // for(auto x : prime){
    //     cout << x << endl;
    // }

    map<int, int> mp;

    rep2(i, 2, n+1){
        int k = 0;
        int itemp = i;
        while(true){
            if(itemp % prime[k] == 0){
                itemp /= prime[k];
                mp[prime[k]]++;
            }
            else{
                k++;
                if(prime[k] > n){
                    break;
                }
            }
        }
    }

    ll ans = 1;
    for(auto x : mp){
        // cout << x.first << " " << x.second << endl;
        ans = (ans * (x.second + 1)) % ll(1e9+7);
    }

    cout << ans;

    return 0;
}

