map<ll, ll>prime_factor(ll n) {
	map<ll, ll>ans;
	for (ll i = 2; i * i <= n; i++) {
		while (n % i == 0) {
			ans[i]++;
			n /= i;
		}
	}
	if (n != 1)ans[n] = 1;
	return ans;
