#define MOD 1000000007

int n;
map<int, int> mp;

void prime_decomposition(int N) {
  int i = 2;

  while (i * i <= N) {
    if (N % i == 0) {
      N /= i;
      mp[i]++;
    } else {
      i++;
    }
  }
  mp[N]++;

  return;
}

void solve() {
  int i;
  ll ans = 1;

  for (i = 2; i <= n; i++) {
    prime_decomposition(i);
  }

  for (auto p : mp) {
    ans = ans * (p.second + 1) % MOD;
  }

  cout << ans << "\n";

  return;
}

int main() {
  int i;

  cin >> n;

  solve();

  return 0;
}

