    class Eratosthenes {
    public:
        // Set up common tasks independent from input values.
        virtual void initialize() {}

        // Find prime numbers in range [0, x).
        virtual void generate(const int64_t x) = 0;

        // Find prime numbers in range [from, to).
        virtual void generate(const int64_t from, const int64_t to) = 0;

        // Returns the number of counted prime numbers.
        virtual int64_t count() = 0;

        virtual bool prime(int x) = 0;

        // Returns the implemented version.
        virtual int32_t version() = 0;

        inline uint64_t PopCnt(uint64_t);
        inline int BitToIndex(uint8_t);
    };

    uint64_t Eratosthenes::PopCnt(uint64_t bits) {
        bits = (bits & 0x5555555555555555ULL) + ((bits >> 1) & 0x5555555555555555ULL);
        bits = (bits & 0x3333333333333333ULL) + ((bits >> 2) & 0x3333333333333333ULL);
        bits = (bits & 0x0f0f0f0f0f0f0f0fULL) + ((bits >> 4) & 0x0f0f0f0f0f0f0f0fULL);
        return (bits * 0x0101010101010101ULL) >> (64 - 8);
    }

    int Eratosthenes::BitToIndex(uint8_t b) {
        switch (b) {
            case 1 << 0:
                return 0;
            case 1 << 1:
                return 1;
            case 1 << 2:
                return 2;
            case 1 << 3:
                return 3;
            case 1 << 4:
                return 4;
            case 1 << 5:
                return 5;
            case 1 << 6:
                return 6;
            case 1 << 7:
                return 7;
        }
        return -1;
    }


