void PrimeEnumeration(int n) {
  FOR(i, 2, n+1) {
    bool flag = true;
    FOR(j, 2, i) {
      if (j*j > i) break;
      if (i%j == 0) {
        flag = false;
        break;
      }
    }
    if (flag) prime.push_back(i);
  }
}

void PrimeFactorization(int n) {
  for (int i = 0; n >= prime[i];) {
    if (n%prime[i] == 0) {
      n /= prime[i];
      prime_factor[prime[i]]++;
    } else {
      i++;
    }
  }
}

