        if(n%primes[i]==0){
            fact[primes[i]]++;
            n /= primes[i];
            i--;
        }
    }
}

void sieve(int n){
    for(int i=0;i<=n;i++) is_prime[i] = true;
    is_prime[0] = is_prime[1] = false;
    for(int i=2;i<=n;i++){
        if(is_prime[i]){
            primes.pb(i);
            for(int j=2*i;j<=n;j += i) is_prime[j] = false;
        }
    }
    return;
}

