P bisearch(int l,int r,function<bool(int)> f){
	while(l+1<r){
		int m=(l+r)/2;
		bool flag=f(m);
		if(flag) r=m;
		else l=m;
	}
	return P(l,r);
}
int Sqrt(int n){
	return bisearch(0,n,[n](int x){return x>n/x;}).first;
}
bool square(int n){
	int s=Sqrt(n);
	return s*s==n;
}
int digitsum(int n,int b){
	if(b<2) return -1;
