		Divisor d(i+1);
		vector<P> a= d.pfac();
		rep(j,a.size()) mp[a[j].first]+=a[j].second;
	}
	itr(i,mp) {
		ans*=i->second+1;
		ans%=mod;
	}
	cout<<ans<<endl;
}

