void prdmod(ll& src, const ll& tgt) {
  ll ret = ((src % MOD) * (tgt % MOD)) % MOD;
  if (ret < 0) ret += MOD;
  src = ret;
}

void addmod(ll& src, const ll& tgt) {
  ll ret = ((src % MOD) + (tgt % MOD)) % MOD;
