// Prime factorization of n
// O(\sqrt(n)) time complexity
void factorize(ll n, unordered_map<ll, ll>& out){
    // out.clear();
    while(n % 2 == 0){
        out[2]++;
        n /= 2;
    }
    for(ll p = 3; p * p <= n; p += 2){
        while(n % p == 0){
            out[p]++;
            n /= p;
        }
    }
    if(n > 2){
        out[n]++;
    }
}

int main(){
    ll n;
    cin >> n;
    unordered_map<ll, ll> p;
    for(ll x = 2; x <= n; ++x){
        factorize(x, p);
    }
    mint ans = 1;
    for(auto it = p.begin(); it != p.end(); ++it){
        ans *= (it->second + 1);
    }
    cout << ans << endl;
    return 0;
}

