vector<P> factorize(int N) {
  vector<P> res;
  FOR(i,2,(int)sqrt(N)+1) {
    if (N%i==0) {
      int cnt=0;
      while (N%i==0) {
        N/=i;
        cnt++;
      }
      res.push_back({i,cnt});
    }
  }
  if (N>1) res.push_back({N,1});
  return res;
}

