        rep(j,F.size()) {
            if(!S.count(F[j].first)) {
                S[F[j].first]=F[j].second;
            }
            else {
                S[F[j].first] += F[j].second;
            }
        }

    }

    ll ans = 1;
    for (auto p:S) {
        ans *= p.second+1;
        ans %= MOD;
    }
    cout << ans << endl;
}

