}

void set(int n) {
    M[n >> 3] |= (0x80 >> (n & 0x07));
}

bool test(int n) {
    return M[n >> 3] & (0x80 >> (n & 0x07));
}

void prime_set(int n) {
    set(0); set(1);
    for (int i = 2; i * i <= n; i++)
        if( !test(i) )
            for (int j = i * i; j <= n; j += i)
                set(j);
}

