    init(N);
    prime_set(N);
    for (int i = 2; i <= N; i++) {
        if(!test(i)) {
            long long res = 0;
            for (int temp = i; temp <= N; temp *= i)
                res += N / temp;
            ans *= (res + 1) % MOD;
            ans %= MOD;
        }
    }
    cout << ans << endl;
    return 0;
}

