map<ll,ll> v;

const ll mod = pow(10,9)+7;
ll max_div;

void decom(ll n)
{
    // 割る数の初期値
    ll a = 2;
    // √n ≧ a ( n ≧ a * a ) の間ループ処理
    while (n >= a * a) {
        // a で割り切れたら、a は素因数
        // そして、割られる数を a で割る
        // a で割り切れなかったら、 a を 1 増加させる
        if (n % a == 0) {
            v[a]++;
            if(a>max_div) max_div = a;
            n /= a;
        } else {
            a++;
        }
    }
    // 最後に残った n は素因数
    v[n]++;
    if(n>max_div) max_div = n;
}


