        N = n;
        vector<bool> v(n+1, true);
        v[0] = false;
        v[1] = false;
        int m = sqrt(n);
        for(int i=2; i<=m; i++){
            if(v[i]){
                int j = i*2;
                while(j <= n){
                    v[j] = false;
                    j += i;
                }
            }
        }
        for(int i=0; i<=n; i++){
            if(v[i]){
                table.push_back(i);
            }
        }
    }

    bool is_prime(ll n){
        if(n < 2){
            return false;
        }
        ll m = sqrt(n);
        for(ll i=2; i<=m; i++){
            if(n%i == 0){
                return false;
            }
        }
        return true;
    }

    map<ll,int> factorization(ll n){
        static map<ll,int> mp;
        for(ll i=2; i*i<=n; i++){
            while(n%i == 0){
                n /= i;
                mp[i]++;
            }
        }
        if(n > 1){
            mp[n]++;
        }
        return mp;
    }
};

