		for (auto pa : vec) {
			sum[pa.first] += pa.second;
		}
	}
	ll ans = 1;
	Rep(i, 2, n + 1) {
		ans *= (sum[i] + 1);
		ans %= mod;
	}

	cout << ans << endl;

	return 0;
}

