map<ll, ll> factorize(ll g){
    map<ll, ll> ret;
    if(g == 1){
        ret[1]++;
        return ret;
    }
    ll d = 2;
    while(d*d <= g){
        if(g % d == 0){
            ret[d]++;
            g /= d;
            while(g % d == 0){
                ret[d]++;
                g /= d;
            }
