// vectorじゃなくてmapでもいい
vector<pair<ll, ll>> prime_factorize(ll x) {
    vector<pair<ll, ll>> res;
    // 素因子2から始める
    for (ll p = 2; p <= x; p++) {
        if (x % p != 0) continue;
        int num = 0;
        // 割り切れる回数をカウント
        while (x % p == 0) {
            num++;
            x /= p;
        }
        res.push_back(make_pair(p, num));
    }
    return res;
}

