#include <cstdio>
int factor[1001];
const int MOD = 1e9 + 7;

void factorize(int N) {
  for (int i = 2; i * i <= N; ++i) {
    while (N % i == 0) {
      factor[i]++;
      N /= i;
    }
  }
  if (N != 1)
    factor[N]++;
}
int main() {
  int N;
  scanf("%d", &N);
  for (int i = 1; i <= N; ++i)
    factorize(i);
  int ans = 1;
  for (int i = 2; i <= N; ++i)
    ans = 1LL * ans * (1 + factor[i]) % MOD;
  printf("%d\n", ans);
  return 0;
}

