typedef long long ll;

using namespace std;

/* least common multiple */
template <typename T> // ll or int
T lcm(T x, T y) {
	T res = 0;
	T mod = x % y;
	if (mod == 0)
		res = y;
	else
		res = lcm(y, mod);

	return res;
}

/* greatest common divisor */
template <typename T> // ll or int
T gcd(T x, T y) {
	T res = 0;
	T lcm_v = lcm(x, y);

	res = x / lcm_v * y;

	return res;
}

int main()
{
	int n;
	cin >> n;

	ll mod = 1e9 + 7;
	ll res = 1;
	map<int, int> mp = {};

	rep (i, 1, n + 1) {
		int tmp = i;
		int div = 2;
		while (tmp > 1) {
			if (tmp % div == 0) {
				mp[div]++;
				tmp /= div;
			} else {
				div++;
			}
		}
	}

	for (auto it = mp.begin(); it != mp.end(); it++) {
		res *= (it->second + 1);
		res %= mod;
	}

	cout << res << endl;
	return 0;
}

