//　素因数分解
void prime_factorize(ll prime) {
    if(prime == 1) return;
    ll a = 2;
    while( a*a <= prime){
        if(prime % a == 0){
            res[a] += 1;
            prime /= a;
        }
        else ++a;
    }
    res[prime] += 1;
    return;
}


