void Eratosthenes(int N){
	for(int i = 0; i < N; i++){
		IsPrime[i] = 1;
	}
	for(int i = 2; i < sqrt(N); i++){
		if(IsPrime[i]){
			for(int j = 0; i * (j + 2) < N; j++){
				IsPrime[i *(j + 2)] = 0;
			}
		}
	}
    for (int i = 2; i < N; i++) if(IsPrime[i]) Prime.push_back(i);
}

int main(){
    int n;
    cin >> n;
    Eratosthenes(1000);
    int divisor[1010] = {0};
    for (int i = 1; i <= n; i++) {
        int tmp = i;
        for (int j = 0; j < Prime.size(); j++) {
