            while(tmp % p == 0){
                tmp /= p;
                divisor[p]++;
            }
        }
    }
    ll ans = 1;
    for (int i = 1; i < 1000; i++) {
        ans = ans * (divisor[i] + 1) % 1000000007;
    }
