namespace NyaGadget
{
	/**
	@brief 素因数分解ライブラリ
	@note
	 nを素因数分解する。
	 ans[i]がnだったとき、素因数分解して得られた積のなかにn個の素数iが含まれていることを表す。
	 例えば n=12 のとき ans[2] = 2, ans[3] = 1 となるので 12 = 2 * 2 * 3 と分かる。
	**/
	void PrimeFactorization(ll n, map<ll, ll>& ans)
	{
		for (ll i = 2; i * i <= n; i++)
		{
			while (n % i == 0)
			{
				ans[i]++;
				n /= i;
			}
		}
		if (n != 1)
			ans[n]++;
	}
}

using namespace NyaGadget;
using mll = ModLL<1000000007>;

int main(void)
{
	ll n; cin >> n;


	vector<ll> pf_count(n+1);
	map<ll, ll> pf;
	rep(i, 2, n + 1)
	{
		PrimeFactorization(i, pf);

		each(e, pf)
			pf_count[e.first] = e.second;
	}

	mll ans = 1;
	each(e, pf_count)
		ans *= (e + 1);

	cout << ans;
	return 0;
}

