void findPrimeNumber(){
    for(int i = 2; i < N; i++){
        bool flag = true;
        for(int j = 2; j < i; j++){
            if(i % j == 0) flag = false;
        }
        if(flag) prime.push_back(make_pair(i, 0));
    }
    return;
}

int main(){
    int n;
    cin >> n;

    findPrimeNumber();

    for(int i = 1; i <= n; i++)
        rep(j, prime.size()){
            int p = prime[j].first, copy = i;
            if(p > i) break;
            while(copy % p == 0){
                prime[j].second++;
                copy /= p;
            }
        }

    ll ans = 1;
    rep(i, prime.size()){
        ans = ans * (prime[i].second + 1) % INF;
    }
    cout << ans << endl;
    return 0;
}

