/*
素因数分解をする
自然数xは素因数を持てばそれは\sqrt{x}以下なのでそこまで調べ上げれば良い
*/

typedef long long ll;
const ll mod = 1e9 + 7;

ll decompositPrime(int x){
    std::map<int, int> mp;
    for(int i = 2; i <= x; i++){
        int j = i;
        int a = 2;
        while(j >= a * a){
            if(j % a == 0){
                j /= a;
                mp[a]++;
            }else{
                a++;
            }
        }
        // 最後に残ったjは素因数
        mp[j]++;
    }
    // メイン処理はここ↑
    // ここからは問題に応じて
    // 今回はxの正の約数の個数を求める
    ll sum = 1;
    for(auto iter = mp.begin(); iter != mp.end(); iter++){
        sum = sum * (iter->second + 1) % mod;
    }

    return sum;
}

int main(){
    int N;
    scanf("%d%*c", &N);
    std::cout << decompositPrime(N) << std::endl;
    return 0;
}

