vector<int> makePrimes(int size) {
    size = max(size, 25); // 小さすぎるとバグる
    vector<int> primes;
    bool *flag = new bool[size];

    memset(flag, true, size);

    int limit = sqrt(size);
    REP(i, 2, limit) {
        if(flag[i]) {
            primes.push_back(i);
            for(int j=i; j<size; j+=i) {
                flag[j] = false;
            }
        }
    }
    REP(i, limit, size) {
        if(flag[i]) {
            primes.push_back(i);
        }
    }

    delete[] flag;
    return primes;
}

map<int, int> prime_div(long long N, vector<int> primes) {
    map<int, int> m;
    m.insert(make_pair(1,1));
    while(true) {
        bool ok = false;
        for(int i=0; i<primes.size(); i++) {
            if(N%primes[i] == 0) {
                if(m.find(primes[i]) != m.end()) m[primes[i]] += 1;
                else m.insert(make_pair(primes[i], 1));
                N /= primes[i];
                break;
            }
            if(primes[i] > N) {
                ok = true;
                break;
            }
        }
        if(ok) break;
    }
    return m;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

