    REP(i,1,N+1) {
        map<int, int> pdi = prime_div(i,primes);
        REP(itr,pdi.begin(),pdi.end()) {
            if(pd.find(itr->first) != pd.end()) pd[itr->first] += pdi[itr->first];
            else pd.insert(*itr);
