using i64 = int64_t;

constexpr i64 MOD = 1e9 + 7;

void prime_factor(i64 n, map<i64, i64> &mp) {
    for (i64 i = 2; i * i <= n; i++) {
        while (n % i == 0) {
            mp[i]++;
            n /= i;
        }
    }
    if (n != 1)
        mp[n]++;
}

int main(){
    i64 n;
    cin >> n;
    map<i64, i64> mp;
    for(i64 i=1;i<=n;++i)prime_factor(i, mp);
    i64 ans = 1;
    for(auto e: mp){
        ans *= e.second + 1;
        ans %= MOD;
        //cout << e.first << ":" << e.second << endl;
    }
    cout << ans << endl;

    return 0;
}

