int exp[N_MAX]; //exponent(べき指数)の略　素数のべき指数の数を保存する変数。


void pn(int n){ //prime_numbers(素数)の略
  for(int i = 2; i <=n; i++){
    for(int j = 2*i; j <=n; j+=i){
      pn_flag[j] = 1;
    }
  }
}

ull fpn(int N){//factorization_in_prime_numbers(素因数分解)の略
  ull cnt=1;
  int n;
  for(int i = 2; i <= N; i++){
    n = i;
    for(int j = 2; j <= i; j++){
      if(pn_flag[j] == 0){
        while(n%j == 0){
          n /= j;
          exp[j]++;
        }
      }
    }
  }

  for(int i = 2; i <= N; i++){
    if(exp[i] != 0){
      exp[i]++;
      cnt *= exp[i];
      cnt %= 1000000007;
    }
  }
  return cnt;
}

