const int MOD = 1000000007;

const int MAX = 10000000;
int least_prime_factor[MAX + 1];
void osa_k_init(int num = MAX) {
  memset(least_prime_factor, -1, sizeof(least_prime_factor));
  vector<bool> is_prime(num + 1, true);
  least_prime_factor[0] = 0;
  least_prime_factor[1] = 1;
  is_prime[0] = false;
  is_prime[1] = false;
  FOR(i, 2, num + 1) if (is_prime[i]) {
    least_prime_factor[i] = i;
    for (int j = i * i; j <= num; j += i) {
      is_prime[j] = false;
      if (least_prime_factor[j] == -1) least_prime_factor[j] = i;
    }
  }
}

vector<pair<int, int> > osa_k(int num) {
  vector<pair<int, int> > res;
  while (num > 1) {
    int prime = least_prime_factor[num], exponent = 0;
    while (least_prime_factor[num] == prime) {
      ++exponent;
      num /= prime;
    }
    res.emplace_back(prime, exponent);
  }
  return res;
}

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  // freopen("input.txt", "r", stdin);

  int n; cin >> n;
  osa_k_init(n);
  map<int, int> mp;
  FOR(i, 2, n + 1) {
    auto tmp = osa_k(i);
    for (auto a : tmp) mp[a.first] += a.second;
  }
  long long ans = 1;
  FOR(i, 2, n + 1) if (mp[i] > 0) (ans *= (mp[i] + 1)) %= MOD;
  cout << ans << '\n';
  return 0;
}

