namespace mymod {ll add(ll a, ll b);ll sub(ll a, ll b);ll mul(ll a, ll b);ll power(ll a, ll b);ll div(ll a, ll b);static constexpr ll my_modulus = 1000000007LL;}

ll mymod::add(ll a, ll b){return (a + b) % my_modulus;}
ll mymod::sub(ll a, ll b){return (a + my_modulus - b) % my_modulus;}
ll mymod::mul(ll a, ll b){return ((a % my_modulus) * (b % my_modulus)) % my_modulus;}
ll mymod::power(ll a, ll b){
    if (b == 0) return 1;
    else if (b == 1) return a % my_modulus;
    else if (b % 2 == 0){ll p = power(a, b / 2); return p * p % my_modulus;}
    else return a * power(a, b-1) % my_modulus;
}
ll mymod::div(ll a, ll b){return mul(a, power(b, my_modulus-2));}


