vector<int> preprocess(int n = MAX)
{
    vector<int> res;
    for (int i = 0; i < n; ++i)
        IsPrime[i] = true, MinFactor[i] = -1;
    IsPrime[0] = false;
    IsPrime[1] = false;
    MinFactor[0] = 0;
