        if (IsPrime[i])
        {
            MinFactor[i] = i;
            res.push_back(i);
            for (int j = i * 2; j < n; j += i)
            {
                IsPrime[j] = false;
                if (MinFactor[j] == -1)
                    MinFactor[j] = i;
            }
        }
    }
    return res;
}

vector<pair<int, int>> prime_factor(int n)
{
    vector<pair<int, int>> res;
    while (n != 1)
    {
        int prime = MinFactor[n];
        int exp = 0;
        while (MinFactor[n] == prime)
        {
            ++exp;
            n /= prime;
        }
        res.push_back(make_pair(prime, exp));
    }
    return res;
}

