void solve(int n, map<int, int> &m) {
    while (n != 1) {
        repd(i, 2, n + 1) {
            if (n % i == 0) {
                if (m[i] == 0) {
                    m[i] = 1;
                } else {
                    m[i]++;
                }
                n /= i;
                break;
            }
        }
    }
    return;
}

