static map<long long, long long> calc_prime_factor (long long n) {
    map<long long, long long> prime_factor;
    for ( long long i = 2; i * i <= n; i++ ) {
        while ( n % i == 0 ) {
            prime_factor[i]++;
            n /= i;
        }
    }
    if ( n != 1 )
        prime_factor[n]++;
