template<typename T = ll>
bool isPrime(T n){
  if(n <= 1) return false;
  if(n == 2) return true;
  if(n % 2 == 0) return false;
  for(T i = 3; i*i <= n; i += 2){
    if(n % i == 0) return false;
  }
  return true;
}
/////////////////////////////////////////////////////////////////////
// PrimeFactor（素因数分解）
// auto MP = Prime_Factor(N);
// for(auto i : MP){
//   cout << i.first << " " << i.second << endl;
// }
/////////////////////////////////////////////////////////////////////
template<typename T = ll>
map<T, T> Prime_Factor(T n){
  map<T, T> mp; T cnt = 0;
  while(n%2 == 0){
    n /= 2; cnt++;
  }
  if(cnt != 0) mp[2] = cnt;
  for(T i = 3; i*i <= n; i += 2){
    cnt = 0;
    while(n%i == 0){
      n /= i; cnt++;
    }
    if(cnt != 0) mp[i] = cnt;
  }
  if(n != 1) mp[n] = 1;
  return mp;
}

