  int N; cin >> N;
  map<int, int> mp;
  for(int i = 1; i <= N; i++){
    for(auto j : Prime_Factor(i)){
      mp[j.first] += j.second;
    }
  }
  ll ans = 1;
  ll MOD = 1e9+7;
  for(auto i : mp){
    ans = (ans*(i.second+1))%MOD;
  }
  cout << ans << endl;
}

