  for (int i=2; i*i<=n; i++){ while (n%i==0){ res[i]++; n/=i; } }
  if (n!=1) res[n]+=1;
}

int main() {
  int n; cin >>n;
  map<int, int> factor;
  rep(i, n) prime_factor(i+1, factor);
  ll res = 1;
  for (auto p : factor){
    res = res * (p.second + 1) % MOD;
  }
  cout <<res <<endl;
}

