void prime_fact(int n, map<int,int>& A){
    if (n <= 1) return;
    int n_origin = n;
    for(int i=2; i<=(int)sqrt(n_origin); i++){
        if (n%i == 0){
            int count = 0;
            while(n%i == 0){
                n/=i;
                count ++;
            }
            A[i] += count;
        }
    }
    if (n!=1){
        A[n] += 1;
    }
    return;
}

int main() {
    int n; cin >> n;
    map<int,int> A;
    FOR(i,1,n+1){
        prime_fact(i, A);
    }
