void findprime(int n){
	primenum.push_back(2);
	int s=sqrt(n);
	bool flag;
	for(int i=3; i<=n; i+=2){
		flag=1;
		for(int j=3; j<=s; j+=2){
			if(i%j==0){
				flag=0;
				break;
			}
		}
		if(flag) primenum.push_back(i);
	}
}

void primefac(int n){
	count.resize(primenum.size());
	int m=0;
	for(int i=0; i<primenum.size(); i++){
		for(int j=1; pow(i,j)<n; i++){
			m += n / pow(i, j);
		}
		count.push_back(m);
	}
}

