bool *primeB(bool *p, int n) {

    int n_ = (int) sqrt(n) + 1;

    fill(p, p + n + 1, true);
    if (n >= 0) p[0] = false;
    if (n >= 1) p[1] = false;

    for (int i = 2; i <= n_; ++i) {
        if (p[i]) {
            for (int j = i + i; j <= n; j += i) {
                if (p[j]) p[j] = false;
            }
        }
    }

    return p;
}

