ll Prime_Factorization(ll N, ll *fac, ll mod) {
    ll N_ = N;
    ll ans = 1;
    for (ll i = 2; i*i <= N_; i++) {
        while (N % i == 0) {
            fac[i]++;
            N /= i;
        }
        ans *= fac[i]+1;
        ans %= mod;
    }
    if (N > 1) {
        fac[N]++;
        ans *= 2;
    }
    return ans;
}

