const ll MOD = 1000000007;
bool is_prime[1001];

void factoring(vector<int> &result, int num) {
  if (is_prime[num]) {
    result.push_back(num);
  }
  for (int j = 2; j < num; ++j) {
    if (num % j == 0 and is_prime[j]) {
      result.push_back(j);
      factoring(result, num / j);
      break;
    }
  }
}

int main() {
  int N;
  cin >> N;

  // エラトステネスの篩で素数表を作る
  for (int i = 0; i < N + 1; ++i) {
    is_prime[i] = true;
  }
  for (int i = 2; i < N + 1; ++i) {
    int cout = i;
    if (is_prime[cout] == false) continue;
    while (cout < N + 1) {
      cout += i;
      is_prime[cout] = false;
    }
  }

  map<int, int> prime_fact;
  for (int i = 2; i < N + 1; ++i) {
    if (is_prime[i]) {
      auto itr = prime_fact.find(i);
      if (itr != prime_fact.end()) {
        prime_fact[i] += 1;
      } else {
        prime_fact[i] = 1;
      }
    } else {
      vector<int> result;
      factoring(result, i);
      for (auto j_prime : result) {
        auto itr = prime_fact.find(j_prime);
        if (itr != prime_fact.end()) {
          prime_fact[j_prime] += 1;
        } else {
          prime_fact[j_prime] = 1;
        }
      }
    }
  }

  ll ans = 1;
  for (auto itr = prime_fact.begin(); itr != prime_fact.end(); ++itr) {
    ans = (ans * (itr->second + 1)) % MOD;
