vector<pair<ll, ll>> prime_factori(ll n) {
	vector<pair<ll, ll>> res;

	for(ll i = 2; i * i <= n; ++i) {
		if(n % i != 0) continue;

		ll exp = 0;
		while(n % i == 0) {
			++exp;
			n /= i;
		}
		res.push_back({i, exp});
	}

	if(n != 1) res.push_back({n, 1});

	return res;
}


