		for(auto item : pf) ex[item.first] += item.second;
	}

	ll ans = 1;
	for(int i = 2; i <=n; ++i) {
		ans *= ex[i] + 1;
		ans %= MOD;
	}

	cout << ans << "\n";

	return 0;
}

