lli isPrime(lli n){
	if(n==0 || n==1)return 0;
	else if(n==2) return 1;
	else if(n%2==0)return 0;
	else{
		for(lli i=3;i*i<=n;i+=2){
			if(n%i == 0){
				return 0;
			}
		}
		return 1;
	}
}

lli calc(lli n,lli prime){
	lli cnt=0;
	while(1){
		if(n%prime==0){
			cnt++;
			n/=prime;
		}
		else break;
	}
	return cnt;
}

