	for(lli n = 1; n<= num;n++){
		for(auto &e:prime){
			ans[e]+=calc(n,e);
		}
	}

	lli ansSum=1;

	for(auto e:ans){
		ansSum *= (e.second+1)%LIM;
		ansSum %= LIM;
	}

	cout<<ansSum<<endl;
	return 0;
}

