map<ll, ll> mp; 

int prime_factorize(ll n) {

  for (ll i = 2; i * i <= n; i++) {
    if (n % i != 0) continue;
    ll ex = 0;
    while (n % i == 0) { ++ex; n /= i; }

    auto itr = mp.find(i);
    if (itr == mp.end()) mp[i] = ex;
    else mp[i] += ex;

  }

  if (n != 1) {
    auto itr = mp.find(n);
    if (itr == mp.end()) mp[n] = 1;
    else mp[n]++;
  }

  return 0;
}

