// 素因数分解 (第2引数は参照渡しして戻り値として利用)
void enumpr(int n, unordered_map<int, int> &V) {
    for (int i = 2; i * i <= n; i++) {
        while (n % i == 0) {
            V[i]++;
            n /= i;
        }
    }
    if (n > 1)
        V[n]++;
}

