    // 素因数分解を2〜Nまで行う
    for (int i = 2; i <= N; i++) {
        enumpr(i, V);
    }
    int ans = 1;
    for (auto &x : V) {
        // 因数(x.first)が0個〜x.second個までの(x.second + 1)通り
        ans *= (x.second + 1);
        ans %= MOD;
    }
    cout << ans << endl;

    return 0;
}

