const long long M = 1000000007;

long long factorial(int n){
  long long a = 1;
  for(long long i = 1; i <= n; i++){
    a *= i;
   cout << a << endl;
  }

  return a;
}

vector<long long> prime_list(long long n){
  vector<long long> p;
  vector<bool> furui(n+1, true);
  furui[0] = furui[1] = false;
  for(long long i = 2; i <= (int)sqrt(n); i++){
    if(furui[i]){
      for(long long j = i + i; j <= n; j += i){
        furui[j] = false;
      }
    }
  }
  for(long long i = 2; i <= n; i++){
    if(furui[i]){
      p.push_back(i);
    }
  }
  return p;
}

long long divide_times(long long n, long long d){
  long long ans = 0;
  while(n % d == 0){
    n /= d;
    ans++;
  }
  return ans;
}

int main(){
  int n;
  cin >> n;
  // long long fact = factorial(n);
  auto plist = prime_list(n);

  unordered_map<long long, long long> mp;
  for(long long i = 0; i < plist.size(); i++){
    mp[plist[i]] = 0;
  }

  for(long long i = 1; i <= n; i++){
    for(long long j = 0; j < plist.size(); j++){
      long long d = plist[j];
      long long t = divide_times(i, d);
      mp[d] += t;
    }
  }

  long long ans = 1;
  for(auto itr = mp.begin(); itr != mp.end(); itr++){
    ans *= itr->second + 1;
    ans %= M;
  }
  cout << ans << endl;
}

