#include <bits/stdc++.h>
using namespace std;

using ll = long long int;

const ll MOD = (ll)(1e9 + 7);

ll x;

map<ll, ll> cnt;

ll ans;

/////////////////////////////////////////////////////////////
map<ll, ll> prime_factorization(ll n) {
  map<ll, ll> res;
  for (ll i = 2; i * i <= n; ++i) {
    while (n % i == 0) {
      res[i] += 1;
      n /= i;
    }
  }
  if (n != 1) res[n] = 1;
  return res;
}
/////////////////////////////////////////////////////////////

int main(void) {
    // Here your code !
    scanf("%lld", &x);

    for (int i = 2; i <= x; ++i) {
      for (auto &e: prime_factorization(i)) {
        if (cnt.find(e.first) != cnt.end()) {
          cnt[e.first] += e.second;
        }
        else {
          cnt[e.first] = e.second;
        }
      }
    }

    ans = 1;
    for (auto &e: cnt) {
      ans = ans * ((e.second + 1) % MOD);
      ans %= MOD;
    }

    printf("%lld\n", ans);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const long long int MOD = 1e9 + 7;

int main(){
    int n;
    cin >> n;

    vector<long long int> prime_power(1001, 1LL);
    for(int i=2; i<=n; i++){
        int k = i;
        for(int p=2; p*p<=k; p++){
            if(k % p != 0) continue;// break and proceed to p+1

            int power = 0;
            while(k % p == 0){
                power += 1;
                k /= p;
            }
            prime_power[p] += power;
        }

        // n has been divided by all primes (with power) smaller than sqrt(n)
        if(k != 1){
            prime_power[k] += 1;
        }
    }
    long long int ans = 1;
    for(int p=2; p<=n; p++){
        ans = ans * prime_power[p] % MOD;
    }
    cout << ans << endl;
    return 0;
}

