void sieve(ll up) {
	bs.set();
	bs[0] = bs[1] = 0;
	ll ss = up+1;
	for(ll i=2;i<=ss;++i) {
		if(bs[i]) {
			for(ll j=i*i;j<=ss;j+=i) bs[j] = false;
			primos.push_back(int(i));
		}
	}
}
void descomponer(int n) {
	int in = 0, prim = primos[in], ans = 0;
	while(prim*prim<=n) {
		while(n%prim==0)
		{
			++ans;
			tablita[prim]++;
			n /= prim;
		}
		prim = primos[++in];
	}
	tablita[n]++;
}
void tablitaear(int n) {
	tablita.resize(n+1);
	for(int i=2;i<=n;++i) descomponer(i);
}
