    ll res = 1;
    for (int i=1; i<=n; i++){
        if(is_prime[i]){

            int sum_expo = 0;
            long long pot = 1;
            while((n/pot)>0){
                pot = pot * i*1ll;
                sum_expo += n/pot;
            }

            if(sum_expo == 0) break;
            res = (res * (sum_expo + 1))%MAX;
        }
    }
    return res;
}

