vector<pair<int,int>> prime_factorize(int N){
    vector<pair<int,int>> ans;

    for(int a=2; a*a<=N; a++){
        if(N % a != 0) continue;
        int ex = 0;
        while(N % a == 0){
            ex++;
            N /= a;
        }
        ans.push_back({a,ex});
    }
    if(N != 1) ans.push_back({N,1});

    return ans;
}

