static const int NMAX = 1000;
static const long long MOD = 1000000007;

ll N;
int fact[NMAX+1];

void factoring(int num){
  int x = 2;

  while(num >= x*x){
    if(num%x == 0){
      fact[x]++;
      num /= x;
    }else{
      x++;
    }
  }
  fact[num]++;
}

int main(){
  cin >> N;
  for(int i=0;i<=NMAX;i++) fact[NMAX] = 0;

  ll ans = 1;

  if(N==1){
    cout << ans << endl;
    return 0;
  }

  for(int i=2;i<=N;i++) factoring(i);

  for(int i=2;i<=N;i++){
    if(fact[i]==0) continue;
    ans = (ans * (fact[i]+1)) % MOD;
  }
  cout << ans << endl;
  return 0;
}

