class Prime
{
public:
    static 
    bool is_prime(long long n) {
        if (n == 1) return false;
        for (ll a = 2; a * a <= n; ++a) if (n % a == 0) return false;
        return true;
    }
    static 
    std::vector<long long> listup(long long n) {
        std::vector<long long> ret;
        for (long long i = 1; i * i < n; ++i) {
            if (n % i == 0) ret.push_back(i);
            long long other = n / i;
            if (other != i) ret.push_back(other);
        }
        std::sort(ret.begin(), ret.end());
        return ret;
    }
    static 
    std::vector<std::pair<long long, long long>> factorize(long long n) {
       std::vector<pair<long long, long long>> res;
        for (long long a = 2; a * a <= n; ++a) {
            if (n % a != 0) continue;
            long long ex = 0;
            while (n % a == 0) {
                ++ex;
                n /= a;
            }
            res.push_back({a, ex});
        }
        if (n != 1) res.push_back({n, 1});
        return res;
    }
};

void solve() {
    ll n; cin >> n;
    vector<ll> ex(n+1, 0);
    for (ll i = 2; i <= n; ++i) {
        const auto& res = Prime::factorize(i);
        for (auto& p: res) ex[p.first] += p.second;
    }

    ll ret = 1;
    for (ll p = 2; p <= n; ++p) {
        ret *= ex[p] + 1;
        ret %= MOD;
    }
    cout << ret << endl;
}

signed main() {
    solve();
    return 0;
}

