  return ret;
}

map<int, int> map_merge(map<int,int>m1, map<int, int>m2){
  for(auto p : m1){
    if(m2.count(p.first) == 0){
      m2[p.first] = p.second;
    } else {
      m2[p.first] += p.second;
    }
  }
  return m2;
}


