// constexprな素数列挙(エラトステネスの篩)
// https://259-momone.hatenablog.com/entry/2018/05/06/015026
template <int64_t max_N> struct Prime {
    bool sieve[max_N];
    // bitset<max_N> sieve;
    // int_fast64_t prime[prime_size];
    constexpr Prime() : sieve() {
        // sieve.flip();
        for (int64_t i = 0; i < max_N; ++i)
            sieve[i] = true;
        for (int64_t n = 3; n * n < max_N; n += 2)
            if (sieve[n / 2])
                for (int64_t index = n * n; index < max_N; index += n * 2)
                    sieve[index / 2] = false;
    }
};

int main() {
    ios::sync_with_stdio(false);
