vector<pair<ll, int>> factorize(ll num){
    vector<pair<ll, int>> res;
    for(ll i=2; i*i<=num; i++){
         if(num%i) continue;

        res.emplace_back(i, 0);
        while(num%i==0){
            res.back().second++;
            num /= i;
        }
    }
    if(num != 1){
        res.emplace_back(num, 1);
    }
    return res;
}

