//nを素因数分解
vector<int> prime_factorization(int n){
    vector<int> factorization_list;
    if(n <= 1){
        return factorization_list;
    }

    vector<int> prime_list = make_prime_list(n);
    for(int i = 0; i < prime_list.size(); i++){
        int prime = prime_list.at(i);
        if(n % prime == 0 && n > 0){
            while(n % prime == 0 && n > 0){
                n /= prime;
                factorization_list.push_back(prime);
            }
        }
    }
    return factorization_list;
}

//nの約数の個数を返す
int search_divisor_num(int n){
    if(n < 0){
        return 0;
    }
    if(n == 1){
        return 1;
    }

    vector<int> factorization = prime_factorization(n);
    vector<int> backet(n + 1, 0);
    for(int i = 0; i < factorization.size(); i++){
        int prime = factorization.at(i);
        backet.at(prime)++;
    }
    int divisor_num = 1;
    for(int i = 0; i < backet.size(); i++){
        divisor_num *= (backet.at(i) + 1);
    }
    return divisor_num;
}

