// Sieve of Eratosthenes
// エラトステネスの篩
vector<int> sieve(int N) {
  vector<bool> e(N, true);
  e[0] = false;
  e[1] = false;
  int sqrtN = ceil(sqrt(N)) + 1;
  rep(p, sqrtN) {
    if (!e[p]) continue;
    for (int i = pow(p, p); i < N; i += p) {
      e[i] = false;
    }
  }
  vector<int> ret;
  rep(i, N) {
    if (e[i]) ret.push_back(i);
  }
  return ret;
}

int loga(int x, int a) {
  if (x == 0 || x == 1) return 0;
  int cnt = 0;
  while (x % a == 0) {
    x /= a;
    cnt++;
  }
  return cnt;
}

