template <typename T>
std::vector<T> prime(const T max) {
  std::vector<bool> sieve(max - 1, true);
  const auto lim = std::floor(std::sqrt(max));

  if (max < 2) {
    return {};
  }

  T var = 2;
  while (var <= lim) {
    for (T i = 2; i * var <= max; i++) {
      sieve[i * var - 2] = false;
    }
    do {
      var++;
    } while (!sieve[var - 2] && var <= lim);
  }

  std::vector<T> ans;
  ans.reserve(std::count(sieve.cbegin(), sieve.cend(), true));
  for (T i = 0; i < max - 1; i++) {
    if (sieve[i]) {
      ans.push_back(i + 2);
    }
  }

  return ans;
}


