map<ll,ll> PrimeFactorization(ll a){
	map<ll, ll> result;
	if (a == 1) return move(result);
	for (ll i=2; i*i<=a; i++){
		if (a % i != 0) continue;
		a /= i;
		result[i--]++;
	}
	result[a]++;
	return move(result);
}


void solve()
{
	ll N; cin >> N;

	map<ll, ll> fAll;
	REPS(i, 2, N){
		auto res = PrimeFactorization(i);
		EACH(e, res) fAll[e.first] += e.second;
	}

	mll ans = 1;
	EACH(e, fAll){
		ans *= (e.second+1);
	}
	cout << ans << '\n';
}


int main(){
	solve();
	return 0;
}

