#define MAXQ 100100
bool isPrime[(MAXQ + 1)];
int pList[(MAXQ + 1)];
int sizeP;  // global
void calcP() {
  sizeP = 0;
  fill(isPrime, isPrime + MAXQ + 1, true);
  isPrime[0] = isPrime[1] = false;
  for (int i = 2; i <= MAXQ; ++i) {
    if (isPrime[i]) {
      pList[sizeP++] = i;
      for (int j = i * 1LL * i; j <= MAXQ; j += i) {
        isPrime[j] = false;
      }
    }
  }
}

