  vector<pair<int, int> > res;
  while (num > 1) {
    int prime = least_prime_factor[num], exponent = 0;
    while (least_prime_factor[num] == prime) {
      ++exponent;
      num /= prime;
    }
    res.emplace_back(prime, exponent);
  }
  return res;
}

