    ll res = 1, last = 0;
    rep(i, V.size() - 1) {
        if (V[i] != V[i + 1]) {
            res *= i + 2 - last;
            res %= MOD;
            last = i + 1;
        }
    }
    res *= V.size() + 1 - last;
    res %= MOD;
    cout << res << rt;
}

