	for (int i = 0; i < MAX; i++) {
		prime[i] = i;
	}	
	prime[0] = prime[1] = 1;
	for (int i = 4; i < MAX; i += 2) {
		prime[i] = 2;
	}
	for (int i = 3; i * i < MAX; i += 2) {
		if (prime[i] == i) {
