template <class T> vector<T> factoring_vector(T N) {
    vector<T> ans(N + 1);
    T mx   = N;
    ans[1] = -1;
    while (mx != 0) {
        N           = mx;
        long long i = 2;
        while (i * i <= N) {
            if (N % i == 0) {
                ans[i]++;
                N /= i;
            } else {
                i++;
            }
        }
        ans[N]++;
        mx--;
    }
    return ans;
}

