void factor(map<int,int> &m, int num){
    for(int i=2; i*i <= num; i++){
        int p = 0;
        while(num%i==0){
            num /= i;
            p++;
        }
        if(p > 0){
            if(!m.count(i)) m[i] = 0;
            m.at(i) += p;
        }
    }
    if(num != 1){
        if(!m.count(num)) m[num] = 0;
        m.at(num)++;
    }
}

