map<int, int> prime_factor(int n){
    map<int,int> prime_factor;
    for(int j=1;j<=n;j++){
        int x=j;
        for(int i=2;i*i<=x;i++){
            if(x==1) break;

            while(x%i==0){
                x /= i;
                prime_factor[i] ++;
            }
        }
        if(x>1) prime_factor[x] ++;
    }
    return prime_factor;
}

