    for (int i=2; i*i<=n; i++)
    {
      int ct = 0;

        if (prime[i])
        {    
            if (i * 1ll * i <= n)               // To avoid Overflow
            {
                for (int j=i*i; j<=n; j+=i)     // We begin to move from i ^ 2, since all smaller                                              
                    prime[j] = false;           // numbers that are multiples of i necessarily have a simple divisor less i,
            }                                   // which means that all of them have already been eliminated earlier
        }
    }
    return prime;
}

