    for(ll i=0; prime[i]<=n &&  i<prime.size(); i++)
    {
        ll cnt=0, temp=prime[i];
        while(temp<=n)
        {
            cnt+=(n/temp);
            temp*=prime[i];
        }
        ans*=(cnt+1);
        if(ans>MOD)
        {
            ans%=MOD;
        }
    }
    return ans;
}

