map<ll,int> prime_factor(ll n){
  map<ll, int> ret;
  for(ll i = 2; i*i <= n; i++){
    while(n % i == 0){
      ret[i]++;
      n/=i;
    }
  }
  if(n!=1)ret[n]=1;
  return ret;
}

int main(){
  int N;
  cin >> N;
  ll ans=1;
  map<ll,int> m;
  FOR(i,2,N+1){
    map<ll,int> mm = prime_factor(i);
    for(auto itr = mm.begin(); itr != mm.end(); ++itr){
      m[itr->first] += itr->second;
    }
  }

  for(auto itr = m.begin(); itr != m.end(); ++itr){
    ans *= (itr->second + 1);
    ans %= MOD;
  }
  cout << ans << endl;
}

