vector<int> sosu;
void init (int n) {
  for (int i = 2; i <= n; i++) {
    for (int j = 2; j <= i; j++) {
      if (i % j == 0 && i != j) {
        break;  
      }    
      if (j == i) {
        sosu.push_back(i);    
      }
    }    
  }  
}

int main () {
  int N;
  cin >> N;
  vector<int> ans(N + 1, 0);
  init(N);
  for (int i = 2; i <= N; i++) {
    // iについて素因数分解をする
    for (int j = 0; j < sosu.size(); j++) {
      if (i < sosu[j]) {
        break;  
      }    
      int sub = sosu[j];
      int it = 1;
      while (i >= sub) {
        if (i % sub == 0) {
          ans[sosu[j]] ++;    
        }    
        it++;
        sub = sub * sosu[j];
      }
    }
  }
  long long as = 1;
  for (int i = 0; i <= N; i++) {
    if (ans[i] != 0) {
      as = as * (ans[i] + 1) % 1000000007;    
    }
  }
  cout << as << endl;
}

