using namespace std;
using lint = long long;
using ld = long double;

// エラトステネスの篩[2,n]を列挙 O(nloglogn)
vector<lint> sieve_of_eratosthenes(lint n) {
    vector<bool> is_prime(n+1, true);
    is_prime[0] = is_prime[1] = false;
    for (lint i = 2; i*i <= n; ++i)
        if (is_prime[i])
            for (lint k = i+i; k <= n; k += i)
                is_prime[k] = false;
    vector<lint> primes;
    for (lint i = 2; i <= n; ++i)
        if (is_prime[i])
            primes.push_back(i);
    return primes;
}

// 素因数分解
map<lint,lint> factors(lint n, vector<lint> const & primes) { 
    map<lint,lint> result;
    for (lint p : primes) {
        if (n < p * p) break;
        while (n % p == 0) {
            result[p] += 1;
            n /= p;
        }
    }
    if (n != 1) result[n] += 1;
    return result;
}

int main(void) {
    lint n; cin >> n;
    if (n == 1) {
        cout << 1 << endl;
        return 0;
    }

    const int MOD = 1e9 + 7;
    vector<lint> primes = sieve_of_eratosthenes(n);
    map<lint, lint> mp;
    repeat_from_to(i, 2, n) {
        map<lint, lint> res = factors(i, primes);
        for(auto &e : res) {
            mp[e.first] += e.second;
        }
    }

    lint ans = 1;
    for(auto &e: mp) {
        ans *= (e.second + 1);
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;

}

