map<int, int> mp;

void primeFactorization(int n)
{
    // 平方根を保存
    auto s = floor(sqrt(n));
    int r = 0;

    for (int i = 2; i <= s; i++)
    {
        // 割り切れる
        if ((n % i) == 0)
        {
            r = 0;

            do
            {
                r++;
                n = n / i;
            } while ((n % i) == 0);

            mp[i] += r;
        }
    }

    // 残った素数を追加
    if (n > s)
    {
        mp[n]++;
    }
}

