using namespace std;

const long long MOD = 1000000007;

void solve(long long N){
    map<LL, LL> cnts;
    for(LL i=2; i<=N; i++){
        LL tmp=i, j=2;
        while(j<=sqrt(i)){
            while(tmp%j==0){
                tmp/=j;
                cnts[j]++;
            }
            j++;
        }
        if(tmp>1)cnts[tmp]++;
    }
    LL ans=1;
    for(auto kv:cnts){
        ans = (ans*(kv.second+1))%MOD;
    }
    cout << ans << endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    solve(N);
    return 0;
}

