    for(int i = 2; i <= N; ++i) {
        vector<P> vec = prime_factorize(i);
        for (auto itr : vec) {
            mp[itr.first] += itr.second;
        }
    }
    for(auto itr : mp){
        ans *= (itr.second + 1);
        ans %= MOD;
    }

    cout << ans << endl;
    return 0;
}

