#include <bits/stdc++.h>
using ll = long long;
using namespace std;

template <long long mod> class modint
{
private:
    long long x;
public:
    modint(long long x = 0) : x(x % mod) {}
    modint& operator+=(const modint rhs) {
        if ((x += rhs.x) >= mod) x -= mod;
        return *this;
    }
    modint& operator-=(const modint rhs) {
        if ((x += mod - rhs.x) >= mod) x -= mod;
        return *this;
    }
    modint& operator*=(const modint rhs) {
        (x *= rhs.x) %= mod;
        return *this;
    }
    modint& operator/=(const modint rhs) {
        *this *= rhs.inv();
        return *this;
    }
    modint operator+(const modint rhs) const {return modint(*this) += rhs;}
    modint operator-(const modint rhs) const {return modint(*this) -= rhs;}
    modint operator*(const modint rhs) const {return modint(*this) *= rhs;}
    modint operator/(const modint rhs) const {return modint(*this) /= rhs;}

    modint pow(long long n) const { // n乗を求める
        modint e = *this, ret = modint(1);
        while (n) {
            if (n & 1) ret *= e;
            e *= e, n >>= 1;
        }
        return ret;
    }

    modint inv() const { // 逆元を求める
        return pow(mod - 2);
    }

    friend ostream& operator<<(ostream& os, const modint<mod>& m) {
        os << m.x;
        return os;
    }

    friend istream& operator>>(istream& is, modint<mod>& m) {
        long long in;
        is >> in;
        m = modint<mod>(in);
        return is;
    }
};
using mint = modint<1000000007>;

map<ll, int> factorize(ll n)
{
    map<ll, int> mp;
    for (ll i = 2; i * i <= n; i++) {
        while (n % i == 0) {
            mp[i]++; n /= i;
        }
    }
    if (n != 1) mp[n] = 1;
    return mp;
}

int main()
{
    int n; cin >> n;
    map<int, int> mp;
    for (int i = 2; i <= n; i++) {
        int num = i;
        for (int j = 2; j * j <= num; j++) {
            while (num % j == 0) {
                mp[j]++; num /= j;
            }
        }
        if (num != 1) mp[num]++;
    }
    mint ans(1);
    for (auto& e: mp) {
        ans *= mint(e.second + 1);
    }
    cout << ans << endl;
    return 0;
}

