vector<int> prime;

void calcPrime(int n){

    bool isPrime[n+1];
    fill(isPrime, isPrime+n+1, true);
    isPrime[0] = false;
    isPrime[1] = false;

    int i1 = 2; 
    while(i1 <= n){
        if(isPrime[i1] == false){
            i1++;
            continue;
        }

        int temp = i1;
        int i2 = i1*2;
        while(i2 <= n){
            isPrime[i2] = false;
            i2 += temp;
        }
        i1++;
    }

    for(int i=2; i<=n; i++){
        if(isPrime[i]){
            prime.push_back(i);
        }
    }
}

int main(){

    int n; cin >> n;
    calcPrime(n);

    map<ll, ll> mp;
    for(int i=2; i<=n; i++){
        int j=0;
        int temp = i;
        while(prime[j] <= i){
            if(temp % prime[j] == 0 && temp != 0){
                mp[prime[j]]++;
                temp /= prime[j];
            }
            else{
                j++;
            }
        }
    }

    ll ans = 1;
    map<ll, ll>::iterator itr;
    for(itr=mp.begin(); itr!=mp.end(); itr++){
        pair<ll, ll> p = *itr;

        ans = (ans * (p.second + 1)) % MOD;
    }

    cout << ans;

    return 0;
}

