template<class INT>
std::map<INT, int> factorize(INT n){
    std::map<INT, int> res;
    for (int i = 2; i * i <= n; i++){
        while (n % i == 0){
            res[i]++;
            n /= i;
        }
    }

    if (n > 1)
        res[n]++;

    return res;
}

int main(){
    int n;
