    const int64_t p = 1e9 + 7;

    map<int, int> M;
    for (int i = 1; i <= n; i++){
        auto res = factorize<int>(i);
        for (const auto &r: res)
            M[r.first] += r.second;
    }
    int64_t ans = 1;
    for (const auto &m: M)
        ans = ans * (m.second + 1) % p;

    cout << ans << endl;
}

