void sieve(size_t max, vector<bool> &isPrime){
    isPrime[0] = false; 
    isPrime[1] = false; 
    for (size_t i = 2; i*i <= max; ++i) 
        if(isPrime[i])
            for(size_t j=2; i*j <= max; ++j) 
                isPrime[i*j] = false; 
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll n;
	cin >> n;
	vector<bool> isPrime(n+1, true);
	sieve(n, isPrime);
	vector<ll> cnt(n+1, 0);
	FOR(i, 2, n+1){
		if (isPrime[i]){
			FOR(j, i, n+1){
				ll c = 0;
				ll tmp = j;
				while(tmp%i==0){
					c++;
					tmp /= i;
				}
				cnt[i] += c;
			}
		}
	}
	ll ans = 1;
	FOR(i, 2, n+1){
		ans *= (cnt[i]+1);
	}
	cout << ans%mod << endl;
}

