void factoring(vector<pair<ll,ll>>&factor,ll n){
  for(ll p=2;p*p<=n;++p){
    if(n%p!=0)continue;
    ll num=0;
    while(n%p==0){
      num++;
      n/=p;
    }
    factor.emplace_back(p,num);
  }
  if(n!=1)factor.emplace_back(n,1);
}

