void getPrime(int N) {
	for (ll n = 2; n <= N; n++) {
		bool prime = true;
		for (int i = 2; i*i <= n; i++) {
			if (n%i == 0) {
				prime = false;
				break;
			}
		}
		if (prime) vec.push_back(n);
	}
}

int main() {
	int N; cin >> N;
	getPrime(N);

	if (N == 1) {
		cout << 1 << endl;
		return 0;
	}

	vector<ll> cnt(N);
	fill(cnt.begin(), cnt.end(), 0);
	for (int n = 1; n <= N; n++) {
		ll buf = n;
		for (int i = 0; i < vec.size(); i++) {
			while (buf%vec[i] == 0) {
				cnt[i]++;
				buf /= vec[i];
			}
		}
	}

	ll ans = 1;
	for (int i = 0; i < vec.size(); i++) {
		ans = (ans*(cnt[i] + 1)) % mod;
	}
	cout << ans << endl;
}

