map<int,int> result;
void prime_factorize(int n){

    for (int factor = 2; factor*factor <= n; factor++) {
        if(n%factor != 0) continue;

        int power = 0;
        while(n%factor == 0){
            power++;
            n /= factor;
        }

        result[factor] += power;
    }

    if (n != 1) result[n] += 1;
}

