map<ll, ll> prime_factor(ll n){
    map<ll, ll> mp;
    for(int i = 2; i * i <= n; i++){
        while(n % i == 0){
            mp[i]++;
            n /= i;
        }
    }
    if(n != 1)mp[n]++;
    return mp;
}

