#include <stdio.h>

void PrimeTable(int);
void PrimeFuctrization2(int);

int PrimeNumber[1000]={};
int Exponent[1000]={};

int main(){
	int N;
	int i;
	long long ans=1;

	scanf("%d",&N);
	PrimeTable(N);
	for(i=2;i<=N;i++){
			PrimeFuctrization2(i);
	}
	for(i=0;i<=N;i++){
			ans=((ans*(Exponent[i]+1))%1000000007);
	}
	printf("%lld\n",ans);
	return 0;
}

/*Nまでの素数(Nを含む)をPrimeNumber[]に格納する関数
int PrimeNumber[]={};
を宣言してから使う*/
void PrimeTable(int N){
	int i,j,k=0,flag;
	for(i=2;i<=N;i++){
		flag=0;
		for(j=2;j*j<=i;j++){
			if(!(i%j)){
				flag=1;
				break;
			}
		}
		if(!flag){
			PrimeNumber[k]=i;
			k++;
		}
	}
}

/*整数Nを素因数分解し、PrimeNumber[i]に対応する冪指数をExponent[i]に格納する関数
PrimeTable関数で素数表を生成した上で
int Exponent[]={};
を宣言してから使う*/
void PrimeFuctrization2(int N){
	int i,j;
	for(i=0;N>=PrimeNumber[i];){
		if(!(N%PrimeNumber[i])){
			N/=PrimeNumber[i];
			Exponent[i]++;
		}else{
			i++;
		}
	}
}

