#include <stdio.h>
#define MOD 1000000007
#define MAX 1001

int main() {
  int primes[MAX];
  int primeNum = 0;
  int factor[MAX][MAX];
  for (int i = 0; i < MAX; i++) {
    for (int j = 0; j < MAX; j++) {
      factor[i][j] = 0;
    }
  }
  int N;
  scanf("%d", &N);

  for (int i = 2; i <= N; i++) {
    int isPrime = 1;
    int minPrimeIndex = primeNum;
    for (int j = 0; j < primeNum; j++) {
      if (i % primes[j] == 0) {
        isPrime = 0;
        minPrimeIndex = j;
        break;
      }
    }
    if (isPrime) {
      primes[primeNum] = i;
      factor[i][primeNum] = 1;
      primeNum++;
    } else {
      for (int j = 0; j < primeNum; j++) {
        factor[i][j] = factor[i / primes[minPrimeIndex]][j];
      }
      factor[i][minPrimeIndex]++;
    }
  }

  long result = 1;
  for (int i = 0; i < primeNum; i++) {
    int numOfI = 0;
    for (int j = 2; j <= N; j++) {
      numOfI += factor[j][i];
    }
    printf("[%d]:%d\n", primes[i], numOfI);
    result *= (numOfI + 1);
    result %= MOD;
  }

  printf("%ld\n", result);
  return 0;
}

