/*Nまでの素数(Nを含む)をPrimeNumber[]に格納する関数
int PrimeNumber[]={};
を宣言してから使う*/
void PrimeTable(int N){
	int i,j,k=0,flag;
	for(i=2;i<=N;i++){
		flag=0;
		for(j=2;j*j<=i;j++){
			if(!(i%j)){
				flag=1;
				break;
			}
		}
		if(!flag){
			PrimeNumber[k]=i;
			k++;
		}
	}
}

/*整数Nを素因数分解し、PrimeNumber[i]に対応する冪指数をExponent[i]に格納する関数
PrimeTable関数で素数表を生成した上で
int Exponent[]={};
を宣言してから使う*/
void PrimeFuctrization2(int N){
	int i,j;
	for(i=0;N>=PrimeNumber[i];){
		if(!(N%PrimeNumber[i])){
			N/=PrimeNumber[i];
			Exponent[i]++;
		}else{
			i++;
		}
	}
}

