void PrimeTable(int N){
	int i,j,k=0,flag;
	for(i=2;i<=N;i++){
		flag=0;
		for(j=2;j*j<=i;j++){
			if(!(i%j)){
				flag=1;
				break;
			}
		}
		if(!flag){
			PrimeNumber[k]=i;
			k++;
		}
	}
}

void PrimeFuctrization(int N){
	int i,j,last,power;
	for(i=0;i<=N;i++){
		if(!PrimeNumber[i]){
		last=i-1;
		break;
		}
	}
	for(i=0;i<=last;i++){
		if(!(N%PrimeNumber[i])){
			for(j=1;pow(PrimeNumber[i],j)<=N;j++){
				power=pow(PrimeNumber[i],j);
				if(!(N%power)){
					Exponent[i]++;
				}
			}
		}
	}
}

