        numPrimeFactors[i] = 0;
    }

    for (uint64_t i = 2; i <= N; i++) {
        const uint64_t lim = (uint64_t)sqrt((double)i) + 1;
        uint64_t val = i;
        uint64_t divisor = 2;

        while (1 < val && divisor <= lim) {
            if (val % divisor == 0) {
                numPrimeFactors[divisor]++;
                val /= divisor;
            }
            else {
                divisor++;
            }
        }

        if (1 < val) {
            numPrimeFactors[val]++;
        }
    }

    uint64_t res = 1;

    for (uint64_t i = 1; i < 35; i++) {
        res = res * numPrimeFactors[i] % MOD_VAL;
    }

    printf("%"PRIu64"\n", res);

    return 0;
}

