		for (j = 2; j * j <= num; j++) {
			while (num % j == 0) {
				num /= j;
				count[j]++;
			}
		}
		if (num > 1) count[num]++;
	}
	for (i = 2; i <= N; i++) {
		answer = mul(answer, add(count[i], 1));
	}
