// 内部構造体 - 素数情報
typedef struct Prm {
	int miVal;													// 値
	int miCnt;													// 数
} Prm;

// 内部変数
static int siN;													// 整数N
static Prm sz1Prm[D_PRM_MAX];									// 素数リスト
static int siPCnt;												// 素数リスト数

// 内部変数 - テスト用
#ifdef D_TEST
	static int siRes;
