#endif

// 素数で割れるかチェック
int
fChkDiv(
	int piVal					// <I> 値
)
{
	int i;

	for (i = 0; i < siPCnt; i++) {
		if (piVal % sz1Prm[i].miVal == 0) {
			return i;
		}
	}

	return -1;
}

// 素数リストの作成
int
fMakePrm(
)
{
	int i;

	// 初期値
	siPCnt = 0;

	// 2
	if (siN < 2) {
		return 0;
	}
	sz1Prm[0].miVal = 2;
	sz1Prm[0].miCnt = 1;
	siPCnt = 1;

	// 順にチェック
	for (i = 3; i <= siN; i++) {
		int liVal = i;

		// 素数で割れるかチェック
		while (1) {
			int liNo = fChkDiv(liVal);
			if (liNo < 0) {					// 割れない
				break;
			}

			// 割る
			liVal /= sz1Prm[liNo].miVal;
			sz1Prm[liNo].miCnt++;
		}
		if (liVal != i) {				// 割れた
			continue;
		}

		// 素数追加
		sz1Prm[siPCnt].miVal = liVal;
		sz1Prm[siPCnt].miCnt = 1;
		siPCnt++;
	}

	return 0;
}

