void PrimeTable(int N){
	int i,j,k=0,flag;
	for(i=2;i<=N;i++){
		flag=0;
		for(j=2;j*j<=i;j++){
			if(!(i%j)){
				flag=1;
				break;
			}
		}
		if(!flag){
			PrimeNumber[k]=i;
			k++;
		}
	}
}

void PrimeFuctrization2(int N){
	int i,j;
	for(i=0;N>=PrimeNumber[i];){
		if(!(N%PrimeNumber[i])){
			N/=PrimeNumber[i];
			Exponent[i]++;
		}else{
			i++;
		}
	}
}

