//Size以下の素数リストをエラストテネスのふるいで作る
void Sieve(int Size, int *output_size, int out[]){
  *output_size = 0;
  int List[1001]={};
  int i, j;
  for(i=2; i<=Size; i++)
    List[i] = i;
  i=2;
  while(i*i <= Size){
    //List[i]が残っていれば素数
    if(List[i]){
      for(j=i+1; j<=Size; j++){
        //List[i]より大きい数のうちList[i]で割り切れるなら0にする
        if(!(List[j]%List[i]))
          List[j] = 0;
      }
    }
    i++;
  }
  //この時点で穴の空いた素数リストが完成する
  for(i=2; i<=Size; i++){
    if(List[i]){
	  out[*output_size] = List[i];
      (*output_size)++;
    }
  }
}

