        while (1 < val && divisor <= lim) {
            if (val % divisor == 0) {
                numPrimeFactors[divisor]++;
                val /= divisor;
            }
            else {
                divisor++;
            }
        }

        if (1 < val) {
            numPrimeFactors[val]++;
        }
    }

