int PrimeNumber[1000]={};
int Exponent[1000]={};

int main(){
	int N;
	int i;
	long long ans=1;

	scanf("%d",&N);
	PrimeTable(N);
	for(i=2;i<=N;i++){
			PrimeFuctrization(i);
	}
	for(i=0;i<=N;i++){
			ans=((ans*(Exponent[i]+1))%1000000007);
	}
	printf("%lld\n",ans);
	return 0;
}

void PrimeTable(int N){
	int i,j,k=0,flag;
	for(i=2;i<=N;i++){
		flag=0;
		for(j=2;j*j<=i;j++){
			if(!(i%j)){
				flag=1;
				break;
			}
		}
		if(!flag){
			PrimeNumber[k]=i;
			k++;
		}
	}
}

void PrimeFuctrization(int N){
	int i,j,last,power;
	for(i=0;i<=N;i++){
		if(!PrimeNumber[i]){
		last=i-1;
		break;
		}
	}
	for(i=0;i<=last;i++){
		if(!(N%PrimeNumber[i])){
			for(j=1;pow(PrimeNumber[i],j)<=N;j++){
				power=pow(PrimeNumber[i],j);
				if(!(N%power)){
					Exponent[i]++;
				}
			}
		}
	}
}

