#define N 1000
#define MD 1000000007

int solve(int n, int p) {
	return n < p ? 0 : n / p + solve(n / p, p);
}

int main() {
	static char composite[N + 1];
	int n, a, b;
	long long p;

	scanf("%d", &n);
	p = 1;
	for (a = 2; a <= n; a++) {
		if (composite[a])
			continue;
		p = p * (solve(n, a) + 1) % MD;
		for (b = a * a; b <= n; b += a)
			composite[b] = 1;
	}
	printf("%lld\n", p);
	return 0;
}

