fun primeDivide(num:Int):Map<Int, Int> {
    var current = num
    val divide = mutableMapOf<Int,Int>()
    var div = 2
    while (current > 1) {
        if(current % div == 0) {
            divide[div] = 0
            while (current%div == 0) {
                divide[div] = divide[div]!! + 1
                current /= div
            }
        }
        div++
    }
    return divide
}

