/* 階乗の素因数分解の仕方。参考: https://youtu.be/28IanD3lXGg */

public class Playground2 {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);

		int n = in.nextInt();

		// find prime factor
		int[] primeFactor = new int[n + 1];
		for (int i = 2; i <= n; i++) {
			int x = i;
			while (1 < x) {
				for (int j = 2; j <= x; j++) {
					if (x % j == 0) {
						primeFactor[j]++;
						break;
					}
				}
			}
		}

		long count = 1;
		for (int i = 2; i <= n; i++) {
			count *= (primeFactor[i] + 1);
			count %= 1000000007;
		}
		System.out.println(count);
	}

}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] factors = new long[n+1];
        for (int i = 2; i <= n; i++) {
            int trg = i;
            int prime = 2;
            while (trg != 1) {
                if (trg % prime == 0) {
                    factors[prime]++;
                    trg /= prime;
                }
                else {
                    while (++prime<trg)
                        if (factors[prime] != 0)
                            break;
                }
            }
        }
        int mod = (int)1e9+7;
        long res = Arrays.stream(factors).reduce(1l, (a, b) -> (a*(b+1l)) % mod);
        System.out.println(res);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;

public class Main {
	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int n = Integer.parseInt(br.readLine());

		long ex[] = new long[n + 1];

		for (long i = 2; i <= n; i++) {
			Map<Long, Integer> map = primeFactorization(i);

			for (long key : map.keySet()) {
				ex[(int) key] += map.get(key);
			}
		}

		long ans = 1;
		for (long i = 2; i <= n; i++) {
			ans *= (ex[(int) i] + 1);
			ans %= 1000000007;
		}

		System.out.println(ans);
	}

	static Map<Long, Integer> primeFactorization(long n) {
		Map<Long, Integer> map = new HashMap<>();
		for (long p = 2; p * p <= n; p++) {
			if (n % p != 0)
				continue;
			int cnt = 0;
			while (n % p == 0) {
				cnt++;
				n = n / p;
			}
			map.put(p, cnt);
		}
		if (n > 1)
			map.put(n, 1);

		return map;
	}
}

