    }

    public static boolean sosuu(long i){
	long j,dame = 0;
	if(i == 1){
	    return false;
	}else{
	    for(j = 2; j < i; j++){
		if((i % j) == 0){
		    dame++;
		}
	    }
	    if(dame > 0){
		return false;
	    }else{
		return true;
	    }
	}
    }

    public static long kazu(long i, int N){
	long j,k,count = 0;
	for(j = 2; j <= N; j++){
	    k = j;
	    while(k % i == 0){
		count++;
		k /= i;
	    }
	}
	return count;
    }
}

