public class Main {
    static final class PrimeFactor {
        public final long primeNumber;
        public final int exponent;

        PrimeFactor(long primeNumber, int exponent) {
            if (primeNumber <= 1) {
                throw new IllegalArgumentException();
            }
            if (exponent < 0) {
                throw new IllegalArgumentException();
            }
            this.primeNumber = primeNumber;
            this.exponent = exponent;
        }
        @Override
        public int hashCode() {
            return Objects.hash(exponent, primeNumber);
        }
        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (!(obj instanceof PrimeFactor)) {
                return false;
            }
            PrimeFactor other = (PrimeFactor)obj;
            return exponent == other.exponent
                   && primeNumber == other.primeNumber;
        }
        @Override
        public String toString() {
            return "PrimeFactor [primeNumber="
                   + primeNumber
                   + ", exponent="
                   + exponent
                   + "]";
        }
        // 素因数分解
        // O(√N)
        public static List<PrimeFactor> factorize(long n) {
            if (n <= 1) {
                throw new IllegalArgumentException();
            }
            List<PrimeFactor> result = new ArrayList<>();
            for (long i = 2; i * i <= n; i += (i == 2 ? 1 : 2)) {
                if (n % i != 0) {
                    continue;
                }
                int exp = 1;
                n /= i;
                for (; n % i == 0; n /= i) {
                    exp++;
                }
                result.add(new PrimeFactor(i, exp));
            }
            if (n != 1) {
                result.add(new PrimeFactor(n, 1));
            }
            return result;
        }
    }
    static void solve(MyScanner in, MyWriter out) {
        int n = in.nextInt();
        long[] exp = new long[n + 1];
        for (int i = 2; i <= n; i++) {
            for (PrimeFactor f : PrimeFactor.factorize(i)) {
                exp[(int)f.primeNumber] += f.exponent;
            }
        }
        long ans = 1;
        for (long e : exp) {
            ans *= e + 1;
            ans %= 1_000_000_007;
        }
        out.println(ans);
    }

    public static void main(String[] args) {
        MyWriter w = new MyWriter(System.out);
        solve(new MyScanner(System.in), w);
        w.flush();
    }

    static final class MyScanner {
        static final int BUFFER_SIZE = 8192;
        private final InputStream in;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int point;
        private int readLength;
        MyScanner(InputStream in) {
            this.in = in;
        }
        private byte readByte() {
            if (point < readLength) {
                byte result = buffer[point];
                point += 1;
                return result;
            }
            try {
                readLength = in.read(buffer);
            } catch (IOException e) {
                throw new AssertionError(null, e);
            }
            if (readLength == -1) {
                return -1;
            }
            point = 1;
            return buffer[0];
        }
        private static boolean isPrintableCharExceptSpace(byte c) {
            return 33 <= c && c <= 126;
        }
        public char nextChar() {
            byte c = readByte();
            while (!(c == -1 || isPrintableCharExceptSpace(c))) {
                c = readByte();
            }
            if (c == -1) {
                throw new NoSuchElementException();
            }
            return (char)c;
        }
        public String next() {
            return next(16);
        }
        public String next(int n) {
            byte c = readByte();
            while (!(c == -1 || isPrintableCharExceptSpace(c))) {
                c = readByte();
            }
            if (c == -1) {
                throw new NoSuchElementException();
            }
            StringBuilder b = new StringBuilder(n);
            do {
                b.append((char)c);
                c = readByte();
            } while (c != -1 && isPrintableCharExceptSpace(c));
            return b.toString();
        }
        public long nextLong() {
            byte c = readByte();
            while (!(c == -1 || isPrintableCharExceptSpace(c))) {
                c = readByte();
            }
            if (c == -1) {
                throw new NoSuchElementException();
            }
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = readByte();
            }
            long result = 0L;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10L + (c - '0');
                c = readByte();
            } while (c != -1 && isPrintableCharExceptSpace(c));
            return minus ? -result : result;
        }
        public int nextInt() {
            long n = nextLong();
            if (n < Integer.MIN_VALUE || n > Integer.MAX_VALUE) {
                throw new InputMismatchException();
            }
            return (int)n;
        }
        public double nextDouble() {
            return Double.parseDouble(next());
        }
        public int[] nextIntArray(int n) {
            int[] result = new int[n];
            for (int i = 0; i < n; i++) {
                result[i] = nextInt();
            }
            return result;
        }
        public long[] nextLongArray(int n) {
            long[] result = new long[n];
            for (int i = 0; i < n; i++) {
                result[i] = nextLong();
            }
            return result;
        }
        public char[] nextCharArray(int n) {
            char[] result = new char[n];
            for (int i = 0; i < n; i++) {
                result[i] = nextChar();
            }
            return result;
        }
        public char[][] next2dCharArray(int n, int m) {
            char[][] result = new char[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    result[i][j] = nextChar();
                }
            }
            return result;
        }
        public int[][] nextVerticalIntArrays(int arrayCount, int arrayLength) {
            int[][] result = new int[arrayCount][arrayLength];
            for (int i = 0; i < arrayLength; i++) {
                for (int j = 0; j < arrayCount; j++) {
                    result[j][i] = nextInt();
                }
            }
            return result;
        }
        public long[][] nextVerticalLongArrays(int arrayCount,
                                               int arrayLength) {
            long[][] result = new long[arrayCount][arrayLength];
            for (int i = 0; i < arrayLength; i++) {
                for (int j = 0; j < arrayCount; j++) {
                    result[j][i] = nextLong();
                }
            }
            return result;
        }
        public char[][] nextVerticalCharArrays(int arrayCount,
                                               int arrayLength) {
            char[][] result = new char[arrayCount][arrayLength];
            for (int i = 0; i < arrayLength; i++) {
                for (int j = 0; j < arrayCount; j++) {
                    result[j][i] = nextChar();
                }
            }
            return result;
        }
    }
