	private int sieve[];
	private Set<Integer> primeSet = new HashSet<>();

	EratosSieve(int x) {
		//篩の作成
		sieve = new int[x + 1];
		sieve[0] = sieve[1] = -1;
		for (int i = 2; i <= x; i++) {
			if (sieve[i] > 0)
				continue;
			for (int j = i + i; j <= x; j += i) {
				sieve[j] = i;
			}
		}
		//素数Setの作成
		Set<Integer> primeSet = new HashSet<>();
		for (int i = 2; i < sieve.length; i++) {
			if (sieve[i] == 0)
				primeSet.add(sieve[i]);
		}
	}

	//0~xまでの篩の配列を返す。配列値は素数なら0。素数でなければ、最大の素因数。(0,1は素数でないので-1)
	int[] getSieve() {
		return sieve;
	}

	//0~xまでの、素数のSetを返す
	Set<Integer> getPrimeSet() {
		return primeSet;
	}

	//素数判定
	boolean isPrime(int x) {
		return sieve[x] == 0;
	}

	//xの素因数分解結果をmapで返す(1は含まない)
	Map<Integer, Integer> primeFactrization(int x) {
		Map<Integer, Integer> map = new HashMap<>();
		while (sieve[x] > 0) {
			map.put(sieve[x], map.getOrDefault(sieve[x], 0) + 1);
			x /= sieve[x];
		}
		map.put(x, map.getOrDefault(x, 0) + 1);
		return map;
	}
}

