public class Main {
    static InputStream is;
    static PrintWriter out;
    static String INPUT = "";

    static void solve()
    {
        int N = ni();
        List<Integer> primes = sieveOfEratosthenes((int) Math.sqrt(N) + 3);
        Map<Long, Integer> factors = new HashMap<>();
        for (int i = 1; i < N + 1; i++) {
            Map<Long, Integer> temp = primeFactorize(i, primes);
            for (long it : temp.keySet()) {
                if (factors.containsKey(it)) {
                    factors.put(it, factors.get(it) + temp.get(it));
                } else {
                    factors.put(it, temp.get(it));
                }
            }
        }
        long ans = 1;
        for (long it : factors.keySet()) {
            int cnt = factors.get(it);
            ans = ans * (1 + cnt) % 1000000007;
        }
        out.println(ans);
    }

    public static Map<Long, Integer> primeFactorize(long n, List<Integer> primes) {
        Map<Long, Integer> result = new HashMap<>();
        for (int p : primes) {
            if (n < p * (long) p) {
                break;
            }
            while (n % p == 0) {
                if (result.containsKey((long) p)) {
                    result.put((long) p, result.get((long) p) + 1);
                } else {
                    result.put((long) p, 1);
                }
                n /= p;
            }
        }
        if (n != 1) {
            if (result.containsKey(n)) {
                result.put(n, result.get(n) + 1);
            } else {
                result.put(n, 1);
            }
        }
        return result;
    }

    // Enumerate primes in [2, n] with O(n log log n)
    public static List<Integer> sieveOfEratosthenes(int n) {
         boolean[] isPrime = new boolean[n+1];
         Arrays.fill(isPrime, true);
         for (int i = 2; i * i <= n; i++) {
             if (isPrime[i]) {
                 for (int j = i + i; j <= n; j += i) {
                     isPrime[j] = false;
                 }
             }
         }
         List<Integer> primes = new ArrayList<>();
         for (int i = 2; i <= n; i++) {
             if (isPrime[i]) {
                 primes.add(i);
             }
         }
         return primes;
    }

    public static void main(String[] args) throws Exception
    {
        long S = System.currentTimeMillis();
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);

        solve();
        out.flush();
        long G = System.currentTimeMillis();
        tr(G-S+"ms");
    }

    private static boolean eof()
    {
        if(lenbuf == -1)return true;
        int lptr = ptrbuf;
        while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

        try {
            is.mark(1000);
            while(true){
                int b = is.read();
                if(b == -1){
                    is.reset();
                    return true;
                }else if(!isSpaceChar(b)){
                    is.reset();
                    return false;
                }
            }
        } catch (IOException e) {
            return true;
        }
    }

    private static byte[] inbuf = new byte[1024];
    static int lenbuf = 0, ptrbuf = 0;

    private static int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }

    private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private static double nd() { return Double.parseDouble(ns()); }
    private static char nc() { return (char)skip(); }

    private static String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b))){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private static char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private static char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private static int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private static int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

