	public static String numtoalpha(int i) {

		String alpha = "abcdefghijklmnopqrstuvwxyz";

		return alpha.substring(i, i + 1);

	}

	public static Map<Integer,Integer> primefactor(int n){

		Map<Integer,Integer> res = new TreeMap<Integer,Integer>();

		for (int i = 2; i*i <= n; i++) {

			//因数が見つかったら、割れなくなるまで割って記録。
			while(n%i==0) {

				if(res.containsKey(i)) {
					res.put(i,res.get(i)+1);
				}else {
					res.put(i,1);
				}

				n/=i;

			}

		}

		//素数のパターン、最後まで試さないとわからない。
		if(n != 1) res.put(n,1);

		return res;

	}

	public static int[] extgcd(int a, int b) {

		int x0 = 1;
		int x1 = 0;

		int y0 = 0;
		int y1 = 1;

		while (b != 0) {
			int q = a / b;
			int r = a % b;

			int x2 = x0 - q * x1;
			int y2 = y0 - q * y1;

			a = b;
			b = r;

			x0 = x1;
			x1 = x2;

			y0 = y1;
			y1 = y2;
		}

		return new int[] { a, x0, y0 };

	}

	static int gcd(int a, int b) {

		if (b == 0)
			return a;

		if (a < b) {
			int t = a;
			a = b;
			b = t;
		}

		return gcd(b, a % b);

	}

	static int lcm(int a, int b) {
		return a * b / gcd(a, b);
	}

	static void swap(int[] a) {
		int t;

		t = a[0];
		a[0] = a[1];
		a[1] = t;

		return;
	}

