    private static Map<Integer, Integer> getPf(int n) {
        for (int i = 2; i * i <= n; i++) {
            while (n % i == 0) {
                map.merge(i, 1, Integer::sum);
                n /= i;
            }
        }
        if (n != 1) {
            map.merge(n, 1, Integer::sum);
        }
        return map;
    }
