        int[] divisorList = new int[N];
        int mod = (int) (Math.pow(10, 9) + 7);
        long result = 1;
        for (int i = N; i >= 2; i--) {
            calcNumOfDivisor(i, divisorList);
        }
        for (int i = 0; i < divisorList.length; i++) {
            result = result * (divisorList[i] + 1) % mod;
        }

        System.out.println(result);
