	/*
	 * 素因数分解の値を返却する（重複も全て） (O(√N ))
	 */
	public static ArrayList<Long> primefactorization(long number) {
		ArrayList<Long> arr = new ArrayList<Long>();
		for (long i = 2; i * i <= number; i++) {
			if (number % i == 0) {
				while (number % i == 0) {
					arr.add(i);
					number /= i;
				}
			}
		}
		// 最後に残った数について
		if (number != 1) {
			arr.add(number);
		}

		return arr;
	}

