public class Main {

	public static void main(String[] args) {
		new Main();
	}

	public Main() {
		FastIO io = new FastIO();
		solve(io);
		io.flush();
	}

	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * 考察メモ
		 * 各素因数について個数を求める
		 * 後はその個数の総積が答えとなる
		 * 各素因数についての個数はルジャンドルの定理を用いれば求められる
		 */
		int N = io.nextInt();
		BitSet prime = prime(N); // 素数
		ModInteger ans = new ModInteger(1000000007, 1);
		for (int i = 2;i <= N;++ i) {
			if (prime.get(i)) { // もしiが素数なら
				int count = 0; // その素因数の個数
				for (long j = i;j <= N;j *= i) count += N / j; // 計算量はO(logN) 慣らしO(1)な気もする……
				ans.multiplyEqual(count + 1); // 約数の個数の式より
			}
		} // 素因数の個数はO(N/logN)程度なのでO(N)には収まってるよ
		io.println(ans);
	}

	private static BitSet prime(int N) { // 素数列挙、もしSieve of Atkinを用いればO(N/loglogN)
		BitSet prime = new BitSet(N + 1);
		prime.flip(2, N + 1);
		for (int i = 2;i <= N;++ i) if (prime.get(i)) for (int j = i + i;j <= N;j += i) prime.set(j, false);
		return prime;
	}

