  static int n;

  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    n = sc.nextInt();

    boolean[] prime = new boolean[n + 1];
    int count = 0;
    Arrays.fill(prime, true);
    prime[1] = false;
    for(int i = 2; i <= n; i++){
      if(prime[i]){
        for(int j = 2; j * i <= n; j++){
          prime[j * i] = false;
        }
        ++count;
      }
    }

    int[] primes = new int[count];
    int sp = 0;
    for(int i = 2; i <= n; i++){
      if(prime[i]){
        primes[sp++] = i;
      }
    }

    int[] expo = new int[n + 1];
