        while(p <= m && m % p == 0){
          m /= p;
          ++expo[p];
        }
      }
    }

    long ans = 1;
    for(int i = 2; i <= n; i++){
      ans = (ans * (expo[i] + 1)) % MOD;
    }

    System.out.println(ans);
  }
}

