            int n = nint(sc);
            long D = (long) 10E8 + 7;
            long count = 1 ;
            Map<Integer, Integer> r = new HashMap<>();
            for (int i = 2; i <= n ; i++) {
                Map<Integer, Integer> m = primeFactorize(i);
                for (Map.Entry<Integer, Integer> e : m.entrySet()){
