public class Main {

	public static long count(int p, int n) {
		long count = 0;
		for(int i = 1; Math.pow(p,  i) <= n; ++i) {
			count += (n / Math.pow(p, i));
		}
		return (count + 1);
	}

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		long ans = 1;
		int n;
		n = sc.nextInt();
