		prime[1] = -1;
		for(int i = 2; i <= 1000; ++i) {
			if(prime[i] != -1) {
				prime[i] = 1;
				for(int j = 2; j * i <= 1000; ++j) {
					prime[i * j] = -1;
				}
			}
		}

		for(int i = 2; i <= n; ++i) {
			if(prime[i] == 1) {
				long tmp = count(i, n);
				ans *= (tmp % (long)(Math.pow(10,  9) + 7));
