namespace Library
{
    class Factorization
    {
        private List<long> factors;

        public List<long> GetFactors(long n)
        {
            //[summary]ある数を素因数分解する

            //別の数を素因数分解することもあるので、最初にかならず初期化
            factors = new List<long>();

            if (n < 2)
            {
                //2より小さい数を受け取った場合
                factors.Add(n);
            }
            else
            {
                Factoring(n);
            }

            return factors;
        }

        private void Factoring(long n)
        {
            //[summary]平方根以下の素数で総当りで割って行く
            //以下リンクを参考に実装
            //https://qiita.com/gushwell/items/561afde2e00bf3380c98

            //平方根を求める
            long sqrt = (long)Math.Sqrt(n);

            //2,3,5で割る(割れなくなるまで割り続ける)
            n = DevideWith(n, 2);
            n = DevideWith(n, 3);
            n = DevideWith(n, 5);

            var primes = new List<int> { 7, 11, 13, 17, 19, 23, 29, 31 };
            long i = 0;

            //平方根以下の素数(候補)で総当りで割る
            while (n > 1)
            {
                foreach (var p in primes)
                {
                    if (p + i > sqrt)
                    {
                        if (n > 1)
                        {
                            factors.Add(n);
                        }

                        return;
                    }
                    else
                    {
                        n = DevideWith(n, p + i);
                    }
                }

                i += 30;
            }
        }

        private long DevideWith(long n, long d)
        {
            while (n % d == 0)
            {
                factors.Add(d);
                n /= d;
            }

