        private const long MOD = 1000000007;

        static void Solve()
        {
            int n = ReadAndParseInt();

            var primeTable = new long[n + 1];

            for(int i=1;i<=n;++i)
            {
                CalcPrimes(i, primeTable);
            }

            long ans = 1;
            for(int i=2;i<primeTable.Length;++i)
            {
                long total = primeTable[i];
                if( total == 0) { continue; }
                ans = ans * (total + 1) % MOD;
            }
            Console.WriteLine(ans);
        }
        private static void CalcPrimes(int n, long[] primeTable)
        {
            int m = n;
            for(int i=2;i*i<=n;++i)
            {
                while (m % i == 0)
                {
                    m /= i;
                    primeTable[i]++;
                }
            }
            primeTable[m]++;
        }

        #region よく使う便利関数
        private static bool isPrime(long x)
        {
            if (x == 2) { return true; }
            if (x < 2 || x % 2 == 0) { return false; }
            long i = 3;
            while (i * i <= x)
            {
                if (x % i == 0) { return false; }
                i = i + 2;
            }
            return true;
        }
        private static long lcm(long x, long y)
        {
            return x / gcd(x, y) * y;
        }
        private static long gcd(long x, long y)
        {
            return y > 0 ? gcd(y, x % y) : x;
        }
        private static long pow(long x, long n)
        {
            if (n == 0) { return 1; }
            long res = pow(x * x % MOD, n / 2);
            if (n % 2 == 1)
            {
                res = res * x % MOD;
            }
            return res;
        }
