        {
            UInt64 i = 2;
            while (i * i <= n)
            {
                if (n % i == 0)
                {
                    n /= i;
                    if (dic.ContainsKey(i)) dic[i]++;
                    else dic.Add(i, 1);
                }
                else
                {
                    i++;
                }
            }
            if (n != 1) 
            {
                if (dic.ContainsKey(n)) dic[n]++;
                else dic.Add(n, 1);
            }
        }
    }
