    public sealed class Program : BaseProgram
    {
        public static void Main(string[] _) { using (var sc = new SetConsole()) { Solve(); } }
        public static void Solve()
        {
            var n = GetNumber<int>();
            var dic = new Dictionary<int, int>();
            for (int i = 2; i <= n; i++)
            {
                foreach (var item in Factorize(i))
                {
                    if (dic.ContainsKey((int)item.Item1))
                    {
                        dic[(int)item.Item1] += item.Item2;
                    }
                    else
                    {
                        dic.Add((int)item.Item1, item.Item2);
                    }
                }
            }
            var count = 1L;
            foreach (var key in dic.Keys)
            {
                count *= dic[key] + 1;
                count %= divisor;
            }            

            Write(count);
        }

        public static IEnumerable<Tuple<long, int>> Factorize(long n)
        {
            var rootN = Sqrt(n);
            for (long i = 2; i <= rootN; i++)
            {
                if (n % i != 0) { continue; }

                var count = 1;
                n /= i;
                while (n % i == 0)
                {
                    n /= i;
                    count++;
                }
                yield return Tuple.Create(i, count);
            }
            if (n != 1) { yield return Tuple.Create(n, 1); }
        }
    }

