class Program
{
    public static Queue<int>Factors(int a)
    {
        Queue<int> r = new Queue<int>();
        if (a <= 1)
            return r;
        while ((a & 1) == 0)
        {
            r.Enqueue(2);
            a >>= 1;
        }
        for (int i = 3; a != 1; i += 2)
        {
            while (a % i == 0)
            {
                r.Enqueue(i);
                a /= i;
            }
        }
        return r;
    }
    public static void Main()
    {
        int N = int.Parse(Console.ReadLine());
        int[] factors = new int[N + 1];
        for(int i = 2; i <= N; i++)
        {
            var t = Factors(i);
            while(t.Count>0)
                factors[t.Dequeue()]++;
        }

        FiniteField d = new FiniteField(1);
        for (int i = 2; i <= N; i++)
        {
            d *= new FiniteField(factors[i] + 1);
        }
        Console.WriteLine(d.ToString());
    }
}

