        {
            const long MOD = 1000000007;
            var N = cin.ReadInt;

            var map = new int[1001];
            for (int i = 2; i <= N; ++i)
            {
                var n = i;
                for (int j = 2; j <= n; ++j)
                    while (n != 0 && n % j == 0) { n /= j; map[j]++; }
            }
