    {
        static long mod = 1000000007;
        static void Main()
        {
            Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Console.Out.Flush();
            Console.ReadKey();
        }

        ///ここから

        static long N;

        static void Solve()
        {
            N = GetLong();
            var dic = new Dictionary<int, int>();
            Enumerable.Range(2, 999).ToList().ForEach(f => dic.Add(f, 0));
            for(int i = 2; i <= N; i++)
            {
                Factoring(i).ToList().ForEach(f => dic[f.Key] += f.Value);
            }
            long ans = 1;
            dic.Values.Select(s => s + 1).ToList().ForEach(f => ans = ans * f % mod);

            Console.WriteLine(ans);
        }

        //素因数分解
        //O(2√N/logN)
        static public Dictionary<int, int> Factoring(int num)
        {
            Dictionary<int, int> vs = new Dictionary<int, int>();
            if (num == 1) { vs.Add(1, 1); return vs; }
            while (num % 2 == 0)
            {
                if (vs.ContainsKey(2) == false) { vs.Add(2, 0); }
                vs[2]++;
                num /= 2;

            }
            if (num == 1)
            {
                return vs;
            }
            int i = 3;
            while (i <= Math.Sqrt(num))
            {
                if (num % i == 0)
                {
                    if (vs.ContainsKey(i) == false) { vs.Add(i, 0); }
                    vs[i]++;
                    num /= i;
                }
                else
                {
                    i += 2;
                }
            }
            if (vs.ContainsKey(num) == false) { vs.Add(num, 1); }
            else { vs[num]++; }

            return vs;
        }

    }

