            for (long p = 2; p * p <= n; p++)
            {
                int count = 0;
                while (n % p == 0)
                {
                    count++;
                    n /= p;
                }

                if (count != 0) map.Add(p, count);
            }

            if (n > 1) map.Add(n, 1);

