            for (long i = 0; i < n; i++)
            {
                for (int j = 0; j < m; j++)
                {
                    kore[i, j] = Char();
                }
            }
            return kore;
        }
        public string Scan()
        {
            var sb = new StringBuilder();
            for (var b = Char(); b >= 33 && b <= 126; b = (char)read())
                sb.Append(b);
            return sb.ToString();
        }
        public string[]Scan(long n)
        {
            string[] str = new string[n];
            for (long i = 0; i < n; i++)
            {
                str[i] = Scan();
            }
            return str;
