    class Program
    {
        class CountedHashSet
        {
            public class Counter
            {
                public Counter()
                {
                    count = 1;
                }

                public int count { get; set; }
            }


            public Dictionary<int, Counter> keySet;

            public CountedHashSet()
            {
                keySet = new Dictionary<int, Counter>();
            }

            public void Add(int key)
            {
                Counter c;

                if (keySet.TryGetValue(key, out c))
                {
                    c.count++;
                }
                else
                {
                    keySet.Add(key, new Counter());
                }
            }

            public int GetKeyCount(int key)
            {
                Counter c;

                if (keySet.TryGetValue(key, out c))
                {
                    return c.count;
                }

                return 0;
            }
        }
        public static List<int> PrimeFactors(int n)
        {
            int i = 2;
            List<int> result = new List<int>();

            while (i * i <= n)
            {
                if (n % i == 0)
                {
                    n /= i;
                    result.Add(i);
                }
                else
                {
                    i++;
                }
            }

            if (n != 1)
            {
                result.Add(n);
            }

            return result;
        }

        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());

            CountedHashSet hs = new CountedHashSet();

            for (int i = N; i > 0; i--)
            {
                List<int> pf = PrimeFactors(i);
                foreach(int e in pf)
                {
                    hs.Add(e);
                }
            }

            int ans = 1;
            foreach(KeyValuePair<int,CountedHashSet.Counter> ks in hs.keySet)
            {
                ans = (int)(Math.BigMul(ans, ks.Value.count + 1) % 1000000007);
            }

            Console.WriteLine(ans);
        }
    }
}

