class Program
{
    public const long mod = 1000000007;

    static void Main(string[] args)
    {
        // 入力
        var n = long.Parse(Console.ReadLine());
        long ans = 1;
        var dic = new Dictionary<long, long>() { };
        for (long i = 0; i < n - 1; i++)
        {
            long[] f = PrimeFactors(n - i).ToArray();

            for (int k = 0; k < f.Length; k++)
            {
                if (!dic.ContainsKey(f[k]))
                {
                    dic.Add(f[k], 1);
                }
                else
                {
                    dic[f[k]]++;
                }
            }
        }

        foreach (var item in dic)
        {
            ans *= (item.Value + 1);
            ans %= mod;
        }

        ans = ans % mod;

        // 出力
        Console.WriteLine(ans);
    }

    //素因数分解
    public static IEnumerable<long> PrimeFactors(long n)
    {
        long i = 2;
        long tmp = n;

        while (i * i <= n) //※1
        {
            if (tmp % i == 0)
            {
                tmp /= i;
                yield return i;
            }
            else
            {
                i++;
            }
        }
        if (tmp != 1) yield return tmp;//最後の素数も返す
    }
}

using System;

class NumberTheory {
    public static int[] Sieve(int m) {
        var minFactor = new int[m + 1];
        var nextPrime = minFactor;
        int previousPrime = 0;
        for (int i = 2; i <= m; ++i) {
            int currentMinFactor = minFactor[i];
            if (currentMinFactor == 0) {
                currentMinFactor = i;
                previousPrime = nextPrime[previousPrime] = i;
            }
            for (int prime = 2; i * prime <= m; prime = nextPrime[prime]) {
                minFactor[i * prime] = prime;
                if (prime >= currentMinFactor) break;
            }
        }
        nextPrime[previousPrime] = m + 1;
        return minFactor;
    }
}

class C {
    public static void Main() {
        var n = int.Parse(Console.ReadLine());
        var sieve = NumberTheory.Sieve(n);
        var p = new int[n + 1];
        for (int i = 2; i <= n; ++i) {
            int m = i;
            while (sieve[m] < m) {
                ++p[sieve[m]];
                m /= sieve[m];
            }
            ++p[m];
        }
        var answer = 1L;
        for (int i = 2; i <= n; ++i)
            answer = answer * (1 + p[i]) % 1000000007L;
        Console.WriteLine(answer);
    }
}

