    public static Dictionary <T1, T2> MERGE <T1, T2>(Dictionary <T1, T2> xs, Dictionary <T1, T2> ys) => xs.Except(xs.Join(ys, z => z.Key, z => z.Key, (a, b) => a)).Concat(ys).ToDictionary(z => z.Key, z => z.Value);
