using System;
using System.Collections.Generic;

class Program
{
    static string InputPattern = "InputX";

    static List<string> GetInputList()
    {
        var WillReturn = new List<string>();

        if (InputPattern == "Input1") {
            WillReturn.Add("3");
            //4
        }
        else if (InputPattern == "Input2") {
            WillReturn.Add("6");
            //30
        }
        else if (InputPattern == "Input3") {
            WillReturn.Add("1000");
            //972926972
        }
        else {
            string wkStr;
            while ((wkStr = Console.ReadLine()) != null) WillReturn.Add(wkStr);
        }
        return WillReturn;
    }

    static void Main()
    {
        List<string> InputList = GetInputList();

        int N = int.Parse(InputList[0]);

        Eratosthenes(N);

        int[] JyousuuArr = new int[SosuuArr.GetUpperBound(0) + 1];

        for (int I = 2; I <= N; I++) {
            int CopiedI = I;
            for (int J = 0; J <= SosuuArr.GetUpperBound(0); J++) {
                if (CopiedI % SosuuArr[J] == 0) {
                    do {
                        JyousuuArr[J]++;
                        CopiedI /= SosuuArr[J];
                    } while (CopiedI % SosuuArr[J] == 0);
                }
                if (CopiedI == 1) break;
            }
        }
        long Answer = 1;
        foreach (int EachInt in JyousuuArr) {
            if (EachInt == 0) continue;
            Answer = (Answer * (EachInt + 1)) % 1000000007;
        }
        Console.WriteLine(Answer);
    }

    static int[] SosuuArr;

    //エラトステネスの篩
    static void Eratosthenes(int pJyougen)
    {
        var IsSosuuArr = new System.Collections.BitArray(pJyougen + 1);

        for (int I = 2; I <= IsSosuuArr.Count - 1; I++) {
            IsSosuuArr[I] = true;
        }
        for (int I = 2; I <= IsSosuuArr.Count - 1; I++) {
            if (I != 2 && I % 2 == 0) continue;

            if (IsSosuuArr[I]) {
                for (int J = I * 2; J <= IsSosuuArr.Count - 1; J += I) {
                    IsSosuuArr[J] = false;
                }
            }
        }
        var SosuuList = new List<int>();
        for (int I = 2; I <= IsSosuuArr.Count - 1; I++)
            if (IsSosuuArr[I]) SosuuList.Add(I);

        SosuuArr = SosuuList.ToArray();
    }
}

