    class Program
    {
        static IO.StreamScanner _scanner = new IO.StreamScanner(Console.OpenStandardInput());

        static void Main(string[] args)
        {
            var n = _scanner.Integer();
            var f = GetFactPows(n);
            var ret = 1L;
            foreach(var e in f)
            {
                ret *= (e + 1);
                ret %= 1000000007L;
            }
            IO.Printer.Out.WriteLine(ret);
            IO.Printer.Out.Flush();
        }

        static List<int> GetFactPows(int n)
        {
            var dict = new Dictionary<int, int>();
            for (int i = 2; i <= n; i++)
            {
                var pFact = GetPrimeFact(i);
                foreach (var k in pFact.Keys)
                {
                    if (!dict.ContainsKey(k)) dict[k] = 0;
                    dict[k] += pFact[k];
                }
            }

            return dict.Values.ToList();
        }

        static Dictionary<int, int> GetPrimeFact(int n)
        {
            var ret = new Dictionary<int, int>();
            for (int d = 2; d * d <= n; d++)
            {
                while (n % d == 0)
                {
                    if (!ret.ContainsKey(d)) ret[d] = 0;
                    ret[d]++;
                    n /= d;
                }
            }
            if(n != 1)
            {
                if (!ret.ContainsKey(n)) ret[n] = 0;
                ret[n]++;
            }
            return ret;
        }
    }

