	public class Solver : SolverBase
	{
		public void Run() {
			var N = ReadInt();

			var dic = new Dictionary<long, int>();
			for (int i = 1; i <= N; i++) {
				foreach (var f in Factoring(i)) {
					if (!dic.ContainsKey(f)) {
						dic.Add(f, 1);
					} else {
						dic[f]++;
					}
				}
			}
			int ans = 1;
			foreach (var kv in dic) {
				//Dump($"{kv.Key}: {kv.Value}");

				// N個から 0-N 個選択する
				// 1 -> 2通り
				// 2 -> 3通り
				// 3 -> 4通り
				ans = Modulo.Mul(ans, kv.Value+1);
			}

			WriteLine(ans);
		}

