using System;
using System.Linq;
using System.Collections.Generic;
using System.Numerics;
using static System.Console;

class Solver {
    Scanner sc = new Scanner();

    public void Solve() {
        int N = sc.nextInt();

        if (N == 1) {
            WriteLine(1);
            return;
        }

        var prime = GeneratePrime(N);
        var n = new List<int>();
        for (int i = 1; i <= N; i++) {
            n.Add(i);
        }

        var cnt = new int[prime.Count];
        for (int i = 0; i < prime.Count; i++) {
            cnt[i] = 1;
        }
        for (int i = 0; i < prime.Count; i++) {
            for (int j = 0; j < n.Count; j++) {
                var hoge = n[j];
                while (hoge % prime[i] == 0) {
                    cnt[i]++;
                    hoge /= prime[i];
                }
            }
        }

        long ans = 1;
        for (int i = 0; i < cnt.Length; i++) {
            ans = ans * cnt[i] % 1000000007;
        }

        WriteLine(ans);
    }

    public static List<int> GeneratePrime(int max) {
        int prime;
        double sqrtMax = Math.Sqrt(max);
        var primeList = new List<int>();

        var searchList = Enumerable.Range(2, max - 1).ToList();

        do {
            prime = searchList.First();
            primeList.Add(prime);
            searchList.RemoveAll(n => n % prime == 0);
        } while (prime < sqrtMax);

        primeList.AddRange(searchList);
        return primeList;
    }
}



