using System;
using System.Linq;
using System.Collections.Generic;

namespace Algorithm
{
    class Program
    {
        const int Mod = 1000000007;
        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var dict = new Dictionary<int, int>();

            for (var i = 2; i <= n; i++)
            {
                var tmp = i;
                var t = 0;
                var count = 2;

                while (count <= i)
                {
                    if (tmp % count == 0)
                    {
                        t++;
                        tmp /= count;
                    }
                    else
                    {
                        if (t != 0)
                        {
                            if (dict.ContainsKey(count))
                                dict[count] += t;
                            else
                                dict[count] = t;
                        }
                        count++;
                        t = 0;
                    }
                }
            }

            var total = 1L;
            foreach (var d in dict)
            {
                // 約数求める時は次数＋１しないとだから＋１する
                total *= d.Value + 1;
                total %= Mod;
            }

            Console.WriteLine(total);
        }
    }
}

