    public class FactorsOfFactorial
    {
        static void Main()
        {
            int N = int.Parse(Console.ReadLine());
            Dictionary<int, int> count = new Dictionary<int, int>(); // 素数xが何個あるか
            int mod = 1000000007;

            for (int i = 1; i <= N; i++) // N!... 1*2*3*4*...N
            {
                List<int> factorList = PrimeFactor(i); // 素因数分解
                foreach (var f in factorList) // 素数をカウント
                {
                    // Dictionaryに記録
                    if (count.ContainsKey(f))
                    {
                        count[f] += 1;
                    }
                    else
                    {
                        count.Add(f, 1);
                    }
                }
            }

            int ans = 1;
            foreach (var c in count)
            {
                if (c.Key == 1) continue;
                ans *= (c.Value + 1) % mod;
                ans %= mod;
            }

            Console.WriteLine(ans);
        }

        // 素因数分解
        static List<int> PrimeFactor(int n)
        {
            List<int> result = new List<int>();
            for (int i = 2; i * i <= n; i++)
            {
                while (n % i == 0)
                {
                    result.Add(i);
                    n /= i;
                }
            }
            result.Add(n);
            return result;
        }
    }
