public class Contest
{
	public static void Main()
	{
        int n;

		MyIO.ReadMulti(out n);

		long[] d = Enumerable.Repeat(1L, 1001).ToArray();
		for(int i=2;i<=n;i++){
			long[] f = PrimeFactor(i);
			foreach(var k in f) d[k]++;
		}
		long ans = 1;
		for (int i = 2; i <=1000;i++)	ans = (ans*d[i])%1000000007;
		MyIO.WriteMulti(ans);
	}


    public static long[] PrimeFactor(long n) {
		List<long> ret = new List<long>();

        if (n < 2) return ret.ToArray();

        while ((n & 1) == 0) {
			ret.Add(2);
			n >>= 1;
		}
        while ((n % 3) == 0) {
			ret.Add(3);
			n /= 3;
		}

        long sqrt = (long)Math.Sqrt(n);
        for (long i = 5, f = 2; i <= sqrt; i += f, f ^= 6) {
            while ((n % i) == 0) {
				ret.Add(i);
				n /= i;
			}
        }
		if(1<n) ret.Add(n);

        return ret.ToArray();
    }

