using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

class Program
{
    static void Main(string[] args)
    {
        int mod = 1000000000 + 7;
        var N = ConsoleUtil.IntReadLine();


        var primes = GetPrimeNumbers().TakeWhile(n => n <= N).ToArray();
        var counter = new int[primes.Length];

        for(int i = 1; i <= N; i++)
        {
            Count(i, primes, counter);
        }

        int ans = 1;

        for(int i = 0; i < counter.Length; i++)
        {
            ans *= (counter[i] + 1);
            ans %= mod;
        }

        Console.WriteLine(ans);
    }

    static void Count(int n, int[] primes, int[] counter)
    {
        for(int i = 0; i < primes.Length; i++)
        {
            int nCpy = n;
            int prime = primes[i];

            while(nCpy % prime == 0)
            {
                nCpy /= prime;
                counter[i]++;
            }
        }
    }

    static IEnumerable<int> GetPrimeNumbers()
    {
        List<int> primes = new List<int>() { 2 };

        yield return 2;

        for (int i = 3; i < int.MaxValue; i++)
        {
            bool isPrime = true;
            int Sqrt = (int)Math.Sqrt(i) + 1;

            foreach (var prime in primes)
            {
                if (prime > Sqrt)
                {
                    break;
                }
                if (i % prime == 0)
                {
                    isPrime = false;
                    break;
                }
            }

            if (isPrime)
            {
                primes.Add(i);
                yield return i;
            }
        }
    }
}



