	static class Program
	{
		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			ModInt ans = 1;
			var d = new Dictionary<int, int>();
			var prime = new List<int>();
			for (int i = 2; i <= n; i++)
			{
				bool ok = true;
				for (int j = 0; j < prime.Count && prime[j] * prime[j] <= i; j++)
				{
					if (i % prime[j] == 0) ok = false;
				}
				if (ok) prime.Add(i);
			}

			foreach (var e in prime)
			{
				d.Add(e, 0);
			}

			for (int i = 1; i <= n; i++)
			{
				int k = i;
				foreach (var e in prime)
				{
					// if (e * e > i) break;
					while(k % e == 0)
					{
						k /= e;
						d[e]++;
					}
				}
			}

			foreach (var e in d)
			{
				ans *= e.Value + 1;
			}
			Console.WriteLine(ans);
		}

