        {
            long N = int.Parse(Console.ReadLine());
            Dictionary<long, long> count = new Dictionary<long, long>(); // 素数xが何個あるか
            long mod = 1000000007;

            for (long i = 2; i <= N; i++) // N!... 1*2*3*4*...N
            {
                List<long> factorList = PrimeFactor(i); // 素因数分解
                foreach (var f in factorList) // 素数をカウント
                {
                    // Dictionaryに記録
                    if (count.ContainsKey(f))
                    {
                        count[f] += 1;
                    }
                    else
                    {
                        count.Add(f, 1);
                    }
                }
            }

            long ans = 1;
            foreach (var c in count)
            {
                ans *= (c.Value + 1) % mod;
                ans %= mod;
            }

            Console.WriteLine(ans);
        }

        // 素因数分解
        static List<long> PrimeFactor(long n)
        {
            List<long> result = new List<long>();
            for (long i = 2; i * i <= n; i++)
            {
                while (n % i == 0)
                {
                    result.Add(i);
                    n /= i;
                }
            }
            if (n != 1) result.Add(n);
            return result;
        }
    }
}

