        {
        divideNum[j-1] ++;//素因数を加算
        ii /= j;
          if(ii == 1) break;
        }
      }
    }

    for(int i = 0; i < n; i++)
    {
    answer *= divideNum[i];
    answer %= 1000000007;
    }

