        }
        static long Mod = (long)1e9 + 7;
        public static void Main(string[] args)
        {
            //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            //Out.Flush();
            Read();
        }
        static void Solve()
        {
            var N = Sarray()[0];
            var dct = new Dictionary<long, long>();
            for (var i = 1; i <= N; ++i)
                dct = primefactorize(i, dct);
            var ans = 1L;
            foreach (var d in dct)
                ans = ans * (d.Value + 1) % Mod;
            WriteLine(ans);

        }
        static Dictionary<long, long> primefactorize(long n, Dictionary<long, long> primes)
        {
            for (long i = 2L; i * i <= n; ++i)
            {
                while (n % i == 0)
                {
                    if (!primes.ContainsKey(i)) primes[i] = 0;
                    ++primes[i];
                    n /= i;
                }
            }
            if (n != 1)
            {
                if (!primes.ContainsKey(n)) primes[n] = 0;
                ++primes[n];
            }
            return primes;
        }
    }
}

