namespace ABC052C
{
    class Program
    {
        static readonly int Mod = 1000000007;

        static void Main(string[] args)
        {
            uint n = UInt32.Parse(Console.ReadLine());
            int[] sups = new int[n + 1];
            for(int i = 2; i <= n; i++)
            {
                sups[i] = 1;
            }

            long res = 1;

            for (int i = 2; i <= n; i++)
            {
                int j = i;
                int k = 2;
                while (j > 1)
                {
                    if (j % k == 0)
                    {
                        sups[k]++;
                        j /= k;
                    }
                    else
                    {
                        k = NextPrime(k);
                    }
                }
            }

            for (int i = 2; i <= n; i++)
            {
                res = (res * sups[i]) % Mod;
            }

            Console.WriteLine(res);
            return;
        }

        static bool IsPrime(int num)
        {
            if ((num > 2) && ((num % 2) == 0)) return false;
            for (int i = 3; i <= (num / 3); i += 2)
            {
                if (num % i == 0)
                {
                    return false;
                }
            }
            return true;
        }

        static int NextPrime(int num)
        {
            int i = num + 1 + (num % 2);
            while (!IsPrime(i))
            {
                i += 2;
            }
            return i;
        }

    }
}

