using System;
using System.Collections;
class Program
{
	private static Hashtable sosu;
	static void Main(string[] args)
	{
		int input = int.Parse(Console.ReadLine());
		sosu = new Hashtable();
		AddSosu(input);
		double answer = CountSosu() % (Math.Pow(10,9) + 7);
		Console.WriteLine(answer);
	}

	static void AddSosu(int num){
		if(num == 1) return;

		int origin = num;
		for(int i=2; i<=origin; i++){
			while(num % i == 0){
				if(sosu[i] == null)
					sosu[i] = 0;

				sosu[i] = (int)sosu[i] + 1;

				num /= i;
			}
		}
		AddSosu(origin - 1);
	}
	static double CountSosu(){
		double result = 1;
		foreach (int item in sosu.Values)
		{
			result *= (1+item);
		}
		return result;
	}
}

using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        var p = MakePList(n);
        var a = new int[n + 1];
        for (int i = 2; i <= n; i++)
        {
            for (int j = 0; j < p.Count(); j++)
            {
                int x = i;
                while (x % p[j] == 0)
                {
                    a[p[j]]++;
                    x /= p[j];
                }
            }
        }
        long ans = 1;
        for (int i = 0; i <= n; i++)
        {
            ans *= a[i] + 1;
            ans %= 1000000007;
        }
        Console.WriteLine(ans);
    }
    static List<int> MakePList(int n)
    {
        var ret = new List<int>();
        ret.Add(2);
        for (int i = 3; i <= n; i += 2)
        {
            for (int j = 0; j < ret.Count(); j++)
            {
                if (i % ret[j] == 0) break;
                else if (j == ret.Count() - 1) ret.Add(i);
            }
        }
        return ret;
    }
}

