class Program
{
	private static Hashtable sosu;
	static void Main(string[] args)
	{
		sosu = new Hashtable();
		AddSosu(int.Parse(Console.ReadLine()));
		Console.WriteLine(CountSosu());
	}

	static void AddSosu(int num){
		if(num == 1) return;

		int origin = num;
		for(int i=2; i<=origin; i++){
			while(num % i == 0){
				if(sosu[i] == null)
					sosu[i] = 0;

				sosu[i] = (int)sosu[i] + 1;

				num /= i;
			}
		}
		AddSosu(origin - 1);
	}
	static UInt64 CountSosu(){
		UInt64 result = 1;
		foreach (int item in sosu.Values){
			result *= (UInt64)(1+item);
			result %= 1000000007;
		}
		return result;
	}
}

