    public static IEnumerable<int> PrimeFactors(int n)
    {
        int i = 2;
        int tmp = n;
        while (i * i <= n)
        {
            if (tmp % i == 0) { tmp /= i; yield return i; }
            else i++;
        }
        if (tmp != 1) yield return tmp;
    }
}

