public class Calculation
{
public static List<int> PrimeList(int length)
    {
        var primeList = new List<int> { 2 };
        for (int i = 3; i <= length; i += 2)
        {
            var isPrime = true;
            for (var j = 1; j * j < i; j++)
            {
                var prime = primeList[j - 1];
                if (i % prime == 0) { isPrime = false; break; }
            }
            if (isPrime) primeList.Add(i);
        }
        return primeList;
    }
}

using System;
