        public static IEnumerable<long> GetPrimeFactors(long n)
        {
            for (long a = 2; a * a <= n; ++a)
            {
                if (n % a != 0) continue;

                // 割れる限り割り続ける
                while (n % a == 0)
                {
                    yield return a;
                    n /= a;
                }

                // TODO：重複を許さない場合はここで返す
                //yield return a;

            }

            // 最後に残った数について
            if (n != 1) yield return n;
        }
