    public class Modular
    {
        public long Value { get; private set; }

        private static readonly long _mod = (long)Math.Pow(10, 9) + 7;
        private static readonly List<int> _facCache = new List<int> { 1 };

        public static explicit operator long(Modular m) => m.Value;
        public static implicit operator Modular(long a)
        {
            var m = a % _mod;

            return new Modular
            {
                Value = (m < 0) ? m + _mod : m
            };
        }

        public static Modular operator +(Modular a, Modular b) => a.Value + b.Value;
        public static Modular operator -(Modular a, Modular b) => a.Value - b.Value;
        public static Modular operator *(Modular a, Modular b) => a.Value * b.Value;
        public static Modular operator /(Modular a, Modular b) => a * Pow(b, _mod - 2);
        public static Modular Pow(Modular a, long n)
        {
            switch (n)
            {
                case 0:
                    return 1;
                case 1:
                    return a;
                default:
                    var p = Pow(a, n / 2);
                    return p * p * Pow(a, n % 2);
            }
        }
        public static Modular Factorial(long n)
        {
            for (int i = _facCache.Count; i <= n; ++i)
            {
                var fac = (int)(Math.BigMul(_facCache.Last(), i) % _mod);
                _facCache.Add(fac);
            }
            return _facCache[(int)n];
        }
        public static Modular Combination(long n, long r)
        {
            Modular ans = 1;
            for (var i = 0; i < r; i++)
            {
                ans *= n - i;
            }
            for (var i = 1; i <= r; i++)
            {
                ans /= i;
            }

            return ans;
        }
        public override string ToString()
        {
            return Value.ToString();
        }
    }
}

