func main() {
	var a, b, c, d, e, f int
	fmt.Scan(&a, &b, &c, &d, &e, &f)
	a *= 100
	b *= 100

	ansSugar := 0
	ansSolution := a
	for ai := 0; a*ai <= f; ai++ {
		for bi := 0; b*bi <= f; bi++ {
			for ci := 0; c*ci <= f; ci++ {
				for di := 0; d*di <= f; di++ {
					water := a*ai + b*bi
					sugar := c*ci + d*di
					solution := water + sugar
					if solution > f {
						continue
