					if sugar*(100+e) > e*solution {
						continue
					}
					if sugar*ansSolution > ansSugar*solution {
						ansSugar = sugar
						ansSolution = solution
					}
				}
			}
		}
	}
	fmt.Println(ansSolution, ansSugar)
}
