// Reads next token and return it as string
func reads() string {
	b, err := nextToken()
	if err != nil {
		panic(err)
	}
	return string(b)
}

// Read next line as string
func readsln() string {
	b, err := nextLine()
	if err != nil {
		panic(err)
	}

	return string(b)
}

// Reads next token and return it as int
func readi() int {
	i, err := strconv.ParseInt(reads(), 10, 64)
	if err != nil {
		panic(err.Error())
	}

	return int(i)
}

// Reads next token and return it as float64
func readf() float64 {
	f, err := strconv.ParseFloat(reads(), 64)
	if err != nil {
		panic(err.Error())
	}
	return f
}

// ReadIntSlice returns an integer slice that has n integers.
func readislice(n int) []int {
	b := make([]int, n)
	for i := 0; i < n; i++ {
		b[i] = readi()
	}
	return b
}

