func permutation(n int, k int) int {
    v := 1
    if 0 < k && k <= n {
        for i := 0; i < k; i++ {
            v *= (n - i)
			v %= MOD
        }
    } else if k > n {
        v = 0
    }
    return v
}

func factorial(n int) int {
    return permutation(n, n - 1)
}

// 12なら[[2,2], [3,1]]が返り値
func primeFactorize(res map[int]int, N int) {
	for a := 2; a * a <= N; a++{
		if N % a != 0 {
			continue
		}

		ex := 0

		for N % a == 0 {
			ex++
			N /= a
		}

		res[a] += ex
	}

	if N != 1 {
		res[N] += 1
	}
}

