import "fmt"

func main() {
	var n int
	fmt.Scan(&n)

	mm := make(map[int]int)
	for i := 2; i <= n; i++ {
		for k, v := range factorize(i) {
			mm[k] += v
		}
	}

	ans := 1
	for _, v := range mm {
		ans = (ans * (v + 1)) % (1e9 + 7)
	}
	fmt.Println(ans)
}

func factorize(n int) map[int]int {
	m := make(map[int]int)
	for n%2 == 0 {
		n /= 2
		m[2]++
	}

	for i := 3; i*i <= n; i += 2 {
		if n%i != 0 {
			continue
		}
		for n%i == 0 {
			n /= i
			m[i]++
		}
	}
	if n != 1 {
		m[n]++
	}
	return m
}

