import "fmt"

type Pair struct {
        First  int64
        Second int64
}

func prime_factorize(n int64) []Pair {
        res := make([]Pair, 0, 0)

        var p, num int64

        for p = 2; p*p <= n; p++ {
                if n%p != 0 {
                        continue
                }
                num = 0
                for n%p == 0 {
                        num++
                        n /= p
                }
                res = append(res, Pair{First: p, Second: num})
        }
        if n != 1 {
                res = append(res, Pair{First: n, Second: 1})
        }
        return res
}

// n! の約数の数を mod で割った余りを返す
func mod_div_fact(n, mod int64) int64 {
        var i int64
        mp := make(map[int64]int64)

        for i = 2; i <= n; i++ {
                s := prime_factorize(i)
                for _, value := range s {
                        p := value.First
                        e := value.Second
                        mp[p] += e
                }
        }
        var ret int64 = 1
        for key, value := range mp {
                if key == 1 {
                        continue
                }
                ret *= (value + 1)
                ret %= mod
        }
        return ret
}

