func createPrimes(n int) []bool {
  r := make([]bool, n+1)
  for i := 2; i <= n; i++ {
    r[i] = true
  }
  root := int(math.Sqrt(float64(n)))
  for i := 2; i <= root; i++ {
    for j := i+1; j <= n; j++ {
