int[] factorize(int n) {
    auto c = 2;
    auto res = new int[0];
    while (c <= n) {
        if (n % c == 0) {
            res ~= c;
            n /= c;
            continue;
        }
        c++;
    }
    if (n > 1) res ~= n;
    return res;
};

