def get_primes(n):
	primes = [True for i in range(n+1)]
	primes[0] = False
	primes[1] = False
	for i in range(2, n+1):
		if i*i > n:
			break
		if not primes[i]:
			continue
		for non_prime in range(2 * i, n+1, i):
			primes[non_prime] = False
	return [i for i, prime in enumerate(primes) if prime]


