class remainder():
    def __init__(self, mod=(10**9 + 7)):
        self.mod = mod

    def mul(self, a, b):
        return ((a % self.mod) * (b % self.mod)) % self.mod

    def pow(self, a, b):
        bp = []
        #bp.append(1)
        bp.append(a)

        n = len(bin(b)) - 2
        for x in range(n):
            bp.append(bp[x]**2 % self.mod)

        res = 1
        for x in range(n):
            if b >> x & 1:
                res = (res * bp[x]) % self.mod

        return res

    def div(self, a, b):

        return self.mul(a, self.pow(b, self.mod - 2))


