def prime_factorize(n):
    res = []
    p = 2
    while p*p <= n:
        if n % p != 0:
            p += 1
            continue
        num = 0
        while n % p == 0:
            num += 1
            n //= p
        res.append( [p, num] )
        p += 1

    if n != 1: res.append( [n, 1] )

    return res


# n! の約数の数を mod で割った余りを返す
def mod_div_fact(n, mod):
    d = {}
    for i in range(2, n+1):
        L = prime_factorize(i)
        for (p, e) in L:
            d[p] = d.get(p, 0) + e
    res = 1
    for v in d.values():
        res *= (v+1)
        res %= mod
    return res;

