import math
class MathAlgo(object):

    @classmethod
    def make_primes(cls, size):
        primes = []
        flag = [True for i in range(size)]
        limit = int(math.sqrt(size))

        for i in range(2, limit):
            if flag[i]:
                primes.append(i)
                for j in range(i, size, i):
                    flag[j] = False

        for i in range(limit, size):
            if flag[i]:
                primes.append(i)

        cls.primes = primes
        cls.prime_flag = flag
        return cls.primes

    @classmethod
    def prime_div(cls, N, primes):
        m = {1:1}
        while True:
            ok = False
            for i in range(len(primes)):
                if N%primes[i] == 0:
                    if primes[i] in m:
                        m[primes[i]] += 1
                    else:
                        m[primes[i]] = 1
                    N = N // primes[i]
                    break
                if primes[i] > N:
                    ok = True
                    break
            if ok:
                break
        cls.pd = m
        return cls.pd


