def get_prime_factor(n, primes):
    if n == 1:
        return (1, 1)
    res = []
    for p in primes:
        if p * p > n:
            break
        c = 0
        while not n % p:
            n //= p
            c += 1
        if c:
            res.append((p, c))
    if n != 1:
        res.append((n, 1))
    return res

