	ans = []
	num = n
	i = 2
	while i <= n**0.5:
		if num % i == 0:
			if len(ans) == 0 or ans[-1][0] != i:
				ans.append([i, 1])
			else:
				ans[-1][1] += 1
			num = num//i
		else:
			i+=1
	if num != 1:
		ans.append([num, 1])

	return ans

