    input = sys.stdin.readline
    N = int(input())
    MOD = 10**9 + 7

    if N == 1:
        return 1

    prime = sieve(N)
    d = defaultdict(lambda: 0)
    for i in range(2, N+1):
        m = i
        for p in prime:
            if p > m:
                break

            while m % p == 0:
                d[p] += 1
                m //= p

    ans = 1
    for key in d.keys():
        ans *= d[key] + 1

    return ans % MOD


