    modulo = 10**9+7
    for i in range(2, N+1):
        if len(divisors[i]) == 0: # if prime
            for j in range(i, N+1, i):
                divisors[j].append(i)
    counter = Counter()
    for i in range(1, N+1):
        j = 0
        temp = i
