fn factorial_2_prime_factorize(n: usize) -> HashMap<usize, usize> {
    let mut factors = HashMap::new();
    for i in 2..n + 1 {
        let mut a = 2;
        let mut temp_i = i;
        while a * a <= temp_i {
            while temp_i % a == 0 {
                let exp = factors.entry(a).or_insert(0);
                *exp += 1;
                temp_i /= a;
            }
            a += 1;
        }
        if temp_i != 1 {
            let exp = factors.entry(temp_i).or_insert(0);
            *exp += 1;
        }
    }
    factors
}
