pub struct Sieve {
    primes: Vec<usize>,
    tbl: Vec<usize>,
}
impl Sieve {
    pub fn new(n: usize) -> Sieve {
        let sz: usize = (n + 1) as usize;
        let mut primes = Vec::new();
        let mut tbl = vec![0; sz];
        tbl[0] = 0;
        tbl[1] = 0;
        for i in 2..sz {
            if tbl[i] != 0 {
                continue;
            }
            primes.push(i as usize);
            tbl[i] = i as usize;
            let mut j = i * i;
            while j < sz {
                if tbl[j] == 0 {
                    tbl[j] = i as usize;
                }
                j += i;
            }
        }
        Sieve { primes: primes, tbl: tbl }
    }
    pub fn primes(&self) -> &Vec<usize> {
        &self.primes
    }
    pub fn is_prime(&self, x: usize) -> bool {
        x > 1 && self.tbl[x as usize] == x
    }
    pub fn factorization(&self, x: usize) -> Vec<(usize, usize)> {
        let mut mx = x;
        let mut fl = Vec::new();
        while mx > 1 {
            let fx = self.tbl[mx as usize];
            fl.push(fx);
            mx /= fx;
        }
        if fl.is_empty() {
            return Vec::new();
        }
        let mut res = vec![(fl[0], 0)];
        for p in &fl {
            let l = res.len() - 1;
            let last = res[l];
            if last.0 == *p {
                res[l].1 += 1;
            } else {
                res.push((*p, 1));
            }
        }
        res
    }
}

